export default "ef test_delete_flow(client: AsyncClient, json_flow: str, logged_in_headers):\\n    flow = orjson.loads(json_flow)\\n    data = flow[\\\"data\\\"]\\n    flow = FlowCreate(name=\\\"Test Flow\\\", description=\\\"description\\\", data=data)\\n    response = await client.post(\\\"api/v1/flows/\\\", json=flow.model_dump(), headers=logged_in_headers)\\n    flow_id = response.json()[\\\"id\\\"]\\n    response = await client.delete(f\\\"api/v1/flows/{flow_id}\\\", headers=logged_in_headers)\\n    assert response.status_code == 200\\n    assert response.json()[\\\"message\\\"] == \\\"Flow deleted successfully\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"active_user\\\")\\nasync def test_delete_flows(client: AsyncClient, logged_in_headers):\\n    # Create ten flows\\n    number_of_flows = 10\\n    flows = [FlowCreate(name=f\\\"Flow {i}\\\", description=\\\"description\\\", data={}) for i in range(number_of_flows)]\\n    flow_ids = []\\n    for flow in flows:\\n        response = await client.post(\\\"api/v1/flows/\\\", json=flow.model_dump(), headers=logged_in_headers)\\n        assert response.status_code == 201\\n        flow_ids.append(response.json()[\\\"id\\\"])\\n\\n    response = await client.request(\\\"DELETE\\\", \\\"api/v1/flows/\\\", headers=logged_in_headers, json=flow_ids)\\n    assert response.status_code == 200, response.content\\n    assert response.json().get(\\\"deleted\\\") == number_of_flows\\n\\n\\n@pytest.mark.usefixtures(\\\"active_user\\\")\\nasync def test_delete_flows_with_transaction_and_build(client: AsyncClient, logged_in_headers):\\n    # Create ten flows\\n    number_of_flows = 10\\n    flows = [FlowCreate(name=f\\\"Flow {i}\\\", description=\\\"description\\\", data={}) for i in range(number_of_flows)]\\n    flow_ids = []\\n    for flow in flows:\\n        response = await client.post(\\\"api/v1/flows/\\\", json=flow.model_dump(), headers=logged_in_headers)\\n        assert response.status_code == 201\\n        flow_ids.append(response.json()[\\\"id\\\"])\\n\\n    class VertexTuple(NamedTuple):\\n        id: str\\n\\n    # Create a transaction for each flow\\n    for flow_id in flow_ids:\\n        await log_transaction(\\n            str(flow_id), source=VertexTuple(id=\\\"vid\\\"), target=VertexTuple(id=\\\"tid\\\"), status=\\\"success\\\"\\n        )\\n\\n    # Create a build for each flow\\n    for flow_id in flow_ids:\\n        build = {\\n            \\\"valid\\\": True,\\n            \\\"params\\\": {},\\n            \\\"data\\\": ResultDataResponse(),\\n            \\\"artifacts\\\": {},\\n            \\\"vertex_id\\\": \\\"vid\\\",\\n            \\\"flow_id\\\": flow_id,\\n        }\\n        await log_vertex_build(\\n            flow_id=build[\\\"flow_id\\\"],\\n            vertex_id=build[\\\"vertex_id\\\"],\\n            valid=build[\\\"valid\\\"],\\n            params=build[\\\"params\\\"],\\n            data=build[\\\"data\\\"],\\n            artifacts=build.get(\\\"artifacts\\\"),\\n        )\\n\\n    response = await client.request(\\\"DELETE\\\", \\\"api/v1/flows/\\\", headers=logged_in_headers, json=flow_ids)\\n    assert response.status_code == 200, response.content\\n    assert response.json().get(\\\"deleted\\\") == number_of_flows\\n\\n    for flow_id in flow_ids:\\n        response = await client.request(\\n            \\\"GET\\\", \\\"api/v1/monitor/transactions\\\", params={\\\"flow_id\\\": flow_id}, headers=logged_in_headers\\n        )\\n        assert response.status_code == 200\\n        json_response = response.json()\\n        assert json_response[\\\"items\\\"] == []\\n\\n    for flow_id in flow_ids:\\n        response = await client.request(\\n            \\\"GET\\\", \\\"api/v1/monitor/builds\\\", params={\\\"flow_id\\\": flow_id}, headers=logged_in_headers\\n        )\\n        assert response.status_code == 200\\n        assert response.json() == {\\\"vertex_builds\\\": {}}\\n\\n\\n@pytest.mark.usefixtures(\\\"active_user\\\")\\nasync def test_delete_folder_with_flows_with_transaction_and_build(client: AsyncClient, logged_in_headers):\\n    # Create a new project\\n    folder_name = f\\\"Test Project {uuid4()}\\\"\\n    project = FolderCreate(name=folder_name, description=\\\"Test project description\\\", components_list=[], flows_list=[])\\n\\n    response = await client.post(\\\"api/v1/projects/\\\", json=project.model_dump(), headers=logged_in_headers)\\n    assert response.status_code == 201, f\\\"Expected status code 201, but got {response.status_code}\\\"\\n\\n    created_folder = response.json()\\n    folder_id = UUID(created_folder[\\\"id\\\"])\\n\\n    # Create ten flows\\n    number_of_flows = 10\\n    flows = [FlowCreate(name=f\\\"Flow {i}\\\", description=\\\"description\\\", data={}) for i in range(number_of_flows)]\\n    flow_ids = []\\n    for flow in flows:\\n        flow.folder_id = folder_id\\n        response = await client.post(\\\"api/v1/flows/\\\", json=flow.model_dump(mode=\\\"json\\\"), headers=logged_in_headers)\\n        assert response.status_code == 201\\n        flow_ids.append(response.json()[\\\"id\\\"])\\n\\n    class VertexTuple(NamedTuple):\\n        id: str\\n        params: dict\\n\\n    # Create a transaction for each flow\\n    for flow_id in flow_ids:\\n        await log_transaction(\\n            str(flow_id),\\n            source=VertexTuple(id=\\\"vid\\\", params={}),\\n            target=VertexTuple(id=\\\"tid\\\", params={}),\\n            status=\\\"success\\\",\\n        )\\n\\n    # Create a build for each flow\\n    for flow_id in flow_ids:\\n        build = {\\n            \\\"valid\\\": True,\\n            \\\"params\\\": {},\\n            \\\"data\\\": ResultDataResponse(),\\n            \\\"artifacts\\\": {},\\n            \\\"vertex_id\\\": \\\"vid\\\",\\n            \\\"flow_id\\\": flow_id,\\n        }\\n        await log_vertex_build(\\n            flow_id=build[\\\"flow_id\\\"],\\n            vertex_id=build[\\\"vertex_id\\\"],\\n            valid=build[\\\"valid\\\"],\\n            params=build[\\\"params\\\"],\\n            data=build[\\\"data\\\"],\\n            artifacts=build.get(\\\"artifacts\\\"),\\n        )\\n\\n    response = await client.request(\\\"DELETE\\\", f\\\"api/v1/projects/{folder_id}\\\", headers=logged_in_headers)\\n    assert response.status_code == 204\\n\\n    for flow_id in flow_ids:\\n        response = await client.request(\\n            \\\"GET\\\", \\\"api/v1/monitor/transactions\\\", params={\\\"flow_id\\\": flow_id}, headers=logged_in_headers\\n        )\\n        assert response.status_code == 200, response.json()\\n        json_response = response.json()\\n        assert json_response[\\\"items\\\"] == []\\n\\n    for flow_id in flow_ids:\\n        response = await client.request(\\n            \\\"GET\\\", \\\"api/v1/monitor/builds\\\", params={\\\"flow_id\\\": flow_id}, headers=logged_in_headers\\n        )\\n        assert response.status_code == 200\\n        assert response.json() == {\\\"vertex_builds\\\": {}}\\n\\n\\nasync def test_get_flows_from_folder_pagination(client: AsyncClient, logged_in_headers):\\n    # Create a new project\\n    folder_name = f\\\"Test Project {uuid4()}\\\"\\n    project = FolderCreate(name=folder_name, description=\\\"Test project description\\\", components_list=[], flows_list=[])\\n\\n    response = await client.post(\\\"api/v1/projects/\\\", json=project.model_dump(), headers=logged_in_headers)\\n    assert response.status_code == 201, f\\\"Expected status code 201, but got {response.status_code}\\\"\\n\\n    created_folder = response.json()\\n    folder_id = UUID(created_folder[\\\"id\\\"])\\n\\n    response = await client.get(\\n        f\\\"api/v1/projects/{folder_id}\\\", headers=logged_in_headers, params={\\\"page\\\": 1, \\\"size\\\": 50}\\n    )\\n    assert response.status_code == 200\\n    assert response.json()[\\\"folder\\\"][\\\"name\\\"] == folder_name\\n    assert response.json()[\\\"folder\\\"][\\\"description\\\"] == \\\"Test project description\\\"\\n    assert response.json()[\\\"flows\\\"][\\\"page\\\"] == 1\\n    assert response.json()[\\\"flows\\\"][\\\"size\\\"] == 50\\n    assert response.json()[\\\"flows\\\"][\\\"pages\\\"] == 0\\n    assert response.json()[\\\"flows\\\"][\\\"total\\\"] == 0\\n    assert len(response.json()[\\\"flows\\\"][\\\"items\\\"]) == 0\\n\\n\\nasync def test_get_flows_from_folder_pagination_with_params(client: AsyncClient, logged_in_headers):\\n    # Create a new project\\n    folder_name = f\\\"Test Project {uuid4()}\\\"\\n    project = FolderCreate(name=folder_name, description=\\\"Test project description\\\", components_list=[], flows_list=[])\\n\\n    response = await client.post(\\\"api/v1/projects/\\\", json=project.model_dump(), headers=logged_in_headers)\\n    assert response.status_code == 201, f\\\"Expected status code 201, but got {response.status_code}\\\"\\n\\n    created_folder = response.json()\\n    folder_id = created_folder[\\\"id\\\"]\\n\\n    response = await client.get(\\n        f\\\"api/v1/projects/{folder_id}\\\", headers=logged_in_headers, params={\\\"page\\\": 3, \\\"size\\\": 10}\\n    )\\n    assert response.status_code == 200\\n    assert response.json()[\\\"folder\\\"][\\\"name\\\"] == folder_name\\n    assert response.json()[\\\"folder\\\"][\\\"description\\\"] == \\\"Test project description\\\"\\n    assert response.json()[\\\"flows\\\"][\\\"page\\\"] == 3\\n    assert response.json()[\\\"flows\\\"][\\\"size\\\"] == 10\\n    assert response.json()[\\\"flows\\\"][\\\"pages\\\"] == 0\\n    assert response.json()[\\\"flows\\\"][\\\"total\\\"] == 0\\n    assert len(response.json()[\\\"flows\\\"][\\\"items\\\"]) == 0\\n\\n\\n@pytest.mark.usefixtures(\\\"session\\\")\\nasync def test_create_flows(client: AsyncClient, json_flow: str, logged_in_headers):\\n    flow = orjson.loads(json_flow)\\n    data = flow[\\\"data\\\"]\\n    # Create test data\\n    flow_unique_name = str(uuid4())\\n    flow_2_unique_name = str(uuid4())\\n    flow_list = FlowListCreate(\\n        flows=[\\n            FlowCreate(name=flow_unique_name, description=\\\"description\\\", data=data),\\n            FlowCreate(name=flow_2_unique_name, description=\\\"description\\\", data=data),\\n        ]\\n    )\\n    # Make request to endpoint\\n    response = await client.post(\\\"api/v1/flows/batch/\\\", json=flow_list.dict(), headers=logged_in_headers)\\n    # Check response status code\\n    assert response.status_code == 201\\n    # Check response data\\n    response_data = response.json()\\n    assert len(response_data) == 2\\n    assert flow_unique_name in response_data[0][\\\"name\\\"]\\n    assert response_data[0][\\\"description\\\"] == \\\"description\\\"\\n    assert response_data[0][\\\"data\\\"] == data\\n    assert response_data[1][\\\"name\\\"] == flow_2_unique_name\\n    assert response_data[1][\\\"description\\\"] == \\\"description\\\"\\n    assert response_data[1][\\\"data\\\"] == data\\n\\n\\n@pytest.mark.usefixtures(\\\"session\\\")\\nasync def test_create_flows_duplicate_name_returns_clean_409(client: AsyncClient, json_flow: str, logged_in_headers):\\n    \\\"\\\"\\\"A (user_id, name) collision in the batch endpoint must surface as a clean 409.\\n\\n    Regression: the duplicate INSERT used to reach ``session.flush()`` unhandled, leaking the raw\\n    SQL statement and bound parameters and \u2014 un-rolled-back on SQLite \u2014 pinning the write lock so\\n    the next writer busy-waited ``busy_timeout`` before \\\"database is locked\\\". The endpoint now rolls\\n    back and maps the violation, so the error is fast and the session stays usable.\\n    \\\"\\\"\\\"\\n    flow = orjson.loads(json_flow)\\n    data = flow[\\\"data\\\"]\\n    taken_name = str(uuid4())\\n\\n    # Seed the name once.\\n    seed = FlowListCreate(flows=[FlowCreate(name=taken_name, description=\\\"seed\\\", data=data)])\\n    seed_response = await client.post(\\\"api/v1/flows/batch/\\\", json=seed.dict(), headers=logged_in_headers)\\n    assert seed_response.status_code == 201\\n\\n    # Re-inserting the same name collides on UNIQUE(user_id, name).\\n    dup = FlowListCreate(flows=[FlowCreate(name=taken_name, description=\\\"dup\\\", data=data)])\\n    dup_response = await client.post(\\\"api/v1/flows/batch/\\\", json=dup.dict(), headers=logged_in_headers)\\n    assert dup_response.status_code == 409\\n    assert dup_response.json()[\\\"detail\\\"] == \\\"Name must be unique\\\"\\n    # No SQLAlchemy statement / bound parameters / driver hint may leak to the client.\\n    body = dup_response.text.lower()\\n    assert \\\"insert into\\\" not in body\\n    assert \\\"sqlalche.me\\\" not in body\\n    assert \\\"user_id\\\" not in body\\n\\n    # The session was rolled back (lock released), so a fresh write still succeeds immediately.\\n    follow_up = FlowListCreate(flows=[FlowCreate(name=str(uuid4()), description=\\\"after\\\", data=data)])\\n    follow_up_response = await client.post(\\\"api/v1/flows/batch/\\\", json=follow_up.dict(), headers=logged_in_headers)\\n    assert follow_up_response.status_code == 201\\n\\n\\n@pytest.mark.usefixtures(\\\"session\\\")\\nasync def test_upload_file(client: AsyncClient, json_flow: str, logged_in_headers):\\n    flow = orjson.loads(json_flow)\\n    data = flow[\\\"data\\\"]\\n    # Create test data\\n    flow_unique_name = str(uuid4())\\n    flow_2_unique_name = str(uuid4())\\n    flow_list = FlowListCreate(\\n        flows=[\\n            FlowCreate(name=flow_unique_name, description=\\\"description\\\", data=data),\\n            FlowCreate(name=flow_2_unique_name, description=\\\"description\\\", data=data),\\n        ]\\n    )\\n    file_contents = orjson_dumps(flow_list.dict())\\n    response = await client.post(\\n        \\\"api/v1/flows/upload/\\\",\\n        files={\\\"file\\\": (\\\"examples.json\\\", file_contents, \\\"application/json\\\")},\\n        headers=logged_in_headers,\\n    )\\n    # Check response status code\\n    assert response.status_code == 201\\n    # Check response data\\n    response_data = response.json()\\n    assert len(response_data) == 2\\n    assert flow_unique_name in response_data[0][\\\"name\\\"]\\n    assert response_data[0][\\\"description\\\"] == \\\"description\\\"\\n    assert response_data[0][\\\"data\\\"] == data\\n    assert response_data[1][\\\"name\\\"] == flow_2_unique_name\\n    assert response_data[1][\\\"description\\\"] == \\\"description\\\"\\n    assert response_data[1][\\\"data\\\"] == data\\n\\n\\n@pytest.mark.usefixtures(\\\"session\\\")\\nasync def test_upload_file_flows_not_a_list_returns_422(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Regression: { \\\"flows\\\": <non-list> } must return 422, not 500.\\\"\\\"\\\"\\n    file_contents = orjson.dumps({\\\"flows\\\": \\\"oops\\\"})\\n    response = await client.post(\\n        \\\"api/v1/flows/upload/\\\",\\n        files={\\\"file\\\": (\\\"bad.json\\\", file_contents, \\\"application/json\\\")},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == 422\\n    assert \\\"flows\\\" in response.json()[\\\"detail\\\"].lower()\\n\\n\\n@pytest.mark.usefixtures(\\\"session\\\")\\nasync def test_upload_file_flows_item_not_a_dict_returns_422(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Regression: { \\\"flows\\\": [1] } must return 422, not 500.\\\"\\\"\\\"\\n    file_contents = orjson.dumps({\\\"flows\\\": [1]})\\n    response = await client.post(\\n        \\\"api/v1/flows/upload/\\\",\\n        files={\\\"file\\\": (\\\"bad.json\\\", file_contents, \\\"application/json\\\")},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == 422\\n    assert \\\"flows\\\" in response.json()[\\\"detail\\\"].lower()\\n\\n\\n@pytest.mark.usefixtures(\\\"session\\\")\\nasync def test_upload_file_flows_mixed_items_returns_422(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Regression: { \\\"flows\\\": [{}, 42] } must return 422 at the bad item.\\\"\\\"\\\"\\n    file_contents = orjson.dumps({\\\"flows\\\": [{}, 42]})\\n    response = await client.post(\\n        \\\"api/v1/flows/upload/\\\",\\n        files={\\\"file\\\": (\\\"bad.json\\\", file_contents, \\\"application/json\\\")},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == 422\\n    assert \\\"flows[1]\\\" in response.json()[\\\"detail\\\"]\\n\\n\\n@pytest.mark.usefixtures(\\\"session\\\")\\nasync def test_download_file(\\n    client: AsyncClient,\\n    json_flow,\\n    active_user,\\n    logged_in_headers,\\n):\\n    flow = orjson.loads(json_flow)\\n    data = flow[\\\"data\\\"]\\n    # Create test data\\n    flow_unique_name = str(uuid4())\\n    flow_2_unique_name = str(uuid4())\\n    flow_list = FlowListCreate(\\n        flows=[\\n            FlowCreate(name=flow_unique_name, description=\\\"description\\\", data=data),\\n            FlowCreate(name=flow_2_unique_name, description=\\\"description\\\", data=data),\\n        ]\\n    )\\n    db_manager = get_db_service()\\n    async with session_getter(db_manager) as _session:\\n        saved_flows = []\\n        for flow in flow_list.flows:\\n            flow.user_id = active_user.id\\n            db_flow = Flow.model_validate(flow.model_dump(exclude={\\\"id\\\"}))\\n            _session.add(db_flow)\\n            saved_flows.append(db_flow)\\n        await _session.commit()\\n        # Make request to endpoint inside the session context\\n        flow_ids = [str(db_flow.id) for db_flow in saved_flows]  # Convert UUIDs to strings\\n        flow_ids_json = json.dumps(flow_ids)\\n        response = await client.post(\\n            \\\"api/v1/flows/download/\\\",\\n            data=flow_ids_json,\\n            headers={**logged_in_headers, \\\"Content-Type\\\": \\\"application/json\\\"},\\n        )\\n    # Check response status code\\n    assert response.status_code == 200, response.json()\\n    # Check response data\\n    # Since the endpoint now returns a zip file, we need to check the content type and the filename in the headers\\n    assert response.headers[\\\"Content-Type\\\"] == \\\"application/x-zip-compressed\\\"\\n    content_disposition = response.headers[\\\"Content-Disposition\\\"]\\n    assert \\\"attachment\\\" in content_disposition\\n    assert 'filename=\\\"' in content_disposition\\n    assert \\\"filename*=UTF-8''\\\" in content_disposition\\n\\n\\n@pytest.mark.usefixtures(\\\"session\\\")\\nasync def test_download_flows_content_disposition_dual_param(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Downloading multiple flows must produce a dual-param RFC 5987 Content-Disposition header.\\n\\n    The ZIP filename is always timestamp-based (pure ASCII). This test verifies\\n    that both the legacy 'filename=' param and the RFC 5987 'filename*=' param\\n    are present and well-formed, as required for compatibility with both old\\n    and new HTTP clients.\\n    \\\"\\\"\\\"\\n    from urllib.parse import unquote\\n\\n    # Create two flows (names don't affect the ZIP filename, which is timestamp-based)\\n    chinese_names = [\\\"\u9f99\u6d41\u7a0b\\\", \\\"\u6d4b\u8bd5\u4e0b\u8f7d\\\"]\\n    flow_ids = []\\n    for name in chinese_names:\\n        create_resp = await client.post(\\n            \\\"api/v1/flows/\\\",\\n            json={\\\"name\\\": name, \\\"description\\\": \\\"\\\", \\\"data\\\": {}},\\n            headers=logged_in_headers,\\n        )\\n        assert create_resp.status_code == 201\\n        flow_ids.append(create_resp.json()[\\\"id\\\"])\\n\\n    download_response = await client.post(\\n        \\\"api/v1/flows/download/\\\",\\n        data=json.dumps(flow_ids),\\n        headers={**logged_in_headers, \\\"Content-Type\\\": \\\"application/json\\\"},\\n    )\\n    assert download_response.status_code == 200\\n    assert download_response.headers[\\\"Content-Type\\\"] == \\\"application/x-zip-compressed\\\"\\n\\n    content_disposition = download_response.headers[\\\"Content-Disposition\\\"]\\n    # Must include both params: ASCII fallback and RFC 5987\\n    assert \\\"attachment\\\" in content_disposition\\n    assert 'filename=\\\"' in content_disposition\\n    assert \\\"filename*=UTF-8''\\\" in content_disposition\\n    # The RFC 5987 value must decode to a .zip filename\\n    rfc5987_value = content_disposition.split(\\\"filename*=UTF-8''\\\")[-1].split(\\\";\\\")[0].strip()\\n    decoded = unquote(rfc5987_value)\\n    assert decoded.endswith(\\\".zip\\\")\\n\\n\\n@pytest.mark.usefixtures(\\\"session\\\")\\nasync def test_download_single_flow_returns_normalized_json(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Downloading a single flow returns normalized JSON rather than a ZIP archive.\\\"\\\"\\\"\\n    code_value = \\\"print('hello')\\\\nprint('world')\\\"\\n    flow_payload = FlowCreate(\\n        name=str(uuid4()),\\n        description=\\\"single flow export\\\",\\n        data={\\n            \\\"nodes\\\": [\\n                {\\n                    \\\"id\\\": \\\"node-1\\\",\\n                    \\\"data\\\": {\\n                        \\\"node\\\": {\\n                            \\\"template\\\": {\\n                                \\\"code\\\": {\\\"type\\\": \\\"code\\\", \\\"value\\\": code_value},\\n                                \\\"api_key\\\": {\\\"name\\\": \\\"api_key\\\", \\\"password\\\": True, \\\"value\\\": \\\"super-secret\\\"},\\n                            }\\n                        }\\n                    },\\n                }\\n            ],\\n            \\\"edges\\\": [],\\n        },\\n    )\\n\\n    create_response = await client.post(\\\"api/v1/flows/\\\", json=flow_payload.model_dump(), headers=logged_in_headers)\\n    assert create_response.status_code == 201\\n    flow_id = create_response.json()[\\\"id\\\"]\\n\\n    download_response = await client.post(\\n        \\\"api/v1/flows/download/\\\",\\n        data=json.dumps([flow_id]),\\n        headers={**logged_in_headers, \\\"Content-Type\\\": \\\"application/json\\\"},\\n    )\\n    assert download_response.status_code == 200\\n    assert download_response.headers[\\\"Content-Type\\\"].startswith(\\\"application/json\\\")\\n\\n    downloaded = download_response.json()\\n    assert downloaded[\\\"name\\\"] == flow_payload.name\\n    assert \\\"updated_at\\\" not in downloaded\\n    assert \\\"user_id\\\" not in downloaded\\n    assert \\\"folder_id\\\" not in downloaded\\n    assert \\\"access_type\\\" not in downloaded\\n    assert downloaded[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"code\\\"][\\\"value\\\"] == [\\n        \\\"print('hello')\\\",\\n        \\\"print('world')\\\",\\n    ]\\n    assert downloaded[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"api_key\\\"][\\\"value\\\"] is None\\n\\n\\n@pytest.mark.usefixtures(\\\"session\\\")\\nasync def test_upload_zip_file_to_flows(client: AsyncClient, json_flow: str, logged_in_headers):\\n    \\\"\\\"\\\"Test uploading a ZIP file containing flow JSONs to the flows upload endpoint.\\\"\\\"\\\"\\n    flow = orjson.loads(json_flow)\\n    data = flow[\\\"data\\\"]\\n\\n    flow_1_name = str(uuid4())\\n    flow_2_name = str(uuid4())\\n    flow_1 = {\\\"name\\\": flow_1_name, \\\"description\\\": \\\"desc1\\\", \\\"data\\\": data}\\n    flow_2 = {\\\"name\\\": flow_2_name, \\\"description\\\": \\\"desc2\\\", \\\"data\\\": data}\\n\\n    # Create a ZIP file in memory with individual flow JSONs\\n    zip_buffer = io.BytesIO()\\n    with zipfile.ZipFile(zip_buffer, \\\"w\\\") as zf:\\n        zf.writestr(f\\\"{flow_1_name}.json\\\", json.dumps(flow_1))\\n        zf.writestr(f\\\"{flow_2_name}.json\\\", json.dumps(flow_2))\\n    zip_buffer.seek(0)\\n\\n    response = await client.post(\\n        \\\"api/v1/flows/upload/\\\",\\n        files={\\\"file\\\": (\\\"flows.zip\\\", zip_buffer.getvalue(), \\\"application/zip\\\")},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == 201\\n    response_data = response.json()\\n    assert len(response_data) == 2\\n    names = {r[\\\"name\\\"] for r in response_data}\\n    assert flow_1_name in names\\n    assert flow_2_name in names\\n\\n\\n@pytest.mark.usefixtures(\\\"session\\\")\\nasync def test_upload_zip_file_to_projects(client: AsyncClient, json_flow: str, logged_in_headers):\\n    \\\"\\\"\\\"Test uploading a ZIP file containing flow JSONs to the projects upload endpoint.\\\"\\\"\\\"\\n    flow = orjson.loads(json_flow)\\n    data = flow[\\\"data\\\"]\\n\\n    flow_1_name = str(uuid4())\\n    flow_2_name = str(uuid4())\\n    flow_1 = {\\\"name\\\": flow_1_name, \\\"description\\\": \\\"desc1\\\", \\\"data\\\": data}\\n    flow_2 = {\\\"name\\\": flow_2_name, \\\"description\\\": \\\"desc2\\\", \\\"data\\\": data}\\n\\n    # Create a ZIP file in memory\\n    zip_buffer = io.BytesIO()\\n    with zipfile.ZipFile(zip_buffer, \\\"w\\\") as zf:\\n        zf.writestr(f\\\"{flow_1_name}.json\\\", json.dumps(flow_1))\\n        zf.writestr(f\\\"{flow_2_name}.json\\\", json.dumps(flow_2))\\n    zip_buffer.seek(0)\\n\\n    response = await client.post(\\n        \\\"api/v1/projects/upload/\\\",\\n        files={\\\"file\\\": (\\\"My Project.zip\\\", zip_buffer.getvalue(), \\\"application/zip\\\")},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == 201\\n    response_data = response.json()\\n    assert len(response_data) == 2\\n    # All flows should belong to the same folder\\n    folder_ids = {r[\\\"folder_id\\\"] for r in response_data}\\n    assert len(folder_ids) == 1\\n\\n    # Verify the project name was derived from the ZIP filename\\n    folder_id = folder_ids.pop()\\n    project_response = await client.get(f\\\"api/v1/projects/{folder_id}\\\", headers=logged_in_headers)\\n    assert project_response.status_code == 200\\n    assert project_response.json()[\\\"name\\\"].startswith(\\\"My Project\\\")\\n\\n\\n@pytest.mark.usefixtures(\\\"session\\\")\\nasync def test_upload_empty_zip_returns_400(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Test that uploading a ZIP with no JSON files returns 400.\\\"\\\"\\\"\\n    zip_buffer = io.BytesIO()\\n    with zipfile.ZipFile(zip_buffer, \\\"w\\\") as zf:\\n        zf.writestr(\\\"readme.txt\\\", \\\"not a flow\\\")\\n    zip_buffer.seek(0)\\n\\n    response = await client.post(\\n        \\\"api/v1/flows/upload/\\\",\\n        files={\\\"file\\\": (\\\"empty.zip\\\", zip_buffer.getvalue(), \\\"application/zip\\\")},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == 400\\n    assert \\\"No valid flow JSON files\\\" in response.json()[\\\"detail\\\"]\\n\\n\\n@pytest.mark.usefixtures(\\\"session\\\")\\nasync def test_download_then_upload_roundtrip(client: AsyncClient, json_flow: str, active_user, logged_in_headers):\\n    \\\"\\\"\\\"Test that downloading flows as ZIP and re-uploading works end-to-end.\\\"\\\"\\\"\\n    flow = orjson.loads(json_flow)\\n    data = flow[\\\"data\\\"]\\n\\n    flow_1_name = str(uuid4())\\n    flow_2_name = str(uuid4())\\n    flow_list = FlowListCreate(\\n        flows=[\\n            FlowCreate(name=flow_1_name, description=\\\"description\\\", data=data),\\n            FlowCreate(name=flow_2_name, description=\\\"description\\\", data=data),\\n        ]\\n    )\\n\\n    # Create flows in DB\\n    db_manager = get_db_service()\\n    async with session_getter(db_manager) as _session:\\n        saved_flows = []\\n        for f in flow_list.flows:\\n            f.user_id = active_user.id\\n            f.id = uuid4()\\n            db_flow = Flow.model_validate(f, from_attributes=True)\\n            _session.add(db_flow)\\n            saved_flows.append(db_flow)\\n        await _session.commit()\\n        flow_ids = [str(db_flow.id) for db_flow in saved_flows]\\n\\n    # Download as ZIP\\n    download_response = await client.post(\\n        \\\"api/v1/flows/download/\\\",\\n        data=json.dumps(flow_ids),\\n        headers={**logged_in_headers, \\\"Content-Type\\\": \\\"application/json\\\"},\\n    )\\n    assert download_response.status_code == 200\\n    assert download_response.headers[\\\"Content-Type\\\"] == \\\"application/x-zip-compressed\\\"\\n\\n    # Re-upload the ZIP\\n    upload_response = await client.post(\\n        \\\"api/v1/flows/upload/\\\",\\n        files={\\\"file\\\": (\\\"flows.zip\\\", download_response.content, \\\"application/zip\\\")},\\n        headers=logged_in_headers,\\n    )\\n    assert upload_response.status_code == 201\\n    uploaded = upload_response.json()\\n    assert len(uploaded) == 2\\n\\n\\n@pytest.mark.usefixtures(\\\"session\\\")\\nasync def test_upload_zip_with_invalid_json(client: AsyncClient, json_flow: str, logged_in_headers):\\n    \\\"\\\"\\\"ZIP entries with invalid JSON are skipped; valid entries are still processed.\\\"\\\"\\\"\\n    flow = orjson.loads(json_flow)\\n    data = flow[\\\"data\\\"]\\n    valid_flow = {\\\"name\\\": \\\"valid_flow\\\", \\\"description\\\": \\\"good\\\", \\\"data\\\": data}\\n\\n    zip_buffer = io.BytesIO()\\n    with zipfile.ZipFile(zip_buffer, \\\"w\\\") as zf:\\n        zf.writestr(\\\"valid.json\\\", json.dumps(valid_flow))\\n        zf.writestr(\\\"broken.json\\\", \\\"{not valid json!!!}\\\")\\n    zip_buffer.seek(0)\\n\\n    response = await client.post(\\n        \\\"api/v1/flows/upload/\\\",\\n        files={\\\"file\\\": (\\\"mixed.zip\\\", zip_buffer.getvalue(), \\\"application/zip\\\")},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == 201\\n    response_data = response.json()\\n    assert len(response_data) == 1\\n    assert response_data[0][\\\"name\\\"] == \\\"valid_flow\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"session\\\")\\nasync def test_upload_zip_exceeding_max_entries(client: AsyncClient, json_flow: str, logged_in_headers, monkeypatch):\\n    \\\"\\\"\\\"ZIP with more JSON entries than the limit raises 400.\\\"\\\"\\\"\\n    import langflow.api.utils.zip_utils as zip_utils_mod\\n\\n    monkeypatch.setattr(zip_utils_mod, \\\"MAX_ZIP_ENTRIES\\\", 3)\\n\\n    flow = orjson.loads(json_flow)\\n    data = flow[\\\"data\\\"]\\n\\n    zip_buffer = io.BytesIO()\\n    with zipfile.ZipFile(zip_buffer, \\\"w\\\") as zf:\\n        for i in range(5):\\n            zf.writestr(f\\\"flow_{i}.json\\\", json.dumps({\\\"name\\\": f\\\"flow_{i}\\\", \\\"data\\\": data}))\\n    zip_buffer.seek(0)\\n\\n    response = await client.post(\\n        \\\"api/v1/flows/upload/\\\",\\n        files={\\\"file\\\": (\\\"too_many.zip\\\", zip_buffer.getvalue(), \\\"application/zip\\\")},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == 400\\n    assert \\\"exceeding the limit\\\" in response.json()[\\\"detail\\\"]\\n\\n\\n@pytest.mark.usefixtures(\\\"session\\\")\\nasync def test_upload_zip_with_oversized_entry(client: AsyncClient, json_flow: str, logged_in_headers, monkeypatch):\\n    \\\"\\\"\\\"Entries exceeding size limit are skipped; smaller valid entries are processed.\\\"\\\"\\\"\\n    import langflow.api.utils.zip_utils as zip_utils_mod\\n\\n    flow = orjson.loads(json_flow)\\n    data = flow[\\\"data\\\"]\\n    small_flow = {\\\"name\\\": \\\"small_flow\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}\\n    big_flow = {\\\"name\\\": \\\"big_flow\\\", \\\"data\\\": data}\\n\\n    # Build the ZIP first, then set the limit between the two entry sizes\\n    zip_buffer = io.BytesIO()\\n    with zipfile.ZipFile(zip_buffer, \\\"w\\\") as zf:\\n        zf.writestr(\\\"small.json\\\", json.dumps(small_flow))\\n        zf.writestr(\\\"big.json\\\", json.dumps(big_flow))\\n\\n    # Re-read to find the actual sizes and pick a limit between them\\n    with zipfile.ZipFile(io.BytesIO(zip_buffer.getvalue()), \\\"r\\\") as zf:\\n        sizes = {info.filename: info.file_size for info in zf.infolist()}\\n    limit = (sizes[\\\"small.json\\\"] + sizes[\\\"big.json\\\"]) // 2\\n    monkeypatch.setattr(zip_utils_mod, \\\"MAX_ENTRY_UNCOMPRESSED_BYTES\\\", limit)\\n\\n    zip_buffer.seek(0)\\n    response = await client.post(\\n        \\\"api/v1/flows/upload/\\\",\\n        files={\\\"file\\\": (\\\"oversized.zip\\\", zip_buffer.getvalue(), \\\"application/zip\\\")},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == 201\\n    response_data = response.json()\\n    assert len(response_data) == 1\\n    assert response_data[0][\\\"name\\\"] == \\\"small_flow\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"session\\\")\\nasync def test_upload_zip_with_mixed_valid_invalid(client: AsyncClient, json_flow: str, logged_in_headers, monkeypatch):\\n    \\\"\\\"\\\"Mix of valid flows, invalid JSON, and oversized entries \u2192 only valid flows returned.\\\"\\\"\\\"\\n    import langflow.api.utils.zip_utils as zip_utils_mod\\n\\n    flow = orjson.loads(json_flow)\\n    data = flow[\\\"data\\\"]\\n    valid_flow = {\\\"name\\\": \\\"keeper\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}\\n    oversized_flow = {\\\"name\\\": \\\"too_big\\\", \\\"data\\\": data, \\\"padding\\\": \\\"x\\\" * 500}\\n\\n    zip_buffer = io.BytesIO()\\n    with zipfile.ZipFile(zip_buffer, \\\"w\\\") as zf:\\n        zf.writestr(\\\"valid.json\\\", json.dumps(valid_flow))\\n        zf.writestr(\\\"broken.json\\\", \\\"NOT JSON {{{\\\")\\n        zf.writestr(\\\"huge.json\\\", json.dumps(oversized_flow))\\n        zf.writestr(\\\"readme.txt\\\", \\\"ignored non-json\\\")\\n\\n    # Set limit between valid entry size and oversized entry size\\n    with zipfile.ZipFile(io.BytesIO(zip_buffer.getvalue()), \\\"r\\\") as zf:\\n        sizes = {info.filename: info.file_size for info in zf.infolist()}\\n    limit = (sizes[\\\"valid.json\\\"] + sizes[\\\"huge.json\\\"]) // 2\\n    monkeypatch.setattr(zip_utils_mod, \\\"MAX_ENTRY_UNCOMPRESSED_BYTES\\\", limit)\\n\\n    zip_buffer.seek(0)\\n    response = await client.post(\\n        \\\"api/v1/flows/upload/\\\",\\n        files={\\\"file\\\": (\\\"mixed.zip\\\", zip_buffer.getvalue(), \\\"application/zip\\\")},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == 201\\n    response_data = response.json()\\n    assert len(response_data) == 1\\n    assert response_data[0][\\\"name\\\"] == \\\"keeper\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"session\\\")\\nasync def test_upload_zip_to_projects_filename_none(client: AsyncClient, json_flow: str, logged_in_headers):\\n    \\\"\\\"\\\"When filename has no stem (e.g. '.zip'), the project name defaults to 'Imported Project'.\\\"\\\"\\\"\\n    flow = orjson.loads(json_flow)\\n    data = flow[\\\"data\\\"]\\n    flow_data = {\\\"name\\\": \\\"flow_none\\\", \\\"data\\\": data}\\n\\n    zip_buffer = io.BytesIO()\\n    with zipfile.ZipFile(zip_buffer, \\\"w\\\") as zf:\\n        zf.writestr(\\\"flow.json\\\", json.dumps(flow_data))\\n    zip_buffer.seek(0)\\n\\n    # filename=\\\".zip\\\" \u2192 rsplit gives (\\\"\\\", \\\"zip\\\") \u2192 \\\"\\\" is falsy \u2192 \\\"Imported Project\\\"\\n    response = await client.post(\\n        \\\"api/v1/projects/upload/\\\",\\n        files={\\\"file\\\": (\\\".zip\\\", zip_buffer.getvalue(), \\\"application/zip\\\")},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == 201\\n    response_data = response.json()\\n    assert len(response_data) == 1\\n\\n    folder_id = response_data[0][\\\"folder_id\\\"]\\n    project_response = await client.get(f\\\"api/v1/projects/{folder_id}\\\", headers=logged_in_headers)\\n    assert project_response.status_code == 200\\n    assert project_response.json()[\\\"name\\\"].startswith(\\\"Imported Project\\\")\\n\\n\\n@pytest.mark.usefixtures(\\\"session\\\")\\nasync def test_upload_json_file_to_projects_rejoins_code_lines(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Project JSON upload accepts exported code-as-lines format and stores code as a string.\\\"\\\"\\\"\\n    project_name = f\\\"JSON Project {uuid4()}\\\"\\n    code_lines = [\\\"print('alpha')\\\", \\\"print('beta')\\\"]\\n    payload = {\\n        \\\"folder_name\\\": project_name,\\n        \\\"folder_description\\\": \\\"json upload\\\",\\n        \\\"flows\\\": [\\n            {\\n                \\\"name\\\": f\\\"Flow {uuid4()}\\\",\\n                \\\"description\\\": \\\"imported from project json\\\",\\n                \\\"data\\\": {\\n                    \\\"nodes\\\": [\\n                        {\\n                            \\\"id\\\": \\\"node-1\\\",\\n                            \\\"data\\\": {\\n                                \\\"node\\\": {\\n                                    \\\"template\\\": {\\n                                        \\\"code\\\": {\\\"type\\\": \\\"code\\\", \\\"value\\\": code_lines},\\n                                    }\\n                                }\\n                            },\\n                        }\\n                    ],\\n                    \\\"edges\\\": [],\\n                },\\n            }\\n        ],\\n    }\\n\\n    response = await client.post(\\n        \\\"api/v1/projects/upload/\\\",\\n        files={\\\"file\\\": (\\\"project.json\\\", json.dumps(payload).encode(\\\"utf-8\\\"), \\\"application/json\\\")},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == 201, response.text\\n    response_data = response.json()\\n    assert len(response_data) == 1\\n    assert response_data[0][\\\"folder_id\\\"] is not None\\n    assert (\\n        response_data[0][\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"code\\\"][\\\"value\\\"]\\n        == \\\"print('alpha')\\\\nprint('beta')\\\"\\n    )\\n\\n    project_response = await client.get(f\\\"api/v1/projects/{response_data[0]['folder_id']}\\\", headers=logged_in_headers)\\n    assert project_response.status_code == 200\\n    assert project_response.json()[\\\"name\\\"].startswith(project_name)\\n\\n\\n@pytest.mark.usefixtures(\\\"session\\\")\\nasync def test_download_project_zip_sanitizes_flow_names(client: AsyncClient, json_flow: str, logged_in_headers):\\n    \\\"\\\"\\\"Project ZIP downloads must sanitize flow names to prevent Zip Slip paths.\\\"\\\"\\\"\\n    project_response = await client.post(\\n        \\\"api/v1/projects/\\\",\\n        json={\\\"name\\\": f\\\"Download Project {uuid4()}\\\", \\\"description\\\": \\\"\\\", \\\"flows_list\\\": [], \\\"components_list\\\": []},\\n        headers=logged_in_headers,\\n    )\\n    assert project_response.status_code == 201\\n    project_id = project_response.json()[\\\"id\\\"]\\n\\n    flow = orjson.loads(json_flow)\\n    create_response = await client.post(\\n        \\\"api/v1/flows/\\\",\\n        json={\\n            \\\"name\\\": \\\"../escaped-flow\\\",\\n            \\\"description\\\": \\\"path traversal test\\\",\\n            \\\"folder_id\\\": project_id,\\n            \\\"data\\\": flow[\\\"data\\\"],\\n            \\\"is_component\\\": False,\\n        },\\n        headers=logged_in_headers,\\n    )\\n    assert create_response.status_code == 201\\n\\n    download_response = await client.get(f\\\"api/v1/projects/download/{project_id}\\\", headers=logged_in_headers)\\n    assert download_response.status_code == 200\\n\\n    with zipfile.ZipFile(io.BytesIO(download_response.content), \\\"r\\\") as zip_file:\\n        file_names = zip_file.namelist()\\n        assert \\\"__escaped-flow.json\\\" in file_names\\n        assert all(\\\"/\\\" not in name and \\\"..\\\" not in name for name in file_names)\\n\\n\\n@pytest.mark.usefixtures(\\\"session\\\")\\nasync def test_upload_bad_zip_file_returns_400(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Uploading a corrupt/invalid ZIP file returns 400 with a descriptive error.\\\"\\\"\\\"\\n    # Payload with an EOCD signature prepended by garbage. Python 3.10-3.13 treat\\n    # this as a ZIP and fail in ZipFile() construction (\\\"not a valid ZIP archive\\\");\\n    # Python 3.14's stricter zipfile.is_zipfile() rejects it and the route falls\\n    # through to the JSON branch (\\\"Invalid JSON file\\\"). Both paths return 400 with\\n    # a descriptive detail, which is the user-facing contract under test.\\n    buf = io.BytesIO()\\n    with zipfile.ZipFile(buf, \\\"w\\\") as zf:\\n        zf.writestr(\\\"dummy.json\\\", '{\\\"name\\\":\\\"x\\\"}')\\n    valid_zip = buf.getvalue()\\n    # Minimal EOCD is 22 bytes; keep it and prepend garbage\\n    corrupt_zip = b\\\"garbage\\\" * 10 + valid_zip[-22:]\\n\\n    response = await client.post(\\n        \\\"api/v1/flows/upload/\\\",\\n        files={\\\"file\\\": (\\\"corrupt.zip\\\", corrupt_zip, \\\"application/zip\\\")},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == 400\\n    detail = response.json()[\\\"detail\\\"]\\n    assert \\\"not a valid ZIP\\\" in detail or \\\"Invalid JSON file\\\" in detail\\n\\n\\n@pytest.mark.usefixtures(\\\"session\\\")\\nasync def test_upload_no_file_to_flows_returns_400(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Uploading with no file to flows endpoint returns 400.\\\"\\\"\\\"\\n    response = await client.post(\\n        \\\"api/v1/flows/upload/\\\",\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == 400\\n    assert response.json()[\\\"detail\\\"] == \\\"No file provided\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"session\\\")\\nasync def test_upload_no_file_to_projects_returns_400(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Uploading with no file to projects endpoint returns 400.\\\"\\\"\\\"\\n    response = await client.post(\\n        \\\"api/v1/projects/upload/\\\",\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == 400\\n    assert response.json()[\\\"detail\\\"] == \\\"No file provided\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"session\\\")\\nasync def test_upload_empty_file_to_flows_returns_400(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Uploading an empty file to flows endpoint returns 400.\\\"\\\"\\\"\\n    response = await client.post(\\n        \\\"api/v1/flows/upload/\\\",\\n        files={\\\"file\\\": (\\\"empty.json\\\", b\\\"\\\", \\\"application/json\\\")},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == 400\\n    assert response.json()[\\\"detail\\\"] == \\\"The uploaded file is empty\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"session\\\")\\nasync def test_upload_empty_file_to_projects_returns_400(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Uploading an empty file to projects endpoint returns 400.\\\"\\\"\\\"\\n    response = await client.post(\\n        \\\"api/v1/projects/upload/\\\",\\n        files={\\\"file\\\": (\\\"empty.json\\\", b\\\"\\\", \\\"application/json\\\")},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == 400\\n    assert response.json()[\\\"detail\\\"] == \\\"The uploaded file is empty\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"session\\\")\\nasync def test_upload_invalid_json_to_flows_returns_400(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Uploading invalid JSON content to flows endpoint returns 400.\\\"\\\"\\\"\\n    response = await client.post(\\n        \\\"api/v1/flows/upload/\\\",\\n        files={\\\"file\\\": (\\\"bad.json\\\", b\\\"this is not json\\\", \\\"application/json\\\")},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == 400\\n    assert \\\"Invalid JSON file\\\" in response.json()[\\\"detail\\\"]\\n\\n\\n@pytest.mark.usefixtures(\\\"session\\\")\\nasync def test_upload_invalid_json_to_projects_returns_400(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Uploading invalid JSON content to projects endpoint returns 400.\\\"\\\"\\\"\\n    response = await client.post(\\n        \\\"api/v1/projects/upload/\\\",\\n        files={\\\"file\\\": (\\\"bad.json\\\", b\\\"this is not json\\\", \\\"application/json\\\")},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == 400\\n    assert \\\"Invalid JSON file\\\" in response.json()[\\\"detail\\\"]\\n\\n\\n@pytest.mark.usefixtures(\\\"session\\\")\\nasync def test_upload_zip_to_projects_batch_name_dedup(client: AsyncClient, json_flow: str, logged_in_headers):\\n    \\\"\\\"\\\"Multiple flows with the same name get unique names within the batch.\\\"\\\"\\\"\\n    flow = orjson.loads(json_flow)\\n    data = flow[\\\"data\\\"]\\n\\n    zip_buffer = io.BytesIO()\\n    with zipfile.ZipFile(zip_buffer, \\\"w\\\") as zf:\\n        for i in range(3):\\n            zf.writestr(f\\\"flow_{i}.json\\\", json.dumps({\\\"name\\\": \\\"duplicate_name\\\", \\\"data\\\": data}))\\n    zip_buffer.seek(0)\\n\\n    response = await client.post(\\n        \\\"api/v1/projects/upload/\\\",\\n        files={\\\"file\\\": (\\\"dedup_test.zip\\\", zip_buffer.getvalue(), \\\"application/zip\\\")},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == 201\\n    response_data = response.json()\\n    assert len(response_data) == 3\\n    names = [r[\\\"name\\\"] for r in response_data]\\n    # All names must be unique\\n    assert len(set(names)) == 3\\n\\n\\n@pytest.mark.usefixtures(\\\"active_user\\\")\\nasync def test_create_flow_with_invalid_data(client: AsyncClient, logged_in_headers):\\n    flow = {\\\"name\\\": \\\"a\\\" * 256, \\\"data\\\": \\\"Invalid flow data\\\"}\\n    response = await client.post(\\\"api/v1/flows/\\\", json=flow, headers=logged_in_headers)\\n    assert response.status_code == 422\\n\\n\\n@pytest.mark.usefixtures(\\\"active_user\\\")\\nasync def test_get_nonexistent_flow(client: AsyncClient, logged_in_headers):\\n    uuid = uuid4()\\n    response = await client.get(f\\\"api/v1/flows/{uuid}\\\", headers=logged_in_headers)\\n    assert response.status_code == 404\\n\\n\\n@pytest.mark.usefixtures(\\\"active_user\\\")\\nasync def test_update_flow_idempotency(client: AsyncClient, json_flow: str, logged_in_headers):\\n    flow_data = orjson.loads(json_flow)\\n    data = flow_data[\\\"data\\\"]\\n    flow_data = FlowCreate(name=\\\"Test Flow\\\", description=\\\"description\\\", data=data)\\n    response = await client.post(\\\"api/v1/flows/\\\", json=flow_data.dict(), headers=logged_in_headers)\\n    flow_id = response.json()[\\\"id\\\"]\\n    updated_flow = FlowCreate(name=\\\"Updated Flow\\\", description=\\\"description\\\", data=data)\\n    response1 = await client.put(f\\\"api/v1/flows/{flow_id}\\\", json=updated_flow.model_dump(), headers=logged_in_headers)\\n    response2 = await client.put(f\\\"api/v1/flows/{flow_id}\\\", json=updated_flow.model_dump(), headers=logged_in_headers)\\n    assert response1.json() == response2.json()\\n\\n\\n@pytest.mark.usefixtures(\\\"active_user\\\")\\nasync def test_update_nonexistent_flow(client: AsyncClient, json_flow: str, logged_in_headers):\\n    flow_data = orjson.loads(json_flow)\\n    data = flow_data[\\\"data\\\"]\\n    uuid = uuid4()\\n    updated_flow = FlowCreate(\\n        name=\\\"Updated Flow\\\",\\n        description=\\\"description\\\",\\n        data=data,\\n    )\\n    response = await client.patch(f\\\"api/v1/flows/{uuid}\\\", json=updated_flow.model_dump(), headers=logged_in_headers)\\n    assert response.status_code == 404, response.text\\n\\n\\n@pytest.mark.usefixtures(\\\"active_user\\\")\\nasync def test_delete_nonexistent_flow(client: AsyncClient, logged_in_headers):\\n    uuid = uuid4()\\n    response = await client.delete(f\\\"api/v1/flows/{uuid}\\\", headers=logged_in_headers)\\n    assert response.status_code == 404\\n\\n\\n@pytest.mark.usefixtures(\\\"active_user\\\")\\nasync def test_read_only_starter_projects(client: AsyncClient, logged_in_headers):\\n    response = await client.get(\\\"api/v1/flows/basic_examples/\\\", headers=logged_in_headers)\\n    starter_projects = await load_starter_projects()\\n    all_types_dict = await get_and_cache_all_types_dict(get_settings_service())\\n    available_starter_projects = filter_starter_projects_by_available_components(starter_projects, all_types_dict)\\n\\n    assert response.status_code == 200\\n    assert sorted(project[\\\"name\\\"] for project in response.json()) == sorted(\\n        project[\\\"name\\\"] for _, project in available_starter_projects\\n    )\\n\\n\\nasync def test_sqlite_pragmas():\\n    import asyncio\\n    import sqlite3\\n    from urllib.parse import unquote\\n\\n    # PRAGMA queries don't work well through SQLModel's async session abstraction\\n    # They need direct database access, so we use sqlite3 directly\\n    db_service = get_db_service()\\n    database_url = db_service.database_url\\n\\n    if not database_url.startswith(\\\"sqlite\\\"):\\n        pytest.skip(\\\"This test only works with SQLite databases\\\")\\n\\n    # Extract the database path from the URL\\n    if \\\"///\\\" in database_url:\\n        db_path = database_url.split(\\\"///\\\", 1)[1]\\n    elif \\\"//\\\" in database_url:\\n        db_path = database_url.split(\\\"//\\\", 1)[1]\\n    else:\\n        pytest.skip(\\\"Could not extract database path from URL\\\")\\n\\n    db_path = unquote(db_path)\\n\\n    def get_pragmas():\\n        conn = sqlite3.connect(db_path)\\n        try:\\n            conn.execute(\\\"PRAGMA journal_mode=wal;\\\")\\n            journal_mode = conn.execute(\\\"PRAGMA journal_mode;\\\").fetchone()[0]\\n            synchronous = conn.execute(\\\"PRAGMA synchronous;\\\").fetchone()[0]\\n            return journal_mode, synchronous\\n        finally:\\n            conn.close()\\n\\n    journal_mode, synchronous = await asyncio.to_thread(get_pragmas)\\n    assert journal_mode == \\\"wal\\\"\\n    assert synchronous in [0, 1, 2], f\\\"Unexpected synchronous value: {synchronous}\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"active_user\\\")\\nasync def test_read_folder(client: AsyncClient, logged_in_headers):\\n    # Create a new project\\n    folder_name = f\\\"Test Project {uuid4()}\\\"\\n    project = FolderCreate(name=folder_name, description=\\\"Test project description\\\")\\n    response = await client.post(\\\"api/v1/projects/\\\", json=project.model_dump(), headers=logged_in_headers)\\n    assert response.status_code == 201\\n    created_folder = response.json()\\n    folder_id = created_folder[\\\"id\\\"]\\n\\n    # Read the project\\n    response = await client.get(f\\\"api/v1/projects/{folder_id}\\\", headers=logged_in_headers)\\n    assert response.status_code == 200\\n    folder_data = response.json()\\n    assert folder_data[\\\"name\\\"] == folder_name\\n    assert folder_data[\\\"description\\\"] == \\\"Test project description\\\"\\n    assert \\\"flows\\\" in folder_data\\n    assert isinstance(folder_data[\\\"flows\\\"], list)\\n\\n\\n@pytest.mark.usefixtures(\\\"active_user\\\")\\nasync def test_read_folder_with_pagination(client: AsyncClient, logged_in_headers):\\n    # Create a new project\\n    folder_name = f\\\"Test Project {uuid4()}\\\"\\n    project = FolderCreate(name=folder_name, description=\\\"Test project description\\\")\\n    response = await client.post(\\\"api/v1/projects/\\\", json=project.model_dump(), headers=logged_in_headers)\\n    assert response.status_code == 201\\n    created_folder = response.json()\\n    folder_id = created_folder[\\\"id\\\"]\\n\\n    # Read the project with pagination\\n    response = await client.get(\\n        f\\\"api/v1/projects/{folder_id}\\\", headers=logged_in_headers, params={\\\"page\\\": 1, \\\"size\\\": 10}\\n    )\\n    assert response.status_code == 200\\n    folder_data = response.json()\\n    assert isinstance(folder_data, dict)\\n    assert \\\"folder\\\" in folder_data\\n    assert \\\"flows\\\" in folder_data\\n    assert folder_data[\\\"folder\\\"][\\\"name\\\"] == folder_name\\n    assert folder_data[\\\"folder\\\"][\\\"description\\\"] == \\\"Test project description\\\"\\n    assert folder_data[\\\"flows\\\"][\\\"page\\\"] == 1\\n    assert folder_data[\\\"flows\\\"][\\\"size\\\"] == 10\\n    assert isinstance(folder_data[\\\"flows\\\"][\\\"items\\\"], list)\\n\\n\\n@pytest.mark.usefixtures(\\\"active_user\\\")\\nasync def test_read_folder_with_flows(client: AsyncClient, json_flow: str, logged_in_headers):\\n    # Create a new project\\n    folder_name = f\\\"Test Project {uuid4()}\\\"\\n    flow_name = f\\\"Test Flow {uuid4()}\\\"\\n    project = FolderCreate(name=folder_name, description=\\\"Test project description\\\")\\n    response = await client.post(\\\"api/v1/projects/\\\", json=project.model_dump(), headers=logged_in_headers)\\n    assert response.status_code == 201\\n    created_folder = response.json()\\n    folder_id = UUID(created_folder[\\\"id\\\"])\\n\\n    # Create a flow in the project\\n    flow_data = orjson.loads(json_flow)\\n    data = flow_data[\\\"data\\\"]\\n    flow = FlowCreate(name=flow_name, description=\\\"description\\\", data=data)\\n    flow.folder_id = folder_id\\n    response = await client.post(\\\"api/v1/flows/\\\", json=flow.model_dump(mode=\\\"json\\\"), headers=logged_in_headers)\\n    assert response.status_code == 201\\n\\n    # Read the project with flows\\n    response = await client.get(f\\\"api/v1/projects/{folder_id}\\\", headers=logged_in_headers)\\n    assert response.status_code == 200\\n    folder_data = response.json()\\n    assert folder_data[\\\"name\\\"] == folder_name\\n    assert folder_data[\\\"description\\\"] == \\\"Test project description\\\"\\n    assert len(folder_data[\\\"flows\\\"]) == 1\\n    assert folder_data[\\\"flows\\\"][0][\\\"name\\\"] == flow_name\\n\\n\\n@pytest.mark.usefixtures(\\\"active_user\\\")\\nasync def test_read_nonexistent_folder(client: AsyncClient, logged_in_headers):\\n    nonexistent_id = str(uuid4())\\n    response = await client.get(f\\\"api/v1/projects/{nonexistent_id}\\\", headers=logged_in_headers)\\n    assert response.status_code == 404\\n    assert response.json()[\\\"detail\\\"] == \\\"Project not found\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"active_user\\\")\\nasync def test_read_folder_with_search(client: AsyncClient, json_flow: str, logged_in_headers):\\n    # Create a new project\\n    folder_name = f\\\"Test Project {uuid4()}\\\"\\n    project = FolderCreate(name=folder_name, description=\\\"Test project description\\\")\\n    response = await client.post(\\\"api/v1/projects/\\\", json=project.model_dump(), headers=logged_in_headers)\\n    assert response.status_code == 201\\n    created_folder = response.json()\\n    folder_id = UUID(created_folder[\\\"id\\\"])\\n\\n    # Create two flows in the project\\n    flow_data = orjson.loads(json_flow)\\n    flow_name_1 = f\\\"Test Flow 1 {uuid4()}\\\"\\n    flow_name_2 = f\\\"Another Flow {uuid4()}\\\"\\n\\n    flow1 = FlowCreate(\\n        name=flow_name_1, description=\\\"Test flow description\\\", data=flow_data[\\\"data\\\"], folder_id=folder_id\\n    )\\n    flow2 = FlowCreate(\\n        name=flow_name_2, description=\\\"Another flow description\\\", data=flow_data[\\\"data\\\"], folder_id=folder_id\\n    )\\n    flow1.folder_id = folder_id\\n    flow2.folder_id = folder_id\\n    await client.post(\\\"api/v1/flows/\\\", json=flow1.model_dump(mode=\\\"json\\\"), headers=logged_in_headers)\\n    await client.post(\\\"api/v1/flows/\\\", json=flow2.model_dump(mode=\\\"json\\\"), headers=logged_in_headers)\\n\\n    # Read the project with search\\n    response = await client.get(\\n        f\\\"api/v1/projects/{folder_id}\\\", headers=logged_in_headers, params={\\\"search\\\": \\\"Test\\\", \\\"page\\\": 1, \\\"size\\\": 10}\\n    )\\n    assert response.status_code == 200\\n    folder_data = response.json()\\n    assert len(folder_data[\\\"flows\\\"][\\\"items\\\"]) == 1\\n    assert folder_data[\\\"flows\\\"][\\\"items\\\"][0][\\\"name\\\"] == flow_name_1\\n\\n\\n@pytest.mark.usefixtures(\\\"active_user\\\")\\nasync def test_read_folder_with_component_filter(client: AsyncClient, json_flow: str, logged_in_headers):\\n    # Create a new project\\n    folder_name = f\\\"Test Project {uuid4()}\\\"\\n    project = FolderCreate(name=folder_name, description=\\\"Test project description\\\")\\n    response = await client.post(\\\"api/v1/projects/\\\", json=project.model_dump(), headers=logged_in_headers)\\n    assert response.status_code == 201\\n    created_folder = response.json()\\n    folder_id = UUID(created_folder[\\\"id\\\"])\\n\\n    # Create a component flow in the project\\n    flow_data = orjson.loads(json_flow)\\n    component_flow_name = f\\\"Component Flow {uuid4()}\\\"\\n    component_flow = FlowCreate(\\n        name=component_flow_name,\\n        description=\\\"Component flow description\\\",\\n        data=flow_data[\\\"data\\\"],\\n        folder_id=folder_id,\\n        is_component=True,\\n    )\\n    component_flow.folder_id = folder_id\\n    await client.post(\\\"api/v1/flows/\\\", json=component_flow.model_dump(mode=\\\"json\\\"), headers=logged_in_headers)\\n\\n    # Read the project with component filter\\n    response = await client.get(\\n        f\\\"api/v1/projects/{folder_id}\\\", headers=logged_in_headers, params={\\\"is_component\\\": True, \\\"page\\\": 1, \\\"size\\\": 10}\\n    )\\n    assert response.status_code == 200\\n    folder_data = response.json()\\n    assert len(folder_data[\\\"flows\\\"][\\\"items\\\"]) == 1\\n    assert folder_data[\\\"flows\\\"][\\\"items\\\"][0][\\\"name\\\"] == component_flow_name\\n    assert folder_data[\\\"flows\\\"][\\\"items\\\"][0][\\\"is_component\\\"] == True  # noqa: E712\\n\\n\\ndef test_transaction_excludes_code_key(session):\\n    \\\"\\\"\\\"Test that the code key is excluded from transaction inputs when logged to the database.\\\"\\\"\\\"\\n    from langflow.services.database.models.transactions.model import TransactionTable\\n\\n    # Create a flow to associate with the transaction\\n    flow = Flow(name=str(uuid4()), description=\\\"Test flow\\\", data={})\\n    session.add(flow)\\n    session.commit()\\n    session.refresh(flow)\\n\\n    # Create input data with a code key\\n    input_data = {\\\"param1\\\": \\\"value1\\\", \\\"param2\\\": \\\"value2\\\", \\\"code\\\": \\\"print('Hello, world!')\\\"}\\n\\n    # Create a transaction with inputs containing a code key\\n    transaction = TransactionTable(\\n        timestamp=datetime.now(timezone.utc),\\n        vertex_id=\\\"test-vertex\\\",\\n        target_id=\\\"test-target\\\",\\n        inputs=input_data,\\n        outputs={\\\"result\\\": \\\"success\\\"},\\n        status=\\\"completed\\\",\\n        flow_id=flow.id,\\n    )\\n\\n    # Verify that the code key is removed during transaction creation\\n    assert transaction.inputs is not None\\n    assert \\\"code\\\" not in transaction.inputs\\n    assert \\\"param1\\\" in transaction.inputs\\n    assert \\\"param2\\\" in transaction.inputs\\n\\n    # Add the transaction to the database\\n    session.add(transaction)\\n    session.commit()\\n    session.refresh(transaction)\\n\\n    # Verify that the code key is not in the saved transaction inputs\\n    assert transaction.inputs is not None\\n    assert \\\"code\\\" not in transaction.inputs\\n    assert \\\"param1\\\" in transaction.inputs\\n    assert \\\"param2\\\" in transaction.inputs\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_database_path_resolution.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"bb3231d8e16af1d79b626fc1035506d5d5e66b2ac927e6cad9735861d055258b\",\"content\":\"\\\"\\\"\\\"Tests for database path resolution in settings.\\n\\nThese tests verify that the database path is correctly resolved\\nbased on the save_db_in_config_dir setting and langflow package availability.\\n\\\"\\\"\\\"\\n\\nimport os\\nfrom pathlib import Path\\nfrom unittest.mock import patch\\n\\n\\nclass TestDatabasePathResolution:\\n    \\\"\\\"\\\"Test database path resolution in Settings.\\\"\\\"\\\"\\n\\n    def test_database_path_uses_langflow_package_when_save_db_in_config_dir_false(self, tmp_path):\\n        \\\"\\\"\\\"When save_db_in_config_dir=False, database should be in langflow package dir.\\\"\\\"\\\"\\n        import langflow\\n        from lfx.services.settings.base import Settings\\n\\n        env_vars = {\\n            \\\"LANGFLOW_CONFIG_DIR\\\": str(tmp_path),\\n            \\\"LANGFLOW_SAVE_DB_IN_CONFIG_DIR\\\": \\\"false\\\",\\n        }\\n        # Remove DATABASE_URL from env to trigger path resolution\\n        env = {k: v for k, v in os.environ.items() if k != \\\"LANGFLOW_DATABASE_URL\\\"}\\n        env.update(env_vars)\\n\\n        with patch.dict(os.environ, env, clear=True):\\n            settings = Settings()\\n\\n        expected_dir = Path(langflow.__file__).parent.resolve()\\n        assert settings.database_url is not None\\n        # The database_url should contain the langflow package path\\n        assert str(expected_dir) in settings.database_url\\n\\n    def test_database_path_uses_config_dir_when_save_db_in_config_dir_true(self, tmp_path):\\n        \\\"\\\"\\\"When save_db_in_config_dir=True, database should be in config_dir.\\\"\\\"\\\"\\n        from lfx.services.settings.base import Settings\\n\\n        config_dir = tmp_path / \\\"config\\\"\\n        config_dir.mkdir()\\n\\n        env_vars = {\\n            \\\"LANGFLOW_CONFIG_DIR\\\": str(config_dir),\\n            \\\"LANGFLOW_SAVE_DB_IN_CONFIG_DIR\\\": \\\"true\\\",\\n        }\\n        # Remove DATABASE_URL from env to trigger path resolution\\n        env = {k: v for k, v in os.environ.items() if k != \\\"LANGFLOW_DATABASE_URL\\\"}\\n        env.update(env_vars)\\n\\n        with patch.dict(os.environ, env, clear=True):\\n            settings = Settings()\\n\\n        assert settings.database_url is not None\\n        assert str(config_dir) in settings.database_url\\n\\n    def test_database_path_falls_back_to_lfx_when_langflow_not_importable(self, tmp_path):\\n        \\\"\\\"\\\"When langflow is not importable, should fall back to lfx package path.\\\"\\\"\\\"\\n        import builtins\\n\\n        import lfx.services.settings.base as settings_module\\n        from lfx.services.settings.base import Settings\\n\\n        original_import = builtins.__import__\\n\\n        def mock_import(name, *args, **kwargs):\\n            if name == \\\"langflow\\\":\\n                raise ImportError(name)\\n            return original_import(name, *args, **kwargs)\\n\\n        env_vars = {\\n            \\\"LANGFLOW_CONFIG_DIR\\\": str(tmp_path),\\n            \\\"LANGFLOW_SAVE_DB_IN_CONFIG_DIR\\\": \\\"false\\\",\\n        }\\n        env = {k: v for k, v in os.environ.items() if k != \\\"LANGFLOW_DATABASE_URL\\\"}\\n        env.update(env_vars)\\n\\n        with (\\n            patch.dict(os.environ, env, clear=True),\\n            patch.object(builtins, \\\"__import__\\\", side_effect=mock_import),\\n        ):\\n            settings = Settings()\\n\\n        # Should fall back to lfx path\\n        lfx_path = Path(settings_module.__file__).parent.parent.parent.resolve()\\n        assert settings.database_url is not None\\n        assert str(lfx_path) in settings.database_url\\n\\n    def test_explicit_database_url_env_var_takes_precedence(self, tmp_path):\\n        \\\"\\\"\\\"LANGFLOW_DATABASE_URL env var should take precedence over path resolution.\\\"\\\"\\\"\\n        from lfx.services.settings.base import Settings\\n\\n        custom_url = \\\"sqlite:///custom/path/test.db\\\"\\n\\n        with patch.dict(\\n            os.environ,\\n            {\\\"LANGFLOW_DATABASE_URL\\\": custom_url, \\\"LANGFLOW_CONFIG_DIR\\\": str(tmp_path)},\\n            clear=False,\\n        ):\\n            settings = Settings(config_dir=str(tmp_path))\\n\\n        assert settings.database_url == custom_url\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_database_windows_postgres_integration.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3d86dba5a8abfe80c73d1fae230f0a2de4c1c61238e5b793f2e4881225e628df\",\"content\":\"\\\"\\\"\\\"Integration tests for database service with Windows + PostgreSQL fix.\\n\\nTests that the database service properly handles event loop configuration\\nacross different platforms and database types.\\n\\\"\\\"\\\"\\n\\nimport asyncio\\nimport os\\nfrom unittest.mock import MagicMock, patch\\n\\nimport pytest\\nfrom langflow.services.database.service import DatabaseService\\n\\n\\nclass TestDatabaseServiceWindowsPostgres:\\n    \\\"\\\"\\\"Test database service with Windows + PostgreSQL event loop configuration.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def mock_settings_service(self):\\n        \\\"\\\"\\\"Create a mock settings service for testing.\\\"\\\"\\\"\\n        mock_service = MagicMock()\\n        mock_service.settings.database_url = \\\"sqlite:///test.db\\\"\\n        mock_service.settings.database_connection_retry = False\\n        mock_service.settings.sqlite_pragmas = {}\\n        mock_service.settings.db_driver_connection_settings = None\\n        mock_service.settings.db_connection_settings = {}\\n        mock_service.settings.alembic_log_to_stdout = True\\n        mock_service.settings.alembic_log_file = \\\"alembic.log\\\"\\n        return mock_service\\n\\n    @patch(\\\"platform.system\\\")\\n    @patch.dict(os.environ, {\\\"LANGFLOW_DATABASE_URL\\\": \\\"postgresql://user:pass@localhost/db\\\"}, clear=True)\\n    @patch(\\\"langflow.services.database.service.create_async_engine\\\")\\n    @patch(\\\"langflow.services.database.service.configure_windows_postgres_event_loop\\\")\\n    def test_windows_postgresql_configures_event_loop(\\n        self, mock_configure, mock_create_engine, mock_platform, mock_settings_service\\n    ):\\n        \\\"\\\"\\\"Test that Windows + PostgreSQL configures the event loop correctly.\\\"\\\"\\\"\\n        mock_platform.return_value = \\\"Windows\\\"\\n        mock_settings_service.settings.database_url = \\\"postgresql://user:pass@localhost/db\\\"\\n        mock_create_engine.return_value = MagicMock()\\n        mock_configure.return_value = True\\n\\n        _ = DatabaseService(mock_settings_service)\\n        mock_configure.assert_called_once_with(source=\\\"database_service\\\")\\n\\n    @patch(\\\"platform.system\\\")\\n    @patch.dict(os.environ, {}, clear=True)\\n    @patch(\\\"langflow.services.database.service.create_async_engine\\\")\\n    def test_linux_postgresql_no_event_loop_change(self, mock_create_engine, mock_platform, mock_settings_service):\\n        \\\"\\\"\\\"Test that Linux + PostgreSQL doesn't change event loop.\\\"\\\"\\\"\\n        mock_platform.return_value = \\\"Linux\\\"\\n        mock_settings_service.settings.database_url = \\\"postgresql://user:pass@localhost/db\\\"\\n        mock_create_engine.return_value = MagicMock()\\n\\n        original_policy = asyncio.get_event_loop_policy()\\n        _ = DatabaseService(mock_settings_service)\\n\\n        # Policy should remain unchanged\\n        assert asyncio.get_event_loop_policy() is original_policy\\n\\n    @patch(\\\"platform.system\\\")\\n    @patch.dict(os.environ, {}, clear=True)\\n    @patch(\\\"langflow.services.database.service.create_async_engine\\\")\\n    def test_macos_postgresql_no_event_loop_change(self, mock_create_engine, mock_platform, mock_settings_service):\\n        \\\"\\\"\\\"Test that macOS + PostgreSQL doesn't change event loop.\\\"\\\"\\\"\\n        mock_platform.return_value = \\\"Darwin\\\"\\n        mock_settings_service.settings.database_url = \\\"postgresql://user:pass@localhost/db\\\"\\n        mock_create_engine.return_value = MagicMock()\\n\\n        original_policy = asyncio.get_event_loop_policy()\\n        _ = DatabaseService(mock_settings_service)\\n\\n        # Policy should remain unchanged\\n        assert asyncio.get_event_loop_policy() is original_policy\\n\\n    @patch(\\\"platform.system\\\")\\n    @patch.dict(os.environ, {}, clear=True)\\n    @patch(\\\"langflow.services.database.service.create_async_engine\\\")\\n    @patch(\\\"langflow.services.database.service.configure_windows_postgres_event_loop\\\")\\n    def test_windows_sqlite_no_event_loop_change(\\n        self, mock_configure, mock_create_engine, mock_platform, mock_settings_service\\n    ):\\n        \\\"\\\"\\\"Test that Windows + SQLite doesn't change event loop.\\\"\\\"\\\"\\n        mock_platform.return_value = \\\"Windows\\\"\\n        mock_settings_service.settings.database_url = \\\"sqlite:///test.db\\\"\\n        mock_create_engine.return_value = MagicMock()\\n        mock_configure.return_value = False\\n\\n        _ = DatabaseService(mock_settings_service)\\n        mock_configure.assert_called_once_with(source=\\\"database_service\\\")\\n\\n    def test_database_url_sanitization(self, mock_settings_service):\\n        \\\"\\\"\\\"Test that database URLs are properly sanitized.\\\"\\\"\\\"\\n        test_cases = [\\n            (\\\"sqlite:///test.db\\\", \\\"sqlite+aiosqlite:///test.db\\\"),\\n            (\\\"postgresql://user:pass@localhost/db\\\", \\\"postgresql+psycopg://user:pass@localhost/db\\\"),\\n            (\\\"postgres://user:pass@localhost/db\\\", \\\"postgresql+psycopg://user:pass@localhost/db\\\"),\\n        ]\\n\\n        with patch(\\\"langflow.services.database.service.create_async_engine\\\") as mock_create_engine:\\n            mock_create_engine.return_value = MagicMock()\\n\\n            for input_url, expected_url in test_cases:\\n                mock_settings_service.settings.database_url = input_url\\n                service = DatabaseService(mock_settings_service)\\n                assert service.database_url == expected_url\\n\\n    @patch(\\\"platform.system\\\")\\n    def test_docker_environment_compatibility(self, mock_platform, mock_settings_service):\\n        \\\"\\\"\\\"Test that Docker environments work correctly.\\\"\\\"\\\"\\n        mock_platform.return_value = \\\"Linux\\\"\\n        os.environ[\\\"DOCKER_CONTAINER\\\"] = \\\"true\\\"\\n        mock_settings_service.settings.database_url = \\\"postgresql://postgres:5432/langflow\\\"\\n\\n        with patch(\\\"langflow.services.database.service.create_async_engine\\\") as mock_create_engine:\\n            mock_create_engine.return_value = MagicMock()\\n\\n            # Should not raise any errors\\n            service = DatabaseService(mock_settings_service)\\n            assert service.database_url == \\\"postgresql+psycopg://postgres:5432/langflow\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_async_operations_work_after_configuration(self, mock_settings_service):\\n        \\\"\\\"\\\"Test that async operations work correctly after event loop configuration.\\\"\\\"\\\"\\n        mock_settings_service.settings.database_url = \\\"sqlite:///test.db\\\"\\n\\n        with patch(\\\"langflow.services.database.service.create_async_engine\\\") as mock_create_engine:\\n            mock_engine = MagicMock()\\n            mock_create_engine.return_value = mock_engine\\n\\n            service = DatabaseService(mock_settings_service)\\n\\n            # Test that async session maker is properly configured\\n            assert service.async_session_maker is not None\\n\\n            # Simulate an async operation\\n            async def test_async():\\n                return True\\n\\n            result = await test_async()\\n            assert result is True\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_docker_security_defaults.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f246a44d28f345da940b55738b7018ad11c6f2dfd8440817e827487ff7b19607\",\"content\":\"import shlex\\nimport sys\\nfrom pathlib import Path\\n\\nimport pytest\\n\\nif sys.version_info >= (3, 11):\\n    import tomllib\\nelse:\\n    import tomli as tomllib\\n\\nREPO_ROOT = Path(__file__).resolve().parents[4]\\nPUBLISHED_IMAGES = (\\n    pytest.param(\\\"build_and_push.Dockerfile\\\", \\\"base\\\", id=\\\"base\\\"),\\n    pytest.param(\\\"build_and_push.Dockerfile\\\", \\\"full\\\", id=\\\"full\\\"),\\n    pytest.param(\\\"build_and_push.Dockerfile\\\", \\\"full-bundles\\\", id=\\\"full-bundles\\\"),\\n    pytest.param(\\\"build_and_push_backend.Dockerfile\\\", None, id=\\\"backend\\\"),\\n    pytest.param(\\\"build_and_push_ep.Dockerfile\\\", None, id=\\\"ep\\\"),\\n)\\nRESTRICTIVE_RUNTIME_ENV_VARS = frozenset(\\n    {\\n        \\\"LANGFLOW_ALLOW_CUSTOM_COMPONENTS\\\",\\n        \\\"LANGFLOW_BLOCK_CODE_INTERPRETER_COMPONENTS\\\",\\n        \\\"LANGFLOW_RESTRICT_LOCAL_FILE_ACCESS\\\",\\n        \\\"LANGFLOW_CONNECTOR_SSRF_ALLOW_LOOPBACK\\\",\\n        \\\"LANGFLOW_MCP_SERVER_DOCKER_HARDENING\\\",\\n        \\\"LANGFLOW_MCP_SERVER_INTERPRETER_HARDENING\\\",\\n        \\\"LANGFLOW_MCP_SERVER_ALLOWED_PACKAGES\\\",\\n    }\\n)\\n\\n\\ndef _logical_instructions(dockerfile: Path) -> list[str]:\\n    \\\"\\\"\\\"Collapse Dockerfile continuations while ignoring blank and comment lines.\\\"\\\"\\\"\\n    instructions: list[str] = []\\n    current = \\\"\\\"\\n    for raw_line in dockerfile.read_text(encoding=\\\"utf-8\\\").splitlines():\\n        line = raw_line.strip()\\n        if not line or line.startswith(\\\"#\\\"):\\n            continue\\n        if line.endswith(\\\"\\\\\\\\\\\"):\\n            current += f\\\"{line[:-1].rstrip()} \\\"\\n            continue\\n        current += line\\n        instructions.append(current)\\n        current = \\\"\\\"\\n    if current:\\n        instructions.append(current)\\n    return instructions\\n\\n\\ndef _apply_env_instruction(env: dict[str, str], payload: str) -> None:\\n    assignments = shlex.split(payload)\\n    if assignments and \\\"=\\\" not in assignments[0]:\\n        env[assignments[0]] = \\\" \\\".join(assignments[1:])\\n        return\\n    for assignment in assignments:\\n        key, has_value, value = assignment.partition(\\\"=\\\")\\n        if has_value:\\n            env[key] = value\\n\\n\\ndef _dockerfile_stages(dockerfile: Path) -> tuple[dict[str, dict[str, str]], dict[str, str], str]:\\n    \\\"\\\"\\\"Return inherited stage envs, stage bases, and the final target name.\\\"\\\"\\\"\\n    stage_envs: dict[str, dict[str, str]] = {}\\n    stage_bases: dict[str, str] = {}\\n    current_stage = \\\"\\\"\\n    final_stage = \\\"\\\"\\n\\n    for instruction in _logical_instructions(dockerfile):\\n        parts = instruction.split(maxsplit=1)\\n        if len(parts) != 2:\\n            continue\\n        keyword, payload = parts\\n        if keyword.upper() == \\\"FROM\\\":\\n            tokens = shlex.split(payload)\\n            base_index = next(index for index, token in enumerate(tokens) if not token.startswith(\\\"--\\\"))\\n            base = tokens[base_index].lower()\\n            as_index = next((index for index, token in enumerate(tokens) if token.lower() == \\\"as\\\"), None)\\n            current_stage = tokens[as_index + 1].lower() if as_index is not None else f\\\"__stage_{len(stage_envs)}\\\"\\n            stage_envs[current_stage] = stage_envs.get(base, {}).copy()\\n            stage_bases[current_stage] = base\\n            final_stage = current_stage\\n            continue\\n        if keyword.upper() == \\\"ENV\\\" and current_stage:\\n            _apply_env_instruction(stage_envs[current_stage], payload)\\n\\n    return stage_envs, stage_bases, final_stage\\n\\n\\ndef _target_env(dockerfile: Path, target: str | None = None) -> dict[str, str]:\\n    stage_envs, _, final_stage = _dockerfile_stages(dockerfile)\\n    return stage_envs[(target or final_stage).lower()]\\n\\n\\n@pytest.mark.parametrize((\\\"dockerfile\\\", \\\"target\\\"), PUBLISHED_IMAGES)\\ndef test_published_images_use_writable_runtime_home(dockerfile: str, target: str | None) -> None:\\n    assert _target_env(REPO_ROOT / \\\"docker\\\" / dockerfile, target).get(\\\"HOME\\\") == \\\"/app/data\\\"\\n\\n\\ndef test_consolidated_and_lfx_images_create_writable_runtime_home() -> None:\\n    sources = (\\n        (REPO_ROOT / \\\"docker\\\" / \\\"build_and_push.Dockerfile\\\").read_text(encoding=\\\"utf-8\\\"),\\n        (REPO_ROOT / \\\"src\\\" / \\\"lfx\\\" / \\\"docker\\\" / \\\"Dockerfile\\\").read_text(encoding=\\\"utf-8\\\"),\\n    )\\n    for source in sources:\\n        assert \\\"mkdir -p /app/data\\\" in source\\n        assert \\\"chown -R 1000:0 /app/data\\\" in source\\n        assert \\\"chmod -R g+rwX /app/data\\\" in source\\n\\n\\n@pytest.mark.parametrize((\\\"dockerfile\\\", \\\"target\\\"), PUBLISHED_IMAGES)\\ndef test_published_images_do_not_force_restrictive_runtime_defaults(dockerfile: str, target: str | None) -> None:\\n    runtime_env = _target_env(REPO_ROOT / \\\"docker\\\" / dockerfile, target)\\n\\n    assert runtime_env[\\\"LANGFLOW_AUTO_LOGIN\\\"] == \\\"false\\\"\\n    assert RESTRICTIVE_RUNTIME_ENV_VARS.isdisjoint(runtime_env)\\n\\n\\ndef test_target_env_parses_inheritance_overrides_multiple_assignments_and_continuations(tmp_path: Path) -> None:\\n    dockerfile = tmp_path / \\\"Dockerfile\\\"\\n    dockerfile.write_text(\\n        \\\"\\\"\\\"FROM builder\\nENV LANGFLOW_ALLOW_CUSTOM_COMPONENTS=builder\\nFROM builder AS runtime\\nenv\\\\tLANGFLOW_ALLOW_CUSTOM_COMPONENTS=false OTHER=first \\\\\\\\\\n    THIRD=three\\nFROM runtime AS base\\nENV OTHER=base\\nFROM runtime AS full\\nENV OTHER=second LANGFLOW_ALLOW_CUSTOM_COMPONENTS=true\\nENV LEGACY value with spaces\\n\\\"\\\"\\\",\\n        encoding=\\\"utf-8\\\",\\n    )\\n\\n    assert _target_env(dockerfile, \\\"base\\\") == {\\n        \\\"LANGFLOW_ALLOW_CUSTOM_COMPONENTS\\\": \\\"false\\\",\\n        \\\"OTHER\\\": \\\"base\\\",\\n        \\\"THIRD\\\": \\\"three\\\",\\n    }\\n    assert _target_env(dockerfile) == {\\n        \\\"LANGFLOW_ALLOW_CUSTOM_COMPONENTS\\\": \\\"true\\\",\\n        \\\"OTHER\\\": \\\"second\\\",\\n        \\\"THIRD\\\": \\\"three\\\",\\n        \\\"LEGACY\\\": \\\"value with spaces\\\",\\n    }\\n\\n\\ndef test_base_and_full_targets_share_one_runtime_defaults_contract() -> None:\\n    dockerfile = REPO_ROOT / \\\"docker\\\" / \\\"build_and_push.Dockerfile\\\"\\n    stage_envs, stage_bases, final_stage = _dockerfile_stages(dockerfile)\\n\\n    assert final_stage == \\\"full\\\"\\n    assert stage_bases[\\\"base\\\"] == \\\"runtime\\\"\\n    assert stage_bases[\\\"full\\\"] == \\\"runtime\\\"\\n    assert stage_bases[\\\"base-builder\\\"] == \\\"base-dependencies\\\"\\n    assert stage_bases[\\\"full-builder\\\"] == \\\"full-dependencies\\\"\\n\\n    for target in (\\\"base\\\", \\\"full\\\"):\\n        assert stage_envs[target][\\\"LANGFLOW_AUTO_LOGIN\\\"] == \\\"false\\\"\\n        assert RESTRICTIVE_RUNTIME_ENV_VARS.isdisjoint(stage_envs[target])\\n\\n    source = dockerfile.read_text(encoding=\\\"utf-8\\\")\\n    assert source.count(\\\"LANGFLOW_AUTO_LOGIN=\\\") == 1\\n    for key in RESTRICTIVE_RUNTIME_ENV_VARS:\\n        assert f\\\"{key}=\\\" not in source\\n\\n    assert not (REPO_ROOT / \\\"docker\\\" / \\\"build_and_push_base.Dockerfile\\\").exists()\\n    assert not (REPO_ROOT / \\\"docker\\\" / \\\"build_and_push_with_extras.Dockerfile\\\").exists()\\n\\n\\ndef test_public_docker_targets_apply_release_version_overrides() -> None:\\n    dockerfile = (REPO_ROOT / \\\"docker\\\" / \\\"build_and_push.Dockerfile\\\").read_text(encoding=\\\"utf-8\\\")\\n    workflow = (REPO_ROOT / \\\".github\\\" / \\\"workflows\\\" / \\\"docker-build-v2.yml\\\").read_text(encoding=\\\"utf-8\\\")\\n\\n    assert 'ARG BASE_VERSION=\\\"\\\"' in dockerfile\\n    assert \\\"/app/src/backend/base/pyproject.toml\\\" in dockerfile\\n    assert 'ARG MAIN_VERSION=\\\"\\\"' in dockerfile\\n    assert \\\"/app/pyproject.toml\\\" in dockerfile\\n    assert 'm.version(\\\"langflow\\\")' in dockerfile\\n    assert 'm.version(\\\"langflow-base\\\")' in dockerfile\\n    source = (REPO_ROOT / \\\"docker\\\" / \\\"build_and_push_ep.Dockerfile\\\").read_text(encoding=\\\"utf-8\\\")\\n    assert 'ARG MAIN_VERSION=\\\"\\\"' in source\\n    assert 'ARG BASE_VERSION=\\\"\\\"' in source\\n    assert 'm.version(\\\"langflow\\\")' in source\\n    assert 'm.version(\\\"langflow-base\\\")' in source\\n\\n    assert workflow.count(\\\"MAIN_VERSION=${{ needs.determine-main-version.outputs.version }}\\\") == 6\\n    assert workflow.count(\\\"BASE_VERSION=${{ needs.determine-main-version.outputs.version }}\\\") == 6\\n    assert workflow.count(\\\"BASE_VERSION=${{ needs.determine-base-version.outputs.version }}\\\") == 2\\n\\n\\ndef test_full_target_checks_only_default_workspace_distributions() -> None:\\n    dockerfile = (REPO_ROOT / \\\"docker\\\" / \\\"build_and_push.Dockerfile\\\").read_text(encoding=\\\"utf-8\\\")\\n\\n    assert 'required = {\\\"langflow\\\", \\\"langflow-base\\\"}' in dockerfile\\n    assert '{\\\"torch\\\", \\\"torchvision\\\"} & names' in dockerfile\\n\\n\\ndef test_published_images_pin_hardened_package_managers() -> None:\\n    install_script = (REPO_ROOT / \\\"docker\\\" / \\\"install_hardened_npm.sh\\\").read_text(encoding=\\\"utf-8\\\")\\n\\n    assert 'NPM_VERSION=\\\"12.0.2\\\"' in install_script\\n    assert 'npm install --global \\\"npm@${NPM_VERSION}\\\"' in install_script\\n    assert 'actual_npm_version=\\\"$(npm --version)\\\"' in install_script\\n    assert 'if [ \\\"$actual_npm_version\\\" != \\\"$NPM_VERSION\\\" ]; then' in install_script\\n\\n    for variable, version, package, validation_entry in (\\n        (\\\"IP_ADDRESS_VERSION\\\", \\\"10.3.1\\\", \\\"ip-address\\\", '\\\"ip-address\\\": \\\"10.3.1\\\"'),\\n        (\\\"BRACE_EXPANSION_VERSION\\\", \\\"5.0.9\\\", \\\"brace-expansion\\\", '\\\"brace-expansion\\\": \\\"5.0.9\\\"'),\\n        (\\\"TAR_VERSION\\\", \\\"7.5.22\\\", \\\"tar\\\", 'tar: \\\"7.5.22\\\"'),\\n        (\\\"UNDICI_VERSION\\\", \\\"6.28.0\\\", \\\"undici\\\", 'undici: \\\"6.28.0\\\"'),\\n    ):\\n        assert f'{variable}=\\\"{version}\\\"' in install_script\\n        assert f'\\\"{package}@${{{variable}}}\\\"' in install_script\\n        assert validation_entry in install_script\\n\\n    assert \\\"for package in ip-address brace-expansion tar undici; do\\\" in install_script\\n    for validation_entry in (\\n        'sigstore: \\\"5.0.0\\\"',\\n        '\\\"@sigstore/core\\\": \\\"4.0.1\\\"',\\n        '\\\"tinyglobby/node_modules/picomatch\\\": \\\"4.0.5\\\"',\\n    ):\\n        assert validation_entry in install_script\\n    assert \\\"npm ls --global --all --omit=dev\\\" in install_script\\n    assert 'rm -rf \\\"$npm_cache\\\" /tmp/node-compile-cache' in install_script\\n\\n    for dockerfile in (\\n        \\\"build_and_push.Dockerfile\\\",\\n        \\\"build_and_push_backend.Dockerfile\\\",\\n        \\\"build_and_push_ep.Dockerfile\\\",\\n    ):\\n        source = (REPO_ROOT / \\\"docker\\\" / dockerfile).read_text(encoding=\\\"utf-8\\\")\\n        assert 'python3.14 -m pip install --no-cache-dir --upgrade \\\"pip==26.2.1\\\"' in source\\n        assert \\\"sh /tmp/install_hardened_npm.sh\\\" in source\\n\\n    backend_project = tomllib.loads(\\n        (REPO_ROOT / \\\"src\\\" / \\\"backend\\\" / \\\"base\\\" / \\\"pyproject.toml\\\").read_text(encoding=\\\"utf-8\\\")\\n    )\\n    assert \\\"pip>=26.2.1,<27.0.0\\\" in backend_project[\\\"project\\\"][\\\"dependencies\\\"]\\n\\n    lockfile = tomllib.loads((REPO_ROOT / \\\"uv.lock\\\").read_text(encoding=\\\"utf-8\\\"))\\n    locked_pip_versions = {package[\\\"version\\\"] for package in lockfile[\\\"package\\\"] if package[\\\"name\\\"] == \\\"pip\\\"}\\n    assert locked_pip_versions == {\\\"26.2.1\\\"}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_end_user_ephemeral_persistence.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9347f53d80aa3e1650eb0c79c0500be47fce594f965fb48b1b723beeb48f2ad0\",\"content\":\"\\\"\\\"\\\"Serving-plane anonymous runs are ephemeral: astore_message must not persist.\\n\\nThe end-user scoping marks an anonymous run's graph ``persist_messages = False``;\\n``get_instance_results`` binds that onto the ambient ``should_persist_messages``\\nflag per component execution, and ``astore_message`` honors it by returning the\\nmessage without writing a row. Identified/normal runs (the True default) persist\\nexactly as before.\\n\\\"\\\"\\\"\\n\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.api.v2.workflow import _parse_persisted_workflow_request\\nfrom langflow.memory import aget_messages, astore_message\\nfrom langflow.schema.message import Message\\nfrom lfx.components.input_output import ChatInput, ChatOutput\\nfrom lfx.graph.graph.base import Graph\\nfrom lfx.memory.flow_context import reset_messages_persist, set_messages_persist\\nfrom lfx.schema.workflow import WorkflowRunRequest\\n\\n\\ndef _msg(session_id: str) -> Message:\\n    return Message(text=\\\"remember me\\\", sender=\\\"User\\\", sender_name=\\\"User\\\", session_id=session_id)\\n\\n\\nasync def test_astore_message_persists_by_default(client):  # noqa: ARG001\\n    session_id = f\\\"persist-{uuid4()}\\\"\\n    await astore_message(_msg(session_id))\\n    stored = await aget_messages(session_id=session_id)\\n    assert [m.text for m in stored] == [\\\"remember me\\\"]\\n\\n\\nasync def test_astore_message_skips_write_when_not_persisting(client):  # noqa: ARG001\\n    session_id = f\\\"ephemeral-{uuid4()}\\\"\\n    token = set_messages_persist(persist=False)\\n    try:\\n        returned = await astore_message(_msg(session_id))\\n    finally:\\n        reset_messages_persist(token)\\n\\n    # The caller still gets its message back (in-run behavior unchanged)...\\n    assert [m.text for m in returned] == [\\\"remember me\\\"]\\n    # ...but nothing was persisted.\\n    assert await aget_messages(session_id=session_id) == []\\n\\n\\nasync def test_flag_resets_after_run(client):  # noqa: ARG001\\n    session_id = f\\\"reset-{uuid4()}\\\"\\n    token = set_messages_persist(persist=False)\\n    reset_messages_persist(token)\\n    # Back to the default: persistence works again.\\n    await astore_message(_msg(session_id))\\n    assert len(await aget_messages(session_id=session_id)) == 1\\n\\n\\nasync def test_anonymous_graph_run_persists_nothing_end_to_end(client):  # noqa: ARG001\\n    \\\"\\\"\\\"A graph marked non-persisting runs ChatInput->ChatOutput but writes no memory.\\\"\\\"\\\"\\n    session_id = f\\\"anon-e2e-{uuid4()}\\\"\\n    chat_input = ChatInput(_id=\\\"chat_input\\\")\\n    chat_input.set(input_value=\\\"hi there\\\")\\n    chat_output = ChatOutput(_id=\\\"chat_output\\\")\\n    chat_output.set(input_value=chat_input.message_response)\\n\\n    graph = Graph(chat_input, chat_output, flow_id=str(uuid4()))\\n    graph.session_id = session_id\\n    graph.persist_messages = False  # anonymous / ephemeral\\n\\n    async for _ in graph.async_start():\\n        pass\\n\\n    # ChatInput/ChatOutput default should_store_message=True, but the ephemeral\\n    # flag must have suppressed every write.\\n    assert await aget_messages(session_id=session_id) == []\\n\\n\\nasync def test_nested_default_graph_cannot_reenable_persistence(client):  # noqa: ARG001\\n    \\\"\\\"\\\"The binding is monotonically restrictive (review B3).\\n\\n    Nested graphs built with ``Graph.from_payload`` (Run Flow, Sub Flow, Flow as\\n    Tool, A2A) default ``persist_messages = True``. Under an ephemeral outer run\\n    that default must not overwrite the ambient no-persist decision \u2014 modeled here\\n    by running a default-persisting graph inside an outer ephemeral binding.\\n    \\\"\\\"\\\"\\n    session_id = f\\\"nested-anon-{uuid4()}\\\"\\n    chat_input = ChatInput(_id=\\\"chat_input\\\")\\n    chat_input.set(input_value=\\\"hi there\\\")\\n    chat_output = ChatOutput(_id=\\\"chat_output\\\")\\n    chat_output.set(input_value=chat_input.message_response)\\n\\n    graph = Graph(chat_input, chat_output, flow_id=str(uuid4()))\\n    graph.session_id = session_id\\n    # NOTE: graph.persist_messages stays at its True default, like a nested\\n    # Graph.from_payload graph inside an anonymous outer run.\\n\\n    token = set_messages_persist(persist=False)  # the outer run's decision\\n    try:\\n        async for _ in graph.async_start():\\n            pass\\n    finally:\\n        reset_messages_persist(token)\\n\\n    assert await aget_messages(session_id=session_id) == []\\n\\n\\nasync def test_memory_component_store_does_not_crash_on_ephemeral_run(client):  # noqa: ARG001\\n    \\\"\\\"\\\"Memory component (store mode) must degrade gracefully, not crash.\\n\\n    Its store path does a write-then-read-back and raises when the read-back is\\n    empty \u2014 which is exactly what an ephemeral run produces. The component must\\n    return the in-run message instead of crashing the flow.\\n    \\\"\\\"\\\"\\n    from lfx.components.models_and_agents.memory import MemoryComponent\\n\\n    session_id = f\\\"memcomp-anon-{uuid4()}\\\"\\n    component = MemoryComponent(_id=\\\"memory\\\")\\n    component.set(\\n        mode=\\\"Store\\\",\\n        message=\\\"remember me\\\",\\n        session_id=session_id,\\n        sender=\\\"User\\\",\\n        sender_name=\\\"User\\\",\\n    )\\n\\n    token = set_messages_persist(persist=False)\\n    try:\\n        stored = await component.store_message()\\n    finally:\\n        reset_messages_persist(token)\\n\\n    assert stored.text == \\\"remember me\\\"\\n    assert await aget_messages(session_id=session_id) == []\\n\\n\\nasync def test_update_stored_message_is_noop_on_ephemeral_run(client):  # noqa: ARG001\\n    \\\"\\\"\\\"Streaming finalization must not require a DB row on ephemeral runs.\\n\\n    ``_update_stored_message`` is called at the end of token streaming; on an\\n    ephemeral run the message was never stored (no id), so the update must be a\\n    no-op instead of raising \\\"Message with id None not found\\\".\\n    \\\"\\\"\\\"\\n    component = ChatOutput(_id=\\\"chat_output\\\")\\n    message = _msg(f\\\"ephemeral-update-{uuid4()}\\\")\\n\\n    token = set_messages_persist(persist=False)\\n    try:\\n        result = await component._update_stored_message(message)\\n    finally:\\n        reset_messages_persist(token)\\n\\n    assert result.text == \\\"remember me\\\"\\n\\n\\nasync def test_send_message_skip_db_update_allows_ephemeral_unstored(client, monkeypatch):  # noqa: ARG001\\n    \\\"\\\"\\\"Agent token streaming uses send_message(skip_db_update=True) per chunk.\\n\\n    Ephemeral messages never have an id, so the \\\"must already have an ID\\\" guard\\n    must not fire when persistence is off \u2014 otherwise any anonymous run with an\\n    Agent component crashes mid-stream.\\n    \\\"\\\"\\\"\\n    component = ChatOutput(_id=\\\"chat_output\\\")\\n    monkeypatch.setattr(component, \\\"_should_skip_message\\\", lambda _msg: False)\\n    message = _msg(f\\\"ephemeral-skipdb-{uuid4()}\\\")\\n\\n    token = set_messages_persist(persist=False)\\n    try:\\n        result = await component.send_message(message, skip_db_update=True)\\n    finally:\\n        reset_messages_persist(token)\\n\\n    assert result.text == \\\"remember me\\\"\\n    assert not result.has_id()\\n\\n\\n# --- background / resume round-trip -------------------------------------------\\n# The background and HITL-resume paths persist the request and re-parse it on the\\n# worker. persist_messages is an internal decision, not a client wire field, so it\\n# must survive that round-trip or an anonymous background run would wrongly persist.\\n\\n\\ndef _bg_request(session_id: str, **extra) -> dict:\\n    return {\\n        \\\"flow_id\\\": str(uuid4()),\\n        \\\"mode\\\": \\\"background\\\",\\n        \\\"input_value\\\": \\\"hi\\\",\\n        \\\"session_id\\\": session_id,\\n        **extra,\\n    }\\n\\n\\ndef test_workflow_run_request_forbids_persist_messages_extra():\\n    # Guards why the pop is required: WorkflowRunRequest rejects the internal field.\\n    with pytest.raises(Exception, match=r\\\"persist_messages|extra\\\"):\\n        WorkflowRunRequest(**_bg_request(\\\"s\\\", persist_messages=False))\\n\\n\\ndef test_background_reparse_preserves_anonymous_no_persist():\\n    parsed = _parse_persisted_workflow_request(_bg_request(\\\"anon-1\\\", persist_messages=False))\\n    assert parsed.persist_messages is False\\n    assert parsed.session_id == \\\"anon-1\\\"\\n\\n\\ndef test_background_reparse_preserves_identified_merged_session():\\n    parsed = _parse_persisted_workflow_request(_bg_request(\\\"alice::chat-1\\\", persist_messages=True))\\n    assert parsed.session_id == \\\"alice::chat-1\\\"\\n    assert parsed.persist_messages is True\\n\\n\\ndef test_background_reparse_defaults_persist_true_for_legacy_rows():\\n    # A persisted request written before the field existed must default to persist.\\n    parsed = _parse_persisted_workflow_request(_bg_request(\\\"s\\\"))\\n    assert parsed.persist_messages is True\\n\\n\\ndef test_workflow_run_request_forbids_end_user_id_extra():\\n    # Guards why the pop is required: end_user_id is internal, not a wire field.\\n    with pytest.raises(Exception, match=r\\\"end_user_id|extra\\\"):\\n        WorkflowRunRequest(**_bg_request(\\\"s\\\", end_user_id=\\\"alice\\\"))\\n\\n\\ndef test_background_reparse_carries_end_user_id():\\n    # An identified background/resume run must keep its end user on the worker so\\n    # memory stamps the end user, not the SID.\\n    parsed = _parse_persisted_workflow_request(_bg_request(\\\"alice::chat-1\\\", end_user_id=\\\"alice\\\"))\\n    assert parsed.end_user_id == \\\"alice\\\"\\n    assert parsed.session_id == \\\"alice::chat-1\\\"\\n\\n\\ndef test_background_reparse_defaults_end_user_id_none_for_legacy_rows():\\n    # A persisted request written before the field existed must default to no end user.\\n    parsed = _parse_persisted_workflow_request(_bg_request(\\\"s\\\"))\\n    assert parsed.end_user_id is None\\n\\n\\nasync def test_identified_graph_run_persists_end_to_end(client):  # noqa: ARG001\\n    \\\"\\\"\\\"The same graph with the default (persist=True) does write memory.\\\"\\\"\\\"\\n    session_id = f\\\"ident-e2e-{uuid4()}\\\"\\n    chat_input = ChatInput(_id=\\\"chat_input\\\")\\n    chat_input.set(input_value=\\\"hi there\\\")\\n    chat_output = ChatOutput(_id=\\\"chat_output\\\")\\n    chat_output.set(input_value=chat_input.message_response)\\n\\n    graph = Graph(chat_input, chat_output, flow_id=str(uuid4()))\\n    graph.session_id = session_id\\n    # persist_messages defaults True\\n\\n    async for _ in graph.async_start():\\n        pass\\n\\n    assert len(await aget_messages(session_id=session_id)) >= 1\\n\\n\\nasync def test_identified_run_stamps_message_owner_with_end_user(client):  # noqa: ARG001\\n    \\\"\\\"\\\"On the serving plane the stored message.user_id is the END USER, not the SID.\\n\\n    Write and read both resolve through resolve_message_owner_id, so a run whose graph\\n    carries end_user_id stamps messages to the end user: querying by the end-user id\\n    returns them, and querying by the service-account id (SID) returns nothing.\\n    \\\"\\\"\\\"\\n    sid, uid = uuid4(), uuid4()\\n    session_id = f\\\"uid-stamp-{uuid4()}\\\"\\n    chat_input = ChatInput(_id=\\\"chat_input\\\")\\n    chat_input.set(input_value=\\\"hi there\\\")\\n    chat_output = ChatOutput(_id=\\\"chat_output\\\")\\n    chat_output.set(input_value=chat_input.message_response)\\n\\n    graph = Graph(chat_input, chat_output, flow_id=str(uuid4()), user_id=str(sid))\\n    graph.session_id = session_id\\n    graph.end_user_id = str(uid)  # serving-plane end user wins over the SID\\n\\n    async for _ in graph.async_start():\\n        pass\\n\\n    assert len(await aget_messages(session_id=session_id, user_id=uid)) >= 1\\n    assert await aget_messages(session_id=session_id, user_id=sid) == []\\n\\n\\nasync def test_non_uuid_end_user_stamps_derived_owner_end_to_end(client):  # noqa: ARG001\\n    \\\"\\\"\\\"A non-UUID end-user id maps to a stable derived UUID for message.user_id.\\n\\n    The UUID-typed column cannot hold \\\"alice\\\", so the write derives a stable uuid5;\\n    the read resolves the same derivation, so retrieval by the derived id returns the\\n    rows (per-user separation preserved) while the SID sees nothing.\\n    \\\"\\\"\\\"\\n    from lfx.memory.flow_context import derive_message_owner_uuid\\n\\n    sid = uuid4()\\n    session_id = f\\\"uid-derive-{uuid4()}\\\"\\n    chat_input = ChatInput(_id=\\\"chat_input\\\")\\n    chat_input.set(input_value=\\\"hi there\\\")\\n    chat_output = ChatOutput(_id=\\\"chat_output\\\")\\n    chat_output.set(input_value=chat_input.message_response)\\n\\n    graph = Graph(chat_input, chat_output, flow_id=str(uuid4()), user_id=str(sid))\\n    graph.session_id = session_id\\n    graph.end_user_id = \\\"alice\\\"  # opaque, non-UUID gateway id\\n\\n    async for _ in graph.async_start():\\n        pass\\n\\n    assert len(await aget_messages(session_id=session_id, user_id=derive_message_owner_uuid(\\\"alice\\\"))) >= 1\\n    assert await aget_messages(session_id=session_id, user_id=sid) == []\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_endpoints.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"160e24f83cca31064f8235dd760531ded8ad95837c93c68d38485fca8b5e18de\",\"content\":\"import asyncio\\nimport json\\nfrom uuid import UUID, uuid4\\n\\nimport orjson\\nimport pytest\\nfrom fastapi import status\\nfrom httpx import AsyncClient\\nfrom langflow.services.database.models.flow.model import FlowCreate\\nfrom langflow.services.deps import get_settings_service\\nfrom lfx.custom.directory_reader.directory_reader import DirectoryReader\\nfrom lfx.services.settings.base import BASE_COMPONENTS_PATH\\n\\n\\n@pytest.fixture(autouse=True)\\ndef allow_custom_components_by_default(monkeypatch):\\n    monkeypatch.setenv(\\\"LANGFLOW_ALLOW_CUSTOM_COMPONENTS\\\", \\\"true\\\")\\n\\n\\nasync def run_post(client, flow_id, headers, post_data):\\n    \\\"\\\"\\\"Sends a POST request to process a flow and returns the JSON response.\\n\\n    Args:\\n        client: The HTTP client to use for making requests.\\n        flow_id: The identifier of the flow to process.\\n        headers: The HTTP headers to include in the request.\\n        post_data: The JSON payload to send in the request.\\n\\n    Returns:\\n        The JSON response from the API if the request is successful.\\n\\n    Raises:\\n        AssertionError: If the response status code is not 200.\\n    \\\"\\\"\\\"\\n    response = await client.post(\\n        f\\\"api/v1/process/{flow_id}\\\",\\n        headers=headers,\\n        json=post_data,\\n    )\\n    assert response.status_code == 200, response.json()\\n    return response.json()\\n\\n\\n# Helper function to poll task status\\nasync def poll_task_status(client, headers, href, max_attempts=20, sleep_time=1):\\n    for _ in range(max_attempts):\\n        task_status_response = await client.get(\\n            href,\\n            headers=headers,\\n        )\\n        if task_status_response.status_code == 200 and task_status_response.json()[\\\"status\\\"] == \\\"SUCCESS\\\":\\n            return task_status_response.json()\\n        await asyncio.sleep(sleep_time)\\n    return None  # Return None if task did not complete in time\\n\\n\\nPROMPT_REQUEST = {\\n    \\\"name\\\": \\\"string\\\",\\n    \\\"template\\\": \\\"string\\\",\\n    \\\"frontend_node\\\": {\\n        \\\"template\\\": {},\\n        \\\"description\\\": \\\"string\\\",\\n        \\\"base_classes\\\": [\\\"string\\\"],\\n        \\\"name\\\": \\\"\\\",\\n        \\\"display_name\\\": \\\"\\\",\\n        \\\"documentation\\\": \\\"\\\",\\n        \\\"custom_fields\\\": {},\\n        \\\"output_types\\\": [],\\n        \\\"field_formatters\\\": {\\n            \\\"formatters\\\": {\\\"openai_api_key\\\": {}},\\n            \\\"base_formatters\\\": {\\n                \\\"kwargs\\\": {},\\n                \\\"optional\\\": {},\\n                \\\"list\\\": {},\\n                \\\"dict\\\": {},\\n                \\\"union\\\": {},\\n                \\\"multiline\\\": {},\\n                \\\"show\\\": {},\\n                \\\"password\\\": {},\\n                \\\"default\\\": {},\\n                \\\"headers\\\": {},\\n                \\\"dict_code_file\\\": {},\\n                \\\"model_fields\\\": {\\n                    \\\"MODEL_DICT\\\": {\\n                        \\\"OpenAI\\\": [\\n                            \\\"text-davinci-003\\\",\\n                            \\\"text-davinci-002\\\",\\n                            \\\"text-curie-001\\\",\\n                            \\\"text-babbage-001\\\",\\n                            \\\"text-ada-001\\\",\\n                        ],\\n                        \\\"ChatOpenAI\\\": [\\n                            \\\"gpt-4-turbo-preview\\\",\\n                            \\\"gpt-4-0125-preview\\\",\\n                            \\\"gpt-4-1106-preview\\\",\\n                            \\\"gpt-4-vision-preview\\\",\\n                            \\\"gpt-3.5-turbo-0125\\\",\\n                            \\\"gpt-3.5-turbo-1106\\\",\\n                        ],\\n                        \\\"Anthropic\\\": [\\n                            \\\"claude-v1\\\",\\n                            \\\"claude-v1-100k\\\",\\n                            \\\"claude-instant-v1\\\",\\n                            \\\"claude-instant-v1-100k\\\",\\n                            \\\"claude-v1.3\\\",\\n                            \\\"claude-v1.3-100k\\\",\\n                            \\\"claude-v1.2\\\",\\n                            \\\"claude-v1.0\\\",\\n                            \\\"claude-instant-v1.1\\\",\\n                            \\\"claude-instant-v1.1-100k\\\",\\n                            \\\"claude-instant-v1.0\\\",\\n                        ],\\n                        \\\"ChatAnthropic\\\": [\\n                            \\\"claude-v1\\\",\\n                            \\\"claude-v1-100k\\\",\\n                            \\\"claude-instant-v1\\\",\\n                            \\\"claude-instant-v1-100k\\\",\\n                            \\\"claude-v1.3\\\",\\n                            \\\"claude-v1.3-100k\\\",\\n                            \\\"claude-v1.2\\\",\\n                            \\\"claude-v1.0\\\",\\n                            \\\"claude-instant-v1.1\\\",\\n                            \\\"claude-instant-v1.1-100k\\\",\\n                            \\\"claude-instant-v1.0\\\",\\n                        ],\\n                    }\\n                },\\n            },\\n        },\\n    },\\n}\\n\\n\\n@pytest.mark.benchmark\\nasync def test_get_all(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Tests the retrieval of all available components from the API.\\n\\n    Sends a GET request to the `api/v1/all` endpoint and verifies that the returned component names\\n    correspond to files in the components directory. Also checks for the presence of specific components\\n    such as \\\"ChatInput\\\", \\\"Prompt\\\", and \\\"ChatOutput\\\" in the response.\\n    \\\"\\\"\\\"\\n    response = await client.get(\\\"api/v1/all\\\", headers=logged_in_headers)\\n    assert response.status_code == 200\\n    dir_reader = DirectoryReader(BASE_COMPONENTS_PATH)\\n    files = dir_reader.get_files()\\n    # json_response is a dict of dicts\\n    all_names = [\\n        component_name\\n        for key, components in response.json().items()\\n        if key != \\\"component_display_names\\\"\\n        for component_name in components\\n    ]\\n    json_response = response.json()\\n    # Bundle/extension components are namespaced \\\"ext:<bundle>:<Class>@<slot>\\\" and are served\\n    # from installed bundle packages (e.g. docling, ibm, arxiv), not from BASE_COMPONENTS_PATH,\\n    # so they are not backed by files in that directory. Exclude them before comparing against\\n    # the on-disk file count.\\n    base_component_names = [name for name in all_names if not name.startswith(\\\"ext:\\\")]\\n    # We need to test the custom nodes\\n    assert len(base_component_names) <= len(\\n        files\\n    )  # Less or equal because we might have some files that don't have the dependencies installed\\n    assert \\\"ChatInput\\\" in json_response[\\\"input_output\\\"]\\n    assert \\\"Prompt Template\\\" in json_response[\\\"models_and_agents\\\"]\\n    assert \\\"ChatOutput\\\" in json_response[\\\"input_output\\\"]\\n\\n\\nasync def test_component_palette_policy_filters_models_without_mutating_shared_cache(monkeypatch):\\n    from langflow.api.v1 import endpoints\\n    from lfx.services.model_provider_policy import (\\n        ModelProviderPolicyContext,\\n        ModelProviderPolicyPurpose,\\n        ModelProviderPolicySnapshot,\\n    )\\n\\n    cached = {\\n        \\\"mixed\\\": {\\n            \\\"AllowedModel\\\": {\\\"metadata\\\": {\\\"model_provider_id\\\": \\\"openai\\\"}},\\n            \\\"DeniedModel\\\": {\\\"metadata\\\": {\\\"model_provider_id\\\": \\\"anthropic\\\"}},\\n            \\\"Utility\\\": {\\\"metadata\\\": {}},\\n        }\\n    }\\n\\n    project_id = uuid4()\\n\\n    async def _openai_only(*, user_id, providers, purpose, attributes=None):\\n        assert purpose is ModelProviderPolicyPurpose.DISCOVER\\n        assert attributes == {\\\"project_id\\\": project_id}\\n        candidates = frozenset(providers)\\n        return ModelProviderPolicySnapshot(\\n            context=ModelProviderPolicyContext(user_id=user_id, attributes=attributes or {}),\\n            purpose=purpose,\\n            candidate_provider_ids=candidates,\\n            allowed_provider_ids=frozenset({\\\"openai\\\"}),\\n        )\\n\\n    def _sync_resolver_must_not_run(**_kwargs):\\n        msg = \\\"scoped palette discovery must refresh hierarchy asynchronously\\\"\\n        raise AssertionError(msg)\\n\\n    monkeypatch.setattr(endpoints, \\\"resolve_model_provider_policy\\\", _sync_resolver_must_not_run, raising=False)\\n    monkeypatch.setattr(endpoints, \\\"aresolve_model_provider_policy\\\", _openai_only, raising=False)\\n\\n    filtered = await endpoints._filter_component_palette_by_provider_policy(\\n        cached,\\n        user_id=\\\"user-1\\\",\\n        attributes={\\\"project_id\\\": project_id},\\n    )\\n\\n    assert set(filtered[\\\"mixed\\\"]) == {\\\"AllowedModel\\\", \\\"Utility\\\"}\\n    assert \\\"DeniedModel\\\" in cached[\\\"mixed\\\"]\\n    assert filtered is not cached\\n    assert filtered[\\\"mixed\\\"] is not cached[\\\"mixed\\\"]\\n\\n\\ndef test_catalog_policy_filter_is_case_sensitive_and_does_not_mutate_shared_cache():\\n    from langflow.api.v1 import endpoints\\n\\n    blocked_component = {\\\"display_name\\\": \\\"Blocked\\\", \\\"metadata\\\": {\\\"nested\\\": True}}\\n    allowed_component = {\\\"display_name\\\": \\\"Allowed\\\", \\\"metadata\\\": {\\\"nested\\\": True}}\\n    cached = {\\n        \\\"models\\\": {\\n            \\\"BlockedAgent\\\": blocked_component,\\n            \\\"blockedagent\\\": allowed_component,\\n        },\\n        \\\"empty\\\": {},\\n    }\\n\\n    filtered = endpoints._filter_component_palette_by_catalog_policy(\\n        cached,\\n        blocked_component_keys=frozenset({\\\"BlockedAgent\\\"}),\\n    )\\n\\n    assert list(filtered) == [\\\"models\\\", \\\"empty\\\"]\\n    assert list(filtered[\\\"models\\\"]) == [\\\"blockedagent\\\"]\\n    assert filtered[\\\"empty\\\"] == {}\\n    assert filtered is not cached\\n    assert filtered[\\\"models\\\"] is not cached[\\\"models\\\"]\\n    assert filtered[\\\"empty\\\"] is not cached[\\\"empty\\\"]\\n    assert filtered[\\\"models\\\"][\\\"blockedagent\\\"] is allowed_component\\n    assert list(cached[\\\"models\\\"]) == [\\\"BlockedAgent\\\", \\\"blockedagent\\\"]\\n    assert cached[\\\"models\\\"][\\\"BlockedAgent\\\"] is blocked_component\\n\\n\\ndef test_catalog_policy_filter_resolves_legacy_extension_alias_without_mutating_cache():\\n    from langflow.api.v1 import endpoints\\n\\n    canonical_key = \\\"ext:datastax:AstraDBVectorStoreComponent@official\\\"\\n    astra_component = {\\n        \\\"name\\\": \\\"AstraDB\\\",\\n        \\\"display_name\\\": \\\"Astra DB\\\",\\n        \\\"metadata\\\": {\\\"module\\\": \\\"lfx_datastax.components.datastax.astradb_vectorstore.AstraDBVectorStoreComponent\\\"},\\n        \\\"template\\\": {\\\"_type\\\": \\\"Component\\\"},\\n    }\\n    cached = {\\n        \\\"datastax\\\": {canonical_key: astra_component},\\n        \\\"input_output\\\": {\\\"ChatInput\\\": {\\\"display_name\\\": \\\"Chat Input\\\"}},\\n    }\\n\\n    filtered = endpoints._filter_component_palette_by_catalog_policy(\\n        cached,\\n        blocked_component_keys=frozenset({\\\"AstraDB\\\"}),\\n    )\\n\\n    assert filtered[\\\"datastax\\\"] == {}\\n    assert \\\"ChatInput\\\" in filtered[\\\"input_output\\\"]\\n    assert cached[\\\"datastax\\\"][canonical_key] is astra_component\\n    assert filtered is not cached\\n    assert filtered[\\\"datastax\\\"] is not cached[\\\"datastax\\\"]\\n\\n\\nasync def test_get_all_filters_catalog_policy_and_uses_current_snapshot(\\n    client: AsyncClient,\\n    logged_in_headers,\\n    monkeypatch,\\n):\\n    from langflow.api.v1 import endpoints\\n    from langflow.interface import components as components_module\\n    from lfx.services.catalog_policy import CatalogPolicySnapshot\\n\\n    cached = {\\n        \\\"models\\\": {\\n            \\\"AllowedAgent\\\": {\\n                \\\"display_name\\\": \\\"Allowed Agent\\\",\\n                \\\"description\\\": \\\"Visible\\\",\\n                \\\"template\\\": {},\\n                \\\"metadata\\\": {},\\n            },\\n            \\\"BlockedAgent\\\": {\\n                \\\"display_name\\\": \\\"Blocked Agent\\\",\\n                \\\"description\\\": \\\"Hidden\\\",\\n                \\\"template\\\": {},\\n                \\\"metadata\\\": {},\\n            },\\n        },\\n        \\\"empty\\\": {},\\n    }\\n\\n    class MutableCatalogPolicyService:\\n        def __init__(self):\\n            self.current_snapshot = CatalogPolicySnapshot(blocked_component_keys={\\\"BlockedAgent\\\"})\\n            self.snapshot_reads = 0\\n\\n        @property\\n        def snapshot(self):\\n            self.snapshot_reads += 1\\n            return self.current_snapshot\\n\\n    service = MutableCatalogPolicyService()\\n\\n    async def get_cached_types(*, settings_service):\\n        _ = settings_service\\n        return cached\\n\\n    monkeypatch.setattr(components_module, \\\"get_and_cache_all_types_dict\\\", get_cached_types)\\n    monkeypatch.setattr(endpoints, \\\"get_catalog_policy_service\\\", lambda: service)\\n\\n    async def allow_all_providers(all_types, **_kwargs):\\n        return {category: dict(components) for category, components in all_types.items()}\\n\\n    monkeypatch.setattr(\\n        endpoints,\\n        \\\"_filter_component_palette_by_provider_policy\\\",\\n        allow_all_providers,\\n    )\\n\\n    blocked_response = await client.get(\\\"api/v1/all\\\", headers=logged_in_headers)\\n\\n    assert blocked_response.status_code == status.HTTP_200_OK\\n    blocked_payload = blocked_response.json()\\n    assert list(blocked_payload[\\\"models\\\"]) == [\\\"AllowedAgent\\\"]\\n    assert \\\"blockedagent\\\" not in blocked_payload[\\\"component_display_names\\\"]\\n    assert blocked_payload[\\\"empty\\\"] == {}\\n    assert service.snapshot_reads == 1\\n    assert \\\"BlockedAgent\\\" in cached[\\\"models\\\"]\\n\\n    service.current_snapshot = CatalogPolicySnapshot()\\n    unblocked_response = await client.get(\\\"api/v1/all\\\", headers=logged_in_headers)\\n\\n    assert unblocked_response.status_code == status.HTTP_200_OK\\n    unblocked_payload = unblocked_response.json()\\n    assert list(unblocked_payload[\\\"models\\\"]) == [\\\"AllowedAgent\\\", \\\"BlockedAgent\\\"]\\n    assert \\\"blockedagent\\\" in unblocked_payload[\\\"component_display_names\\\"]\\n    assert service.snapshot_reads == 2\\n    assert list(cached[\\\"models\\\"]) == [\\\"AllowedAgent\\\", \\\"BlockedAgent\\\"]\\n\\n\\nasync def test_get_all_rejects_include_blocked_for_non_superuser_before_broad_exception_handler(\\n    client: AsyncClient,\\n    logged_in_headers,\\n    monkeypatch,\\n):\\n    from langflow.api.v1 import endpoints\\n\\n    def unexpected_catalog_service_lookup():\\n        msg = \\\"catalog policy must not be read for an unauthorized override\\\"\\n        raise AssertionError(msg)\\n\\n    monkeypatch.setattr(endpoints, \\\"get_catalog_policy_service\\\", unexpected_catalog_service_lookup)\\n\\n    response = await client.get(\\\"api/v1/all?include_blocked=true\\\", headers=logged_in_headers)\\n\\n    assert response.status_code == status.HTTP_403_FORBIDDEN\\n\\n\\nasync def test_get_all_superuser_override_skips_only_catalog_filter_without_cache_poisoning(\\n    client: AsyncClient,\\n    logged_in_headers_super_user,\\n    monkeypatch,\\n):\\n    from langflow.api.v1 import endpoints\\n    from langflow.interface import components as components_module\\n    from lfx.services.catalog_policy import CatalogPolicySnapshot\\n\\n    cached = {\\n        \\\"models\\\": {\\n            \\\"AllowedAgent\\\": {\\n                \\\"display_name\\\": \\\"Allowed Agent\\\",\\n                \\\"description\\\": \\\"Visible\\\",\\n                \\\"template\\\": {},\\n                \\\"metadata\\\": {},\\n            },\\n            \\\"BlockedAgent\\\": {\\n                \\\"display_name\\\": \\\"Blocked Agent\\\",\\n                \\\"description\\\": \\\"Catalog blocked\\\",\\n                \\\"template\\\": {},\\n                \\\"metadata\\\": {},\\n            },\\n            \\\"ProviderBlockedAgent\\\": {\\n                \\\"display_name\\\": \\\"Provider Blocked Agent\\\",\\n                \\\"description\\\": \\\"Provider blocked\\\",\\n                \\\"template\\\": {},\\n                \\\"metadata\\\": {\\\"model_provider_id\\\": \\\"denied-provider\\\"},\\n            },\\n        }\\n    }\\n\\n    class CountingCatalogPolicyService:\\n        def __init__(self):\\n            self.snapshot_reads = 0\\n\\n        @property\\n        def snapshot(self):\\n            self.snapshot_reads += 1\\n            return CatalogPolicySnapshot(blocked_component_keys={\\\"BlockedAgent\\\"})\\n\\n    service = CountingCatalogPolicyService()\\n    provider_filter_calls = 0\\n\\n    async def get_cached_types(*, settings_service):\\n        _ = settings_service\\n        return cached\\n\\n    async def filter_provider_policy(all_types, *, user_id, attributes=None):\\n        nonlocal provider_filter_calls\\n        _ = user_id\\n        provider_filter_calls += 1\\n        assert attributes == {\\\"is_superuser\\\": True}\\n        return {\\n            category: {\\n                key: component\\n                for key, component in components.items()\\n                if component.get(\\\"metadata\\\", {}).get(\\\"model_provider_id\\\") != \\\"denied-provider\\\"\\n            }\\n            for category, components in all_types.items()\\n        }\\n\\n    monkeypatch.setattr(components_module, \\\"get_and_cache_all_types_dict\\\", get_cached_types)\\n    monkeypatch.setattr(endpoints, \\\"get_catalog_policy_service\\\", lambda: service)\\n    monkeypatch.setattr(endpoints, \\\"_filter_component_palette_by_provider_policy\\\", filter_provider_policy)\\n\\n    override_response = await client.get(\\n        \\\"api/v1/all?include_blocked=true\\\",\\n        headers=logged_in_headers_super_user,\\n    )\\n\\n    assert override_response.status_code == status.HTTP_200_OK\\n    override_payload = override_response.json()\\n    assert list(override_payload[\\\"models\\\"]) == [\\\"AllowedAgent\\\", \\\"BlockedAgent\\\"]\\n    assert \\\"ProviderBlockedAgent\\\" not in override_payload[\\\"models\\\"]\\n    assert service.snapshot_reads == 1\\n    assert provider_filter_calls == 1\\n    assert list(cached[\\\"models\\\"]) == [\\\"AllowedAgent\\\", \\\"BlockedAgent\\\", \\\"ProviderBlockedAgent\\\"]\\n\\n    default_response = await client.get(\\\"api/v1/all\\\", headers=logged_in_headers_super_user)\\n\\n    assert default_response.status_code == status.HTTP_200_OK\\n    assert list(default_response.json()[\\\"models\\\"]) == [\\\"AllowedAgent\\\"]\\n    assert service.snapshot_reads == 2\\n    assert provider_filter_calls == 2\\n    assert list(cached[\\\"models\\\"]) == [\\\"AllowedAgent\\\", \\\"BlockedAgent\\\", \\\"ProviderBlockedAgent\\\"]\\n\\n\\n@pytest.mark.usefixtures(\\\"active_user\\\")\\nasync def test_post_validate_code(client: AsyncClient, logged_in_headers):\\n    # Test case with a valid import and function\\n    code1 = \\\"\\\"\\\"\\nimport math\\n\\ndef square(x):\\n    return x ** 2\\n\\\"\\\"\\\"\\n    response1 = await client.post(\\\"api/v1/validate/code\\\", json={\\\"code\\\": code1}, headers=logged_in_headers)\\n    assert response1.status_code == 200\\n    assert response1.json() == {\\\"imports\\\": {\\\"errors\\\": []}, \\\"function\\\": {\\\"errors\\\": []}}\\n\\n    # Test case with an invalid import and valid function\\n    code2 = \\\"\\\"\\\"\\nimport non_existent_module\\n\\ndef square(x):\\n    return x ** 2\\n\\\"\\\"\\\"\\n    response2 = await client.post(\\\"api/v1/validate/code\\\", json={\\\"code\\\": code2}, headers=logged_in_headers)\\n    assert response2.status_code == 200\\n    assert response2.json() == {\\n        \\\"imports\\\": {\\\"errors\\\": [\\\"No module named 'non_existent_module'\\\"]},\\n        \\\"function\\\": {\\\"errors\\\": []},\\n    }\\n\\n    # Test case with a valid import and invalid function syntax\\n    code3 = \\\"\\\"\\\"\\nimport math\\n\\ndef square(x)\\n    return x ** 2\\n\\\"\\\"\\\"\\n    response3 = await client.post(\\\"api/v1/validate/code\\\", json={\\\"code\\\": code3}, headers=logged_in_headers)\\n    assert response3.status_code == 200\\n    assert response3.json() == {\\n        \\\"imports\\\": {\\\"errors\\\": []},\\n        \\\"function\\\": {\\\"errors\\\": [\\\"expected ':' (<unknown>, line 4)\\\"]},\\n    }\\n\\n    # Test case with invalid JSON payload\\n    response4 = await client.post(\\\"api/v1/validate/code\\\", json={\\\"invalid_key\\\": code1}, headers=logged_in_headers)\\n    assert response4.status_code == 422\\n\\n    # Test case with an empty code string\\n    response5 = await client.post(\\\"api/v1/validate/code\\\", json={\\\"code\\\": \\\"\\\"}, headers=logged_in_headers)\\n    assert response5.status_code == 200\\n    assert response5.json() == {\\\"imports\\\": {\\\"errors\\\": []}, \\\"function\\\": {\\\"errors\\\": []}}\\n\\n    # Test case with a syntax error in the code\\n    code6 = \\\"\\\"\\\"\\nimport math\\n\\ndef square(x)\\n    return x ** 2\\n\\\"\\\"\\\"\\n    response6 = await client.post(\\\"api/v1/validate/code\\\", json={\\\"code\\\": code6}, headers=logged_in_headers)\\n    assert response6.status_code == 200\\n    assert response6.json() == {\\n        \\\"imports\\\": {\\\"errors\\\": []},\\n        \\\"function\\\": {\\\"errors\\\": [\\\"expected ':' (<unknown>, line 4)\\\"]},\\n    }\\n\\n\\nVALID_PROMPT = \\\"\\\"\\\"\\nI want you to act as a naming consultant for new companies.\\n\\nHere are some examples of good company names:\\n\\n- search engine, Google\\n- social media, Facebook\\n- video sharing, YouTube\\n\\nThe name should be short, catchy and easy to remember.\\n\\nWhat is a good name for a company that makes {product}?\\n\\\"\\\"\\\"\\n\\nINVALID_PROMPT = \\\"This is an invalid prompt without any input variable.\\\"\\n\\n\\nasync def test_valid_prompt(client: AsyncClient, logged_in_headers):\\n    PROMPT_REQUEST[\\\"template\\\"] = VALID_PROMPT\\n    response = await client.post(\\\"api/v1/validate/prompt\\\", json=PROMPT_REQUEST, headers=logged_in_headers)\\n    assert response.status_code == 200\\n    assert response.json()[\\\"input_variables\\\"] == [\\\"product\\\"]\\n\\n\\nasync def test_invalid_prompt(client: AsyncClient, logged_in_headers):\\n    PROMPT_REQUEST[\\\"template\\\"] = INVALID_PROMPT\\n    response = await client.post(\\n        \\\"api/v1/validate/prompt\\\",\\n        json=PROMPT_REQUEST,\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == 200\\n    assert response.json()[\\\"input_variables\\\"] == []\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"prompt\\\", \\\"expected_input_variables\\\"),\\n    [\\n        (\\\"{color} is my favorite color.\\\", [\\\"color\\\"]),\\n        (\\\"The weather is {weather} today.\\\", [\\\"weather\\\"]),\\n        (\\\"This prompt has no variables.\\\", []),\\n        (\\\"{a}, {b}, and {c} are variables.\\\", [\\\"a\\\", \\\"b\\\", \\\"c\\\"]),\\n    ],\\n)\\nasync def test_various_prompts(client, logged_in_headers, prompt, expected_input_variables):\\n    PROMPT_REQUEST[\\\"template\\\"] = prompt\\n    response = await client.post(\\\"api/v1/validate/prompt\\\", json=PROMPT_REQUEST, headers=logged_in_headers)\\n    assert response.status_code == 200\\n    assert response.json()[\\\"input_variables\\\"] == expected_input_variables\\n\\n\\nasync def test_get_vertices_flow_not_found(client, logged_in_headers):\\n    \\\"\\\"\\\"A nonexistent flow id on the deprecated /build/{flow_id}/vertices route returns 404.\\n\\n    The handler now does an owner-or-public ownership check before reaching\\n    ``build_graph_from_db`` (which previously raised ``ValueError(\\\"Invalid\\n    flow ID\\\")`` and surfaced as 500). Unknown flow ids \u2014 and other users'\\n    private flows \u2014 fail closed with 404, matching the supported\\n    /build/{flow_id}/flow contract and the rest of the API's UUID-privacy\\n    behavior.\\n    \\\"\\\"\\\"\\n    uuid = uuid4()\\n    response = await client.post(f\\\"/api/v1/build/{uuid}/vertices\\\", headers=logged_in_headers)\\n    assert response.status_code == 404\\n\\n\\nasync def test_get_vertices(client, added_flow_webhook_test, logged_in_headers):\\n    flow_id = added_flow_webhook_test[\\\"id\\\"]\\n    response = await client.post(f\\\"/api/v1/build/{flow_id}/vertices\\\", headers=logged_in_headers)\\n    assert response.status_code == 200\\n    assert \\\"ids\\\" in response.json()\\n    # The response should contain the list in this order\\n    # ['ConversationBufferMemory-Lu2Nb', 'PromptTemplate-5Q0W8', 'ChatOpenAI-vy7fV', 'LLMChain-UjBh1']\\n    # The important part is before the - (ConversationBufferMemory, PromptTemplate, ChatOpenAI, LLMChain)\\n    ids = [_id.split(\\\"-\\\")[0] for _id in response.json()[\\\"ids\\\"]]\\n\\n    assert set(ids) == {\\\"ChatInput\\\"}\\n\\n\\nasync def test_get_vertices_rebuilds_outdated_components_when_custom_components_disabled(\\n    client, added_flow_webhook_test, logged_in_headers, monkeypatch\\n):\\n    \\\"\\\"\\\"A saved flow whose built-in code drifted across versions still builds (issue #14455).\\n\\n    With allow_custom_components=False the code stored in the node is never what executes \u2014\\n    ``resolve_trusted_code_for_build`` substitutes this server's copy \u2014 so refusing the flow over\\n    a stale code hash only broke every saved flow on upgrade. This node's type is a known server\\n    component, so the build runs the server's copy of it instead of being refused.\\n\\n    The spy asserts the substitution actually fired against the real component registry, which is\\n    what keeps this test honest: were the fixture's stored code ever to catch up with the server's\\n    copy, the build would still return 200 without exercising the substitution at all.\\n    \\\"\\\"\\\"\\n    from lfx.utils import flow_validation\\n\\n    monkeypatch.setattr(get_settings_service().settings, \\\"allow_custom_components\\\", False)\\n\\n    # from_payload imports this by module attribute on every call, so the spy sees the real run.\\n    substitute = flow_validation.substitute_outdated_component_code_in_place\\n    swapped: list[str] = []\\n\\n    def _spy(payload, **kwargs):\\n        result = substitute(payload, **kwargs)\\n        swapped.extend(result)\\n        return result\\n\\n    monkeypatch.setattr(flow_validation, \\\"substitute_outdated_component_code_in_place\\\", _spy)\\n\\n    flow_id = added_flow_webhook_test[\\\"id\\\"]\\n    response = await client.post(f\\\"/api/v1/build/{flow_id}/vertices\\\", headers=logged_in_headers)\\n\\n    assert response.status_code == 200\\n    assert any(\\\"ChatInput\\\" in label for label in swapped), f\\\"expected a ChatInput swap, got {swapped}\\\"\\n\\n\\nasync def test_get_vertices_blocks_outdated_components_when_substitution_disabled(\\n    client, added_flow_webhook_test, logged_in_headers, monkeypatch\\n):\\n    \\\"\\\"\\\"LANGFLOW_SUBSTITUTE_OUTDATED_COMPONENT_CODE=false keeps the strict hash gate.\\\"\\\"\\\"\\n    settings = get_settings_service().settings\\n    monkeypatch.setattr(settings, \\\"allow_custom_components\\\", False)\\n    monkeypatch.setattr(settings, \\\"substitute_outdated_component_code\\\", False)\\n\\n    flow_id = added_flow_webhook_test[\\\"id\\\"]\\n    response = await client.post(f\\\"/api/v1/build/{flow_id}/vertices\\\", headers=logged_in_headers)\\n\\n    assert response.status_code == 400\\n    assert \\\"outdated components must be updated before running\\\" in response.json()[\\\"detail\\\"]\\n\\n\\nasync def test_build_vertex_invalid_flow_id(client, logged_in_headers):\\n    \\\"\\\"\\\"A nonexistent flow id on the deprecated /build/{flow_id}/vertices/{vertex_id} route returns 404.\\n\\n    Same contract as test_get_vertices_flow_not_found \u2014 the new ownership\\n    check raises 404 before the graph-cache lookup that previously produced\\n    a generic 500.\\n    \\\"\\\"\\\"\\n    uuid = uuid4()\\n    response = await client.post(f\\\"/api/v1/build/{uuid}/vertices/vertex_id\\\", headers=logged_in_headers)\\n    assert response.status_code == 404\\n\\n\\n@pytest.fixture\\nasync def second_user_headers(client):\\n    \\\"\\\"\\\"Log in as a second, distinct user.\\n\\n    The conftest's ``active_user`` / ``logged_in_headers`` fixtures hard-code\\n    a single ``activeuser`` account. Cross-user authorization tests need a\\n    second login token, which this fixture provides by registering and\\n    logging in as ``second_active_user`` for the lifetime of the test.\\n    \\\"\\\"\\\"\\n    from langflow.services.database.models.user.model import User, UserRead\\n    from langflow.services.deps import get_auth_service, session_scope\\n    from sqlmodel import select\\n\\n    username = \\\"second_active_user\\\"\\n    password = \\\"testpassword\\\"  # noqa: S105  # pragma: allowlist secret\\n\\n    async with session_scope() as session:\\n        user = User(\\n            username=username,\\n            password=get_auth_service().get_password_hash(password),\\n            is_active=True,\\n            is_superuser=False,\\n        )\\n        stmt = select(User).where(User.username == username)\\n        if existing := (await session.exec(stmt)).first():\\n            user = existing\\n        else:\\n            session.add(user)\\n            await session.flush()\\n            await session.refresh(user)\\n        user_id = UserRead.model_validate(user, from_attributes=True).id\\n\\n    login_response = await client.post(\\\"api/v1/login\\\", data={\\\"username\\\": username, \\\"password\\\": password})\\n    assert login_response.status_code == 200\\n    token = login_response.json()[\\\"access_token\\\"]\\n    yield {\\\"Authorization\\\": f\\\"Bearer {token}\\\"}\\n\\n    async with session_scope() as session:\\n        if existing := await session.get(User, user_id):\\n            await session.delete(existing)\\n\\n\\nasync def test_get_vertices_returns_404_for_other_users_private_flow(\\n    client, added_flow_webhook_test, second_user_headers\\n):\\n    \\\"\\\"\\\"A second user attempting to build vertices on someone else's private flow gets 404.\\n\\n    Behavioral regression for the deprecated /build/{flow_id}/vertices guard.\\n    The flow is created by ``active_user`` via ``added_flow_webhook_test``;\\n    ``second_user_headers`` is a different account, so the owner-or-public\\n    fetch returns None and the handler raises 404 (preserving UUID-privacy)\\n    before reaching the graph builder that previously had no owner filter.\\n    \\\"\\\"\\\"\\n    flow_id = added_flow_webhook_test[\\\"id\\\"]\\n    response = await client.post(f\\\"/api/v1/build/{flow_id}/vertices\\\", headers=second_user_headers)\\n    assert response.status_code == 404, response.text\\n\\n\\nasync def test_get_vertices_with_supplied_data_returns_404_for_other_users_private_flow(\\n    client, added_flow_webhook_test, second_user_headers\\n):\\n    \\\"\\\"\\\"A non-owner cannot pollute another user's graph cache via the deprecated supplied-data path.\\n\\n    Regression for the reported cache-pollution scenario: a second user POSTs\\n    attacker-controlled graph ``data`` for someone else's private flow UUID. The\\n    owner-or-public ownership guard runs *before* the build-and-cache branch\\n    (``build_and_cache_graph_from_data`` -> ``set_cache(str(flow_id), ...)``), so the\\n    request fails closed with 404 and no graph is cached under the victim flow id.\\n\\n    Complements ``test_get_vertices_returns_404_for_other_users_private_flow`` (which\\n    exercises the no-data branch) by covering the supplied-data branch specifically.\\n    The payload is a schema-valid ``FlowDataRequest`` so the request clears body\\n    validation and actually reaches the ownership guard.\\n    \\\"\\\"\\\"\\n    flow_id = added_flow_webhook_test[\\\"id\\\"]\\n    attacker_data = {\\n        \\\"nodes\\\": [{\\\"id\\\": \\\"attacker-node\\\", \\\"data\\\": {\\\"type\\\": \\\"AttackerControlled\\\"}}],\\n        \\\"edges\\\": [],\\n        \\\"viewport\\\": {\\\"x\\\": 1, \\\"y\\\": 2, \\\"zoom\\\": 0.75},\\n    }\\n    response = await client.post(f\\\"/api/v1/build/{flow_id}/vertices\\\", json=attacker_data, headers=second_user_headers)\\n    assert response.status_code == 404, response.text\\n\\n\\nasync def test_build_vertex_returns_404_for_other_users_private_flow(\\n    client, added_flow_webhook_test, second_user_headers\\n):\\n    \\\"\\\"\\\"Same cross-user 404 behavior on the per-vertex deprecated build route.\\\"\\\"\\\"\\n    flow_id = added_flow_webhook_test[\\\"id\\\"]\\n    response = await client.post(f\\\"/api/v1/build/{flow_id}/vertices/some-vertex-id\\\", headers=second_user_headers)\\n    assert response.status_code == 404, response.text\\n\\n\\nasync def test_build_vertex_stream_returns_404_for_other_users_private_flow(\\n    client, added_flow_webhook_test, second_user_headers\\n):\\n    \\\"\\\"\\\"The deprecated stream route must authorize before reading the shared graph cache.\\\"\\\"\\\"\\n    flow_id = added_flow_webhook_test[\\\"id\\\"]\\n    response = await client.get(\\n        f\\\"/api/v1/build/{flow_id}/ChatInput-some-id/stream\\\",\\n        headers=second_user_headers,\\n    )\\n    assert response.status_code == 404, response.text\\n\\n\\nasync def test_build_vertex_invalid_vertex_id(client, added_flow_webhook_test, logged_in_headers):\\n    flow_id = added_flow_webhook_test[\\\"id\\\"]\\n    response = await client.post(f\\\"/api/v1/build/{flow_id}/vertices/invalid_vertex_id\\\", headers=logged_in_headers)\\n    assert response.status_code == 500\\n\\n\\nasync def test_build_vertex_revalidates_cached_graph_after_catalog_policy_change(\\n    client,\\n    added_flow_webhook_test,\\n    logged_in_headers,\\n    monkeypatch,\\n):\\n    \\\"\\\"\\\"The deprecated per-vertex route must not execute a stale, newly blocked cached graph.\\\"\\\"\\\"\\n    from langflow.api.v1 import chat as chat_module\\n    from lfx.utils.flow_validation import CatalogPolicyValidationError\\n\\n    flow_id = added_flow_webhook_test[\\\"id\\\"]\\n    order_response = await client.post(f\\\"/api/v1/build/{flow_id}/vertices\\\", headers=logged_in_headers)\\n    assert order_response.status_code == 200\\n    vertex_id = order_response.json()[\\\"ids\\\"][0]\\n    blocked_message = \\\"Flow build blocked: catalog policy blocks components: ChatInput\\\"\\n\\n    def reject_cached_graph(_graph):\\n        raise CatalogPolicyValidationError(blocked_message)\\n\\n    monkeypatch.setattr(chat_module, \\\"validate_flow_for_current_settings\\\", reject_cached_graph)\\n\\n    response = await client.post(\\n        f\\\"/api/v1/build/{flow_id}/vertices/{vertex_id}\\\",\\n        headers=logged_in_headers,\\n    )\\n\\n    assert response.status_code == 400\\n    assert \\\"ChatInput\\\" in response.json()[\\\"detail\\\"]\\n\\n\\nasync def test_build_vertex_stream_revalidates_cached_graph_after_catalog_policy_change(\\n    client,\\n    added_flow_webhook_test,\\n    logged_in_headers,\\n    monkeypatch,\\n):\\n    \\\"\\\"\\\"The deprecated stream route rejects a stale graph before response streaming begins.\\\"\\\"\\\"\\n    from langflow.api.v1 import chat as chat_module\\n    from lfx.utils.flow_validation import CatalogPolicyValidationError\\n\\n    flow_id = added_flow_webhook_test[\\\"id\\\"]\\n    order_response = await client.post(f\\\"/api/v1/build/{flow_id}/vertices\\\", headers=logged_in_headers)\\n    assert order_response.status_code == 200\\n    vertex_id = order_response.json()[\\\"ids\\\"][0]\\n    blocked_message = \\\"Flow build blocked: catalog policy blocks components: ChatInput\\\"\\n\\n    def reject_cached_graph(_graph):\\n        raise CatalogPolicyValidationError(blocked_message)\\n\\n    monkeypatch.setattr(chat_module, \\\"validate_flow_for_current_settings\\\", reject_cached_graph)\\n\\n    response = await client.get(\\n        f\\\"/api/v1/build/{flow_id}/{vertex_id}/stream\\\",\\n        headers=logged_in_headers,\\n    )\\n\\n    assert response.status_code == 400\\n    assert \\\"ChatInput\\\" in response.json()[\\\"detail\\\"]\\n\\n\\nasync def test_successful_run_no_payload(client, simple_api_test, created_api_key):\\n    headers = {\\\"x-api-key\\\": created_api_key.api_key}\\n    flow_id = simple_api_test[\\\"id\\\"]\\n    response = await client.post(f\\\"/api/v1/run/{flow_id}\\\", headers=headers)\\n    assert response.status_code == status.HTTP_200_OK, response.text\\n    # Add more assertions here to validate the response content\\n    json_response = response.json()\\n    assert \\\"session_id\\\" in json_response\\n    assert \\\"outputs\\\" in json_response\\n    outer_outputs = json_response[\\\"outputs\\\"]\\n    assert len(outer_outputs) == 1\\n    outputs_dict = outer_outputs[0]\\n    assert len(outputs_dict) == 2\\n    assert \\\"inputs\\\" in outputs_dict\\n    assert \\\"outputs\\\" in outputs_dict\\n    assert isinstance(outputs_dict.get(\\\"outputs\\\"), list)\\n    assert len(outputs_dict.get(\\\"outputs\\\")) == 1\\n    ids = [output.get(\\\"component_id\\\") for output in outputs_dict.get(\\\"outputs\\\")]\\n    assert all(\\\"ChatOutput\\\" in _id for _id in ids)\\n    display_names = [output.get(\\\"component_display_name\\\") for output in outputs_dict.get(\\\"outputs\\\")]\\n    assert all(name in display_names for name in [\\\"Chat Output\\\"])\\n    output_results_has_results = all(\\\"results\\\" in output.get(\\\"results\\\") for output in outputs_dict.get(\\\"outputs\\\"))\\n    inner_results = [output.get(\\\"results\\\") for output in outputs_dict.get(\\\"outputs\\\")]\\n\\n    assert all(result is not None for result in inner_results), (outputs_dict, output_results_has_results)\\n\\n\\nasync def test_run_by_id_enforces_current_catalog_policy_and_recovers_when_cleared(\\n    client, json_simple_api_test, logged_in_headers, created_api_key\\n):\\n    from lfx.services.deps import get_catalog_policy_service\\n\\n    catalog_policy_service = get_catalog_policy_service()\\n    await catalog_policy_service.replace_blocked_component_keys([], actor_user_id=None)\\n    flow_payload = orjson.loads(json_simple_api_test)\\n    flow = FlowCreate(\\n        name=\\\"Catalog Policy Run Test\\\",\\n        data=flow_payload[\\\"data\\\"],\\n        description=\\\"Catalog policy route test\\\",\\n    )\\n    create_response = await client.post(\\\"api/v1/flows/\\\", json=flow.model_dump(), headers=logged_in_headers)\\n    assert create_response.status_code == status.HTTP_201_CREATED\\n    flow_id = create_response.json()[\\\"id\\\"]\\n    await catalog_policy_service.replace_blocked_component_keys([\\\"ChatInput\\\"], actor_user_id=None)\\n\\n    blocked_response = await client.post(\\n        f\\\"/api/v1/run/{flow_id}\\\",\\n        headers={\\\"x-api-key\\\": created_api_key.api_key},\\n    )\\n    await catalog_policy_service.replace_blocked_component_keys([], actor_user_id=None)\\n    allowed_response = await client.post(\\n        f\\\"/api/v1/run/{flow_id}\\\",\\n        headers={\\\"x-api-key\\\": created_api_key.api_key},\\n    )\\n\\n    assert blocked_response.status_code == status.HTTP_400_BAD_REQUEST\\n    assert blocked_response.json()[\\\"detail\\\"].endswith(\\\"ChatInput\\\")\\n    assert allowed_response.status_code == status.HTTP_200_OK, allowed_response.text\\n\\n\\nasync def test_successful_run_with_output_type_text(client, simple_api_test, created_api_key):\\n    headers = {\\\"x-api-key\\\": created_api_key.api_key}\\n    flow_id = simple_api_test[\\\"id\\\"]\\n    payload = {\\n        \\\"output_type\\\": \\\"text\\\",\\n    }\\n    response = await client.post(f\\\"/api/v1/run/{flow_id}\\\", headers=headers, json=payload)\\n    assert response.status_code == status.HTTP_200_OK, response.text\\n    # Add more assertions here to validate the response content\\n    json_response = response.json()\\n    assert \\\"session_id\\\" in json_response\\n    assert \\\"outputs\\\" in json_response\\n    outer_outputs = json_response[\\\"outputs\\\"]\\n    assert len(outer_outputs) == 1\\n    outputs_dict = outer_outputs[0]\\n    assert len(outputs_dict) == 2\\n    assert \\\"inputs\\\" in outputs_dict\\n    assert \\\"outputs\\\" in outputs_dict\\n    assert isinstance(outputs_dict.get(\\\"outputs\\\"), list)\\n    assert len(outputs_dict.get(\\\"outputs\\\")) == 1\\n    ids = [output.get(\\\"component_id\\\") for output in outputs_dict.get(\\\"outputs\\\")]\\n    assert all(\\\"ChatOutput\\\" in _id for _id in ids), ids\\n    display_names = [output.get(\\\"component_display_name\\\") for output in outputs_dict.get(\\\"outputs\\\")]\\n    assert all(name in display_names for name in [\\\"Chat Output\\\"]), display_names\\n    inner_results = [output.get(\\\"results\\\") for output in outputs_dict.get(\\\"outputs\\\")]\\n    expected_keys = [\\\"message\\\"]\\n    assert all(key in result for result in inner_results for key in expected_keys), outputs_dict\\n\\n\\n@pytest.mark.benchmark\\nasync def test_successful_run_with_output_type_any(client, simple_api_test, created_api_key):\\n    # This one should have both the ChatOutput and TextOutput components\\n    headers = {\\\"x-api-key\\\": created_api_key.api_key}\\n    flow_id = simple_api_test[\\\"id\\\"]\\n    payload = {\\n        \\\"output_type\\\": \\\"any\\\",\\n    }\\n    response = await client.post(f\\\"/api/v1/run/{flow_id}\\\", headers=headers, json=payload)\\n    assert response.status_code == status.HTTP_200_OK, response.text\\n    # Add more assertions here to validate the response content\\n    json_response = response.json()\\n    assert \\\"session_id\\\" in json_response\\n    assert \\\"outputs\\\" in json_response\\n    outer_outputs = json_response[\\\"outputs\\\"]\\n    assert len(outer_outputs) == 1\\n    outputs_dict = outer_outputs[0]\\n    assert len(outputs_dict) == 2\\n    assert \\\"inputs\\\" in outputs_dict\\n    assert \\\"outputs\\\" in outputs_dict\\n    assert isinstance(outputs_dict.get(\\\"outputs\\\"), list)\\n    assert len(outputs_dict.get(\\\"outputs\\\")) == 1\\n    ids = [output.get(\\\"component_id\\\") for output in outputs_dict.get(\\\"outputs\\\")]\\n    assert all(\\\"ChatOutput\\\" in _id or \\\"TextOutput\\\" in _id for _id in ids), ids\\n    display_names = [output.get(\\\"component_display_name\\\") for output in outputs_dict.get(\\\"outputs\\\")]\\n    assert all(name in display_names for name in [\\\"Chat Output\\\"]), display_names\\n    inner_results = [output.get(\\\"results\\\") for output in outputs_dict.get(\\\"outputs\\\")]\\n    expected_keys = [\\\"message\\\"]\\n    assert all(key in result for result in inner_results for key in expected_keys), outputs_dict\\n\\n\\n@pytest.mark.benchmark\\nasync def test_successful_run_with_output_type_debug(client, simple_api_test, created_api_key):\\n    # This one should return outputs for all components\\n    # Let's just check the amount of outputs(there should be 7)\\n    headers = {\\\"x-api-key\\\": created_api_key.api_key}\\n    flow_id = simple_api_test[\\\"id\\\"]\\n    payload = {\\n        \\\"output_type\\\": \\\"debug\\\",\\n    }\\n    response = await client.post(f\\\"/api/v1/run/{flow_id}\\\", headers=headers, json=payload)\\n    assert response.status_code == status.HTTP_200_OK, response.text\\n    # Add more assertions here to validate the response content\\n    json_response = response.json()\\n    assert \\\"session_id\\\" in json_response\\n    assert \\\"outputs\\\" in json_response\\n    outer_outputs = json_response[\\\"outputs\\\"]\\n    assert len(outer_outputs) == 1\\n    outputs_dict = outer_outputs[0]\\n    assert len(outputs_dict) == 2\\n    assert \\\"inputs\\\" in outputs_dict\\n    assert \\\"outputs\\\" in outputs_dict\\n    assert isinstance(outputs_dict.get(\\\"outputs\\\"), list)\\n    assert len(outputs_dict.get(\\\"outputs\\\")) == 3\\n\\n\\n@pytest.mark.benchmark\\nasync def test_successful_run_with_input_type_text(client, simple_api_test, created_api_key):\\n    headers = {\\\"x-api-key\\\": created_api_key.api_key}\\n    flow_id = simple_api_test[\\\"id\\\"]\\n    payload = {\\n        \\\"input_type\\\": \\\"text\\\",\\n        \\\"output_type\\\": \\\"debug\\\",\\n        \\\"input_value\\\": \\\"value1\\\",\\n    }\\n    response = await client.post(f\\\"/api/v1/run/{flow_id}\\\", headers=headers, json=payload)\\n    assert response.status_code == status.HTTP_200_OK, response.text\\n    # Add more assertions here to validate the response content\\n    json_response = response.json()\\n    assert \\\"session_id\\\" in json_response\\n    assert \\\"outputs\\\" in json_response\\n    outer_outputs = json_response[\\\"outputs\\\"]\\n    assert len(outer_outputs) == 1\\n    outputs_dict = outer_outputs[0]\\n    assert len(outputs_dict) == 2\\n    assert \\\"inputs\\\" in outputs_dict\\n    assert \\\"outputs\\\" in outputs_dict\\n    actual_inputs = outputs_dict.get(\\\"inputs\\\")\\n    expected_inputs = {\\\"input_value\\\": \\\"value1\\\"}\\n    assert actual_inputs == expected_inputs, (\\n        f\\\"Expected inputs to be {expected_inputs}, but got {actual_inputs}. \\\"\\n        f\\\"Full outputs_dict keys: {list(outputs_dict.keys())}, \\\"\\n        f\\\"Full response: {json_response}\\\"\\n    )\\n    assert isinstance(outputs_dict.get(\\\"outputs\\\"), list)\\n    assert len(outputs_dict.get(\\\"outputs\\\")) == 3\\n    # Now we get all components that contain TextInput in the component_id\\n    text_input_outputs = [output for output in outputs_dict.get(\\\"outputs\\\") if \\\"TextInput\\\" in output.get(\\\"component_id\\\")]\\n    assert len(text_input_outputs) == 1\\n    # Now we check if the input_value is correct\\n    # We get text key twice because the output is now a Message\\n    assert all(output.get(\\\"results\\\").get(\\\"text\\\").get(\\\"text\\\") == \\\"value1\\\" for output in text_input_outputs), (\\n        text_input_outputs\\n    )\\n\\n\\n@pytest.mark.api_key_required\\n@pytest.mark.benchmark\\nasync def test_successful_run_with_input_type_chat(client: AsyncClient, simple_api_test, created_api_key):\\n    headers = {\\\"x-api-key\\\": created_api_key.api_key}\\n    flow_id = simple_api_test[\\\"id\\\"]\\n    payload = {\\n        \\\"input_type\\\": \\\"chat\\\",\\n        \\\"output_type\\\": \\\"debug\\\",\\n        \\\"input_value\\\": \\\"value1\\\",\\n    }\\n    response = await client.post(f\\\"/api/v1/run/{flow_id}\\\", headers=headers, json=payload)\\n    assert response.status_code == status.HTTP_200_OK, response.text\\n    # Add more assertions here to validate the response content\\n    json_response = response.json()\\n    assert \\\"session_id\\\" in json_response\\n    assert \\\"outputs\\\" in json_response\\n    outer_outputs = json_response[\\\"outputs\\\"]\\n    assert len(outer_outputs) == 1\\n    outputs_dict = outer_outputs[0]\\n    assert len(outputs_dict) == 2\\n    assert \\\"inputs\\\" in outputs_dict\\n    assert \\\"outputs\\\" in outputs_dict\\n    actual_inputs = outputs_dict.get(\\\"inputs\\\")\\n    expected_inputs = {\\\"input_value\\\": \\\"value1\\\"}\\n    assert actual_inputs == expected_inputs, (\\n        f\\\"Expected inputs to be {expected_inputs}, but got {actual_inputs}. \\\"\\n        f\\\"Full outputs_dict keys: {list(outputs_dict.keys())}, \\\"\\n        f\\\"Full response: {json_response}\\\"\\n    )\\n    assert isinstance(outputs_dict.get(\\\"outputs\\\"), list)\\n    assert len(outputs_dict.get(\\\"outputs\\\")) == 3\\n    # Now we get all components that contain TextInput in the component_id\\n    chat_input_outputs = [output for output in outputs_dict.get(\\\"outputs\\\") if \\\"ChatInput\\\" in output.get(\\\"component_id\\\")]\\n    assert len(chat_input_outputs) == 1\\n    # Now we check if the input_value is correct\\n    assert all(output.get(\\\"results\\\").get(\\\"message\\\").get(\\\"text\\\") == \\\"value1\\\" for output in chat_input_outputs), (\\n        chat_input_outputs\\n    )\\n\\n\\n@pytest.mark.benchmark\\nasync def test_invalid_run_with_input_type_chat(client, simple_api_test, created_api_key):\\n    headers = {\\\"x-api-key\\\": created_api_key.api_key}\\n    flow_id = simple_api_test[\\\"id\\\"]\\n    payload = {\\n        \\\"input_type\\\": \\\"chat\\\",\\n        \\\"output_type\\\": \\\"debug\\\",\\n        \\\"input_value\\\": \\\"value1\\\",\\n        \\\"tweaks\\\": {\\\"Chat Input\\\": {\\\"input_value\\\": \\\"value2\\\"}},\\n    }\\n    response = await client.post(f\\\"/api/v1/run/{flow_id}\\\", headers=headers, json=payload)\\n    assert response.status_code == status.HTTP_400_BAD_REQUEST, response.text\\n    assert \\\"If you pass an input_value to the chat input, you cannot pass a tweak with the same name.\\\" in response.text\\n\\n\\n@pytest.mark.benchmark\\nasync def test_successful_run_with_input_type_any(client, simple_api_test, created_api_key):\\n    headers = {\\\"x-api-key\\\": created_api_key.api_key}\\n    flow_id = simple_api_test[\\\"id\\\"]\\n    payload = {\\n        \\\"input_type\\\": \\\"any\\\",\\n        \\\"output_type\\\": \\\"debug\\\",\\n        \\\"input_value\\\": \\\"value1\\\",\\n    }\\n    response = await client.post(f\\\"/api/v1/run/{flow_id}\\\", headers=headers, json=payload)\\n    assert response.status_code == status.HTTP_200_OK, response.text\\n    # Add more assertions here to validate the response content\\n    json_response = response.json()\\n    assert \\\"session_id\\\" in json_response\\n    assert \\\"outputs\\\" in json_response\\n    outer_outputs = json_response[\\\"outputs\\\"]\\n    assert len(outer_outputs) == 1\\n    outputs_dict = outer_outputs[0]\\n    assert len(outputs_dict) == 2\\n    assert \\\"inputs\\\" in outputs_dict\\n    assert \\\"outputs\\\" in outputs_dict\\n    actual_inputs = outputs_dict.get(\\\"inputs\\\")\\n    expected_inputs = {\\\"input_value\\\": \\\"value1\\\"}\\n    assert actual_inputs == expected_inputs, (\\n        f\\\"Expected inputs to be {expected_inputs}, but got {actual_inputs}. \\\"\\n        f\\\"Full outputs_dict keys: {list(outputs_dict.keys())}, \\\"\\n        f\\\"Full response: {json_response}\\\"\\n    )\\n    assert isinstance(outputs_dict.get(\\\"outputs\\\"), list)\\n    assert len(outputs_dict.get(\\\"outputs\\\")) == 3\\n    # Now we get all components that contain TextInput or ChatInput in the component_id\\n    any_input_outputs = [\\n        output\\n        for output in outputs_dict.get(\\\"outputs\\\")\\n        if \\\"TextInput\\\" in output.get(\\\"component_id\\\") or \\\"ChatInput\\\" in output.get(\\\"component_id\\\")\\n    ]\\n    assert len(any_input_outputs) == 2\\n    # Now we check if the input_value is correct\\n    all_result_dicts = [output.get(\\\"results\\\") for output in any_input_outputs]\\n    all_message_or_text_dicts = [\\n        result_dict.get(\\\"message\\\", result_dict.get(\\\"text\\\")) for result_dict in all_result_dicts\\n    ]\\n    assert all(message_or_text_dict.get(\\\"text\\\") == \\\"value1\\\" for message_or_text_dict in all_message_or_text_dicts), (\\n        any_input_outputs\\n    )\\n\\n\\nasync def test_invalid_flow_id(client, created_api_key):\\n    headers = {\\\"x-api-key\\\": created_api_key.api_key}\\n    flow_id = \\\"invalid-flow-id\\\"\\n    response = await client.post(f\\\"/api/v1/run/{flow_id}\\\", headers=headers)\\n    assert response.status_code == status.HTTP_404_NOT_FOUND, response.text\\n    headers = {\\\"x-api-key\\\": created_api_key.api_key}\\n    flow_id = UUID(int=0)\\n    response = await client.post(f\\\"/api/v1/run/{flow_id}\\\", headers=headers)\\n    assert response.status_code == status.HTTP_404_NOT_FOUND, response.text\\n    # Check if the error detail is as expected\\n\\n\\n@pytest.mark.benchmark\\nasync def test_starter_projects(client, created_api_key):\\n    headers = {\\\"x-api-key\\\": created_api_key.api_key}\\n    response = await client.get(\\\"api/v1/starter-projects/\\\", headers=headers)\\n    assert response.status_code == status.HTTP_200_OK, response.text\\n\\n\\nasync def _run_single_stream_test(client: AsyncClient, flow_id: str, headers: dict, payload: dict):\\n    \\\"\\\"\\\"Helper coroutine to run and validate a single streaming request.\\\"\\\"\\\"\\n    received_events = []  # Track all event types in sequence\\n    got_end_event = False\\n    final_result = None\\n\\n    async with client.stream(\\\"POST\\\", f\\\"/api/v1/run/{flow_id}?stream=true\\\", headers=headers, json=payload) as response:\\n        assert response.status_code == status.HTTP_200_OK, (\\n            f\\\"Request failed with status {response.status_code}: {response.text}\\\"\\n        )\\n        assert response.headers[\\\"content-type\\\"].startswith(\\\"text/event-stream\\\"), (\\n            f\\\"Expected event stream content type, got: {response.headers['content-type']}\\\"\\n        )\\n\\n        async for line in response.aiter_lines():\\n            if not line or line.strip() == \\\"\\\":\\n                continue\\n\\n            try:\\n                event_data = json.loads(line)\\n            except json.JSONDecodeError:\\n                pytest.fail(f\\\"Failed to parse JSON from stream line: {line}\\\")\\n\\n            assert \\\"event\\\" in event_data, f\\\"Event type missing in response line: {line}\\\"\\n            event_type = event_data[\\\"event\\\"]\\n            received_events.append(event_type)\\n\\n            if event_type == \\\"add_message\\\":\\n                message_data = event_data[\\\"data\\\"]\\n                assert \\\"sender_name\\\" in message_data, f\\\"Missing 'sender_name' in add_message event: {message_data}\\\"\\n                assert \\\"sender\\\" in message_data, f\\\"Missing 'sender' in add_message event: {message_data}\\\"\\n                assert \\\"session_id\\\" in message_data, f\\\"Missing 'session_id' in add_message event: {message_data}\\\"\\n                assert \\\"text\\\" in message_data, f\\\"Missing 'text' in add_message event: {message_data}\\\"\\n\\n            elif event_type == \\\"token\\\":\\n                token_data = event_data[\\\"data\\\"]\\n                assert \\\"chunk\\\" in token_data, f\\\"Missing 'chunk' in token event: {token_data}\\\"\\n\\n            elif event_type == \\\"end\\\":\\n                got_end_event = True\\n                final_result = event_data[\\\"data\\\"].get(\\\"result\\\")\\n                assert final_result is not None, \\\"End event should contain result data but was None\\\"\\n                break  # Exit loop after end event\\n\\n            elif event_type == \\\"error\\\":\\n                pytest.fail(f\\\"Received error event in stream: {event_data['data']}\\\")\\n\\n    # Assert we got the end event\\n    assert got_end_event, f\\\"Stream did not receive an end event. Received events: {received_events}\\\"\\n\\n    # Verify event sequence\\n    assert \\\"end\\\" in received_events, f\\\"End event missing from event sequence. Received: {received_events}\\\"\\n    assert received_events[-1] == \\\"end\\\", f\\\"Last event should be 'end', but was '{received_events[-1]}'\\\"\\n\\n    # Verify we got at least one message or token event before end\\n    assert len(received_events) > 2, f\\\"Should receive multiple events before the end event. Got: {received_events}\\\"\\n    assert any(event == \\\"add_message\\\" for event in received_events), (\\n        f\\\"Should receive at least one add_message event. Received events: {received_events}\\\"\\n    )\\n    assert any(event == \\\"token\\\" for event in received_events), (\\n        f\\\"Should receive at least one token event. Received events: {received_events}\\\"\\n    )\\n\\n    # Verify the final result structure in the end event\\n    assert final_result is not None, \\\"Final result should not be None\\\"\\n    assert \\\"outputs\\\" in final_result, f\\\"Missing 'outputs' in final result: {final_result}\\\"\\n    assert \\\"session_id\\\" in final_result, f\\\"Missing 'session_id' in final result: {final_result}\\\"\\n    outputs = final_result[\\\"outputs\\\"]\\n    assert len(outputs) == 1, f\\\"Expected 1 output, got {len(outputs)}: {outputs}\\\"\\n    outputs_dict = outputs[0]\\n\\n    # Verify the debug outputs in final result\\n    assert \\\"inputs\\\" in outputs_dict, f\\\"Missing 'inputs' in outputs_dict: {outputs_dict}\\\"\\n    assert \\\"outputs\\\" in outputs_dict, f\\\"Missing 'outputs' in outputs_dict: {outputs_dict}\\\"\\n    assert outputs_dict[\\\"inputs\\\"] == {\\\"input_value\\\": payload[\\\"input_value\\\"]}, (\\n        f\\\"Input value mismatch. Expected: {{'input_value': {payload['input_value']}}}, Got: {outputs_dict['inputs']}\\\"\\n    )\\n    assert isinstance(outputs_dict.get(\\\"outputs\\\"), list), (\\n        f\\\"Expected outputs to be a list, got: {type(outputs_dict.get('outputs'))}\\\"\\n    )\\n\\n    chat_input_outputs = [output for output in outputs_dict.get(\\\"outputs\\\") if \\\"ChatInput\\\" in output.get(\\\"component_id\\\")]\\n    assert len(chat_input_outputs) == 1, (\\n        f\\\"Expected 1 ChatInput output, got {len(chat_input_outputs)}: {chat_input_outputs}\\\"\\n    )\\n    assert all(\\n        output.get(\\\"results\\\").get(\\\"message\\\").get(\\\"text\\\") == payload[\\\"input_value\\\"] for output in chat_input_outputs\\n    ), f\\\"Message text mismatch. Expected: {payload['input_value']}, Got: {chat_input_outputs}\\\"\\n\\n\\n@pytest.mark.api_key_required\\n@pytest.mark.benchmark\\nasync def test_concurrent_stream_run_with_input_type_chat(client: AsyncClient, starter_project, created_api_key):\\n    \\\"\\\"\\\"Test concurrent streaming requests to the run endpoint with chat input type.\\\"\\\"\\\"\\n    headers = {\\\"x-api-key\\\": created_api_key.api_key, \\\"Accept\\\": \\\"text/event-stream\\\", \\\"Content-Type\\\": \\\"application/json\\\"}\\n    flow_id = starter_project[\\\"id\\\"]\\n    payload = {\\n        \\\"input_type\\\": \\\"chat\\\",\\n        \\\"output_type\\\": \\\"debug\\\",\\n        \\\"input_value\\\": \\\"How are you?\\\",\\n    }\\n    num_concurrent_requests = 5  # Number of concurrent requests to test\\n\\n    tasks = [_run_single_stream_test(client, flow_id, headers, payload) for _ in range(num_concurrent_requests)]\\n\\n    # Run all streaming tests concurrently\\n    await asyncio.gather(*tasks)\\n\\n\\n# ============================================================================\\n# Security Tests: User Permission Checks for Flow Access\\n# ============================================================================\\n\\n\\n@pytest.mark.benchmark\\nasync def test_user_can_run_own_flow(client: AsyncClient, simple_api_test, created_api_key):\\n    \\\"\\\"\\\"Test that a user can successfully run their own flow using their API key.\\\"\\\"\\\"\\n    headers = {\\\"x-api-key\\\": created_api_key.api_key}\\n    flow_id = simple_api_test[\\\"id\\\"]\\n\\n    response = await client.post(f\\\"/api/v1/run/{flow_id}\\\", headers=headers)\\n\\n    assert response.status_code == status.HTTP_200_OK, response.text\\n    json_response = response.json()\\n    assert \\\"session_id\\\" in json_response\\n    assert \\\"outputs\\\" in json_response\\n\\n\\n@pytest.mark.benchmark\\nasync def test_user_cannot_run_other_users_flow(client: AsyncClient, simple_api_test, user_two_api_key):\\n    \\\"\\\"\\\"Test that a user cannot run another user's flow.\\n\\n    Post-fix behavior is 404 (not 403) so we don't leak flow existence\\n    via a 403-vs-404 oracle.  See ``get_flow_for_api_key_user`` in\\n    ``api/v1/endpoints.py``.\\n    \\\"\\\"\\\"\\n    # simple_api_test belongs to active_user, but we're using user_two's API key\\n    headers = {\\\"x-api-key\\\": user_two_api_key}\\n    flow_id = simple_api_test[\\\"id\\\"]\\n\\n    response = await client.post(f\\\"/api/v1/run/{flow_id}\\\", headers=headers)\\n\\n    assert response.status_code == status.HTTP_404_NOT_FOUND, response.text\\n    # Must not leak that the flow exists under another user's account.\\n    assert \\\"permission\\\" not in response.text.lower()\\n\\n\\n@pytest.mark.benchmark\\nasync def test_user_cannot_run_other_users_flow_with_payload(client: AsyncClient, simple_api_test, user_two_api_key):\\n    \\\"\\\"\\\"Test that a user cannot run another user's flow even with valid payload.\\\"\\\"\\\"\\n    headers = {\\\"x-api-key\\\": user_two_api_key}\\n    flow_id = simple_api_test[\\\"id\\\"]\\n    payload = {\\n        \\\"input_type\\\": \\\"chat\\\",\\n        \\\"output_type\\\": \\\"debug\\\",\\n        \\\"input_value\\\": \\\"test message\\\",\\n    }\\n\\n    response = await client.post(f\\\"/api/v1/run/{flow_id}\\\", headers=headers, json=payload)\\n\\n    assert response.status_code == status.HTTP_404_NOT_FOUND, response.text\\n    assert \\\"permission\\\" not in response.text.lower()\\n\\n\\n@pytest.mark.benchmark\\nasync def test_user_can_run_own_flow_with_streaming(client: AsyncClient, simple_api_test, created_api_key):\\n    \\\"\\\"\\\"Test that a user can run their own flow with streaming enabled.\\\"\\\"\\\"\\n    headers = {\\\"x-api-key\\\": created_api_key.api_key}\\n    flow_id = simple_api_test[\\\"id\\\"]\\n    payload = {\\n        \\\"input_type\\\": \\\"chat\\\",\\n        \\\"output_type\\\": \\\"debug\\\",\\n        \\\"input_value\\\": \\\"test\\\",\\n    }\\n\\n    async with client.stream(\\\"POST\\\", f\\\"/api/v1/run/{flow_id}?stream=true\\\", headers=headers, json=payload) as response:\\n        assert response.status_code == status.HTTP_200_OK, response.text\\n        assert response.headers[\\\"content-type\\\"].startswith(\\\"text/event-stream\\\")\\n\\n\\n@pytest.mark.benchmark\\nasync def test_user_cannot_run_other_users_flow_with_streaming(client: AsyncClient, simple_api_test, user_two_api_key):\\n    \\\"\\\"\\\"Test that a user cannot run another user's flow with streaming.\\\"\\\"\\\"\\n    headers = {\\\"x-api-key\\\": user_two_api_key}\\n    flow_id = simple_api_test[\\\"id\\\"]\\n    payload = {\\n        \\\"input_type\\\": \\\"chat\\\",\\n        \\\"output_type\\\": \\\"debug\\\",\\n        \\\"input_value\\\": \\\"test\\\",\\n    }\\n\\n    response = await client.post(f\\\"/api/v1/run/{flow_id}?stream=true\\\", headers=headers, json=payload)\\n\\n    assert response.status_code == status.HTTP_404_NOT_FOUND, response.text\\n    assert \\\"permission\\\" not in response.text.lower()\\n\\n\\n@pytest.mark.benchmark\\nasync def test_user_can_run_own_flow_advanced_endpoint(client: AsyncClient, simple_api_test, created_api_key):\\n    \\\"\\\"\\\"Test that a user can run their own flow using the advanced endpoint.\\\"\\\"\\\"\\n    headers = {\\\"x-api-key\\\": created_api_key.api_key}\\n    flow_id = simple_api_test[\\\"id\\\"]\\n    payload = {\\n        \\\"inputs\\\": [{\\\"components\\\": [], \\\"input_value\\\": \\\"test\\\"}],\\n        \\\"outputs\\\": [],\\n        \\\"tweaks\\\": {},\\n        \\\"stream\\\": False,\\n    }\\n\\n    response = await client.post(f\\\"/api/v1/run/advanced/{flow_id}\\\", headers=headers, json=payload)\\n\\n    assert response.status_code == status.HTTP_200_OK, response.text\\n    json_response = response.json()\\n    assert \\\"session_id\\\" in json_response\\n    assert \\\"outputs\\\" in json_response\\n\\n\\n@pytest.mark.benchmark\\nasync def test_user_cannot_run_other_users_flow_advanced_endpoint(\\n    client: AsyncClient, simple_api_test, user_two_api_key\\n):\\n    \\\"\\\"\\\"Test that a user cannot run another user's flow using the advanced endpoint.\\\"\\\"\\\"\\n    headers = {\\\"x-api-key\\\": user_two_api_key}\\n    flow_id = simple_api_test[\\\"id\\\"]\\n    payload = {\\n        \\\"inputs\\\": [{\\\"components\\\": [], \\\"input_value\\\": \\\"test\\\"}],\\n        \\\"outputs\\\": [],\\n        \\\"tweaks\\\": {},\\n        \\\"stream\\\": False,\\n    }\\n\\n    response = await client.post(f\\\"/api/v1/run/advanced/{flow_id}\\\", headers=headers, json=payload)\\n\\n    assert response.status_code == status.HTTP_404_NOT_FOUND, response.text\\n    assert \\\"permission\\\" not in response.text.lower()\\n\\n\\n@pytest.mark.benchmark\\nasync def test_user_cannot_run_other_users_flow_session_endpoint(\\n    client: AsyncClient, simple_api_test, logged_in_headers, monkeypatch\\n):\\n    \\\"\\\"\\\"Regression: cross-user access on /run/session/{flow_id} returns 404.\\n\\n    ``simplified_run_flow_session`` is feature-flagged behind\\n    ``agentic_experience`` and uses session auth (``CurrentActiveUser``).\\n    We flip the flag on via monkeypatch and log in as ``active_super_user``\\n    (a different user than ``active_user`` who owns ``simple_api_test``) to\\n    exercise the session-auth variant of the wrapper dependency.\\n    \\\"\\\"\\\"\\n    from langflow.services.auth.utils import get_password_hash\\n    from langflow.services.database.models.user.model import User\\n    from langflow.services.deps import get_settings_service\\n    from lfx.services.deps import session_scope\\n    from sqlmodel import select\\n\\n    settings_service = get_settings_service()\\n    monkeypatch.setattr(settings_service.settings, \\\"agentic_experience\\\", True)\\n\\n    # Create a second user with session credentials and log in.\\n    other_username = \\\"cross_user_session_user\\\"\\n    other_password = \\\"testpassword\\\"  # noqa: S105  # pragma: allowlist secret\\n    async with session_scope() as session:\\n        existing = (await session.exec(select(User).where(User.username == other_username))).first()\\n        if existing is None:\\n            session.add(\\n                User(\\n                    username=other_username,\\n                    password=get_password_hash(other_password),\\n                    is_active=True,\\n                    is_superuser=False,\\n                )\\n            )\\n    try:\\n        login_response = await client.post(\\n            \\\"api/v1/login\\\",\\n            data={\\\"username\\\": other_username, \\\"password\\\": other_password},\\n        )\\n        assert login_response.status_code == 200\\n        other_headers = {\\\"Authorization\\\": f\\\"Bearer {login_response.json()['access_token']}\\\"}\\n\\n        flow_id = simple_api_test[\\\"id\\\"]  # owned by active_user via logged_in_headers\\n        response = await client.post(f\\\"/api/v1/run/session/{flow_id}\\\", headers=other_headers)\\n\\n        assert response.status_code == status.HTTP_404_NOT_FOUND, response.text\\n        assert \\\"permission\\\" not in response.text.lower()\\n    finally:\\n        async with session_scope() as session:\\n            user = (await session.exec(select(User).where(User.username == other_username))).first()\\n            if user is not None:\\n                await session.delete(user)\\n\\n    # Silence the unused-fixture warning -- we depend on logged_in_headers to\\n    # ensure active_user (the flow owner) exists before we attack as a peer.\\n    _ = logged_in_headers\\n\\n\\n@pytest.mark.benchmark\\nasync def test_run_rejects_malformed_user_id_query_param(client: AsyncClient, simple_api_test, created_api_key):\\n    \\\"\\\"\\\"Regression: a malformed ``?user_id=`` query param returns 404, not 500.\\n\\n    FastAPI exposes ``user_id`` as a free query parameter on routes that\\n    previously used ``Depends(get_flow_by_id_or_endpoint_name)``.  The auth-aware\\n    wrapper ignores the query value entirely (it derives user_id from the\\n    authenticated caller), and the helper itself converts a malformed UUID\\n    into 404 rather than a 500.  Both defenses must hold.\\n    \\\"\\\"\\\"\\n    headers = {\\\"x-api-key\\\": created_api_key.api_key}\\n    flow_id = simple_api_test[\\\"id\\\"]\\n\\n    for bad in (\\\"not-a-uuid\\\", \\\"\\\", \\\"12345\\\"):\\n        response = await client.post(\\n            f\\\"/api/v1/run/{flow_id}\\\",\\n            headers=headers,\\n            params={\\\"user_id\\\": bad},\\n        )\\n        # Same user owns the flow, so the wrapper resolves the flow\\n        # successfully regardless of the junk query param; the run itself\\n        # returns 200 (the flow executes) rather than leaking a 500.\\n        assert response.status_code != status.HTTP_500_INTERNAL_SERVER_ERROR, (\\n            f\\\"Malformed user_id={bad!r} triggered 500: {response.text}\\\"\\n        )\\n\\n\\n@pytest.mark.benchmark\\nasync def test_permission_check_with_nonexistent_flow(client: AsyncClient, created_api_key):\\n    \\\"\\\"\\\"Test permission check with a non-existent flow ID.\\\"\\\"\\\"\\n    headers = {\\\"x-api-key\\\": created_api_key.api_key}\\n    nonexistent_flow_id = uuid4()\\n\\n    response = await client.post(f\\\"/api/v1/run/{nonexistent_flow_id}\\\", headers=headers)\\n\\n    assert response.status_code == status.HTTP_404_NOT_FOUND, response.text\\n\\n\\n@pytest.mark.benchmark\\nasync def test_permission_check_with_invalid_flow_id(client: AsyncClient, created_api_key):\\n    \\\"\\\"\\\"Test permission check with an invalid flow ID format.\\\"\\\"\\\"\\n    headers = {\\\"x-api-key\\\": created_api_key.api_key}\\n    invalid_flow_id = \\\"not-a-valid-uuid\\\"\\n\\n    response = await client.post(f\\\"/api/v1/run/{invalid_flow_id}\\\", headers=headers)\\n\\n    assert response.status_code == status.HTTP_404_NOT_FOUND, response.text\\n\\n\\n@pytest.mark.benchmark\\nasync def test_permission_check_blocks_before_execution(client: AsyncClient, simple_api_test, user_two_api_key):\\n    \\\"\\\"\\\"Test that permission check happens before flow execution to prevent resource usage.\\n\\n    The 404 comes from ``get_flow_for_api_key_user`` which scopes lookups by\\n    user_id, so cross-user access fails closed at the dependency layer rather\\n    than via a downstream 403 (which would have given attackers a\\n    403-vs-404 existence oracle on flow UUIDs).\\n    \\\"\\\"\\\"\\n    headers = {\\\"x-api-key\\\": user_two_api_key}\\n    flow_id = simple_api_test[\\\"id\\\"]\\n    payload = {\\n        \\\"input_type\\\": \\\"chat\\\",\\n        \\\"output_type\\\": \\\"debug\\\",\\n        \\\"input_value\\\": \\\"complex computation\\\",\\n        \\\"tweaks\\\": {},\\n    }\\n\\n    # This should fail immediately at the flow-lookup dependency, not during execution\\n    response = await client.post(f\\\"/api/v1/run/{flow_id}\\\", headers=headers, json=payload)\\n\\n    assert response.status_code == status.HTTP_404_NOT_FOUND, response.text\\n    assert \\\"permission\\\" not in response.text.lower()\\n\\n\\n@pytest.mark.benchmark\\nasync def test_user_can_access_multiple_own_flows(\\n    client: AsyncClient, logged_in_headers, json_simple_api_test, created_api_key\\n):\\n    \\\"\\\"\\\"Test that a user can access multiple flows they own.\\\"\\\"\\\"\\n    # Create two flows for the same user\\n    flow1_data = orjson.loads(json_simple_api_test)\\n    flow1 = FlowCreate(name=\\\"Flow 1\\\", data=flow1_data[\\\"data\\\"], description=\\\"First flow\\\")\\n    response1 = await client.post(\\\"api/v1/flows/\\\", json=flow1.model_dump(), headers=logged_in_headers)\\n    assert response1.status_code == 201\\n    flow1_id = response1.json()[\\\"id\\\"]\\n\\n    flow2 = FlowCreate(name=\\\"Flow 2\\\", data=flow1_data[\\\"data\\\"], description=\\\"Second flow\\\")\\n    response2 = await client.post(\\\"api/v1/flows/\\\", json=flow2.model_dump(), headers=logged_in_headers)\\n    assert response2.status_code == 201\\n    flow2_id = response2.json()[\\\"id\\\"]\\n\\n    headers = {\\\"x-api-key\\\": created_api_key.api_key}\\n\\n    # User should be able to run both flows\\n    response_flow1 = await client.post(f\\\"/api/v1/run/{flow1_id}\\\", headers=headers)\\n    assert response_flow1.status_code == status.HTTP_200_OK, response_flow1.text\\n\\n    response_flow2 = await client.post(f\\\"/api/v1/run/{flow2_id}\\\", headers=headers)\\n    assert response_flow2.status_code == status.HTTP_200_OK, response_flow2.text\\n\\n    # Cleanup\\n    await client.delete(f\\\"api/v1/flows/{flow1_id}\\\", headers=logged_in_headers)\\n    await client.delete(f\\\"api/v1/flows/{flow2_id}\\\", headers=logged_in_headers)\\n\\n\\n# ============================================================================\\n# OpenAI Responses API Tests\\n# ============================================================================\\n\\n\\nasync def test_openai_responses_invalid_flow_id(client: AsyncClient, created_api_key):\\n    \\\"\\\"\\\"Test that OpenAI Responses endpoint returns error for invalid flow ID.\\\"\\\"\\\"\\n    headers = {\\\"x-api-key\\\": created_api_key.api_key}\\n    payload = {\\n        \\\"model\\\": \\\"invalid-flow-id\\\",\\n        \\\"input\\\": \\\"Hello\\\",\\n        \\\"stream\\\": False,\\n    }\\n\\n    response = await client.post(\\\"/api/v1/responses\\\", json=payload, headers=headers)\\n\\n    assert response.status_code == status.HTTP_200_OK  # Returns 200 with error in body\\n    json_response = response.json()\\n    assert \\\"error\\\" in json_response\\n    assert json_response[\\\"error\\\"][\\\"type\\\"] == \\\"invalid_request_error\\\"\\n    assert json_response[\\\"error\\\"][\\\"code\\\"] == \\\"flow_not_found\\\"\\n\\n\\nasync def test_openai_responses_tools_not_supported(client: AsyncClient, simple_api_test, created_api_key):\\n    \\\"\\\"\\\"Test that OpenAI Responses endpoint returns error when tools parameter is provided.\\\"\\\"\\\"\\n    headers = {\\\"x-api-key\\\": created_api_key.api_key}\\n    flow_id = simple_api_test[\\\"id\\\"]\\n    payload = {\\n        \\\"model\\\": flow_id,\\n        \\\"input\\\": \\\"Hello\\\",\\n        \\\"stream\\\": False,\\n        \\\"tools\\\": [{\\\"type\\\": \\\"function\\\", \\\"function\\\": {\\\"name\\\": \\\"test\\\"}}],\\n    }\\n\\n    response = await client.post(\\\"/api/v1/responses\\\", json=payload, headers=headers)\\n\\n    assert response.status_code == status.HTTP_200_OK  # Returns 200 with error in body\\n    json_response = response.json()\\n    assert \\\"error\\\" in json_response\\n    assert json_response[\\\"error\\\"][\\\"type\\\"] == \\\"invalid_request_error\\\"\\n    assert json_response[\\\"error\\\"][\\\"code\\\"] == \\\"tools_not_supported\\\"\\n\\n\\nasync def test_openai_responses_nonexistent_flow_uuid(client: AsyncClient, created_api_key):\\n    \\\"\\\"\\\"Test that OpenAI Responses endpoint returns error for nonexistent flow UUID.\\\"\\\"\\\"\\n    headers = {\\\"x-api-key\\\": created_api_key.api_key}\\n    nonexistent_flow_id = str(uuid4())\\n    payload = {\\n        \\\"model\\\": nonexistent_flow_id,\\n        \\\"input\\\": \\\"Hello\\\",\\n        \\\"stream\\\": False,\\n    }\\n\\n    response = await client.post(\\\"/api/v1/responses\\\", json=payload, headers=headers)\\n\\n    assert response.status_code == status.HTTP_200_OK  # Returns 200 with error in body\\n    json_response = response.json()\\n    assert \\\"error\\\" in json_response\\n    assert json_response[\\\"error\\\"][\\\"type\\\"] == \\\"invalid_request_error\\\"\\n    assert \\\"not found\\\" in json_response[\\\"error\\\"][\\\"message\\\"].lower()\\n\\n\\nasync def test_openai_responses_response_schema_has_usage_field(client: AsyncClient, simple_api_test, created_api_key):\\n    \\\"\\\"\\\"Test that OpenAI Responses response schema includes usage field (even if None).\\\"\\\"\\\"\\n    headers = {\\\"x-api-key\\\": created_api_key.api_key}\\n    flow_id = simple_api_test[\\\"id\\\"]\\n    payload = {\\n        \\\"model\\\": flow_id,\\n        \\\"input\\\": \\\"Hello\\\",\\n        \\\"stream\\\": False,\\n    }\\n\\n    response = await client.post(\\\"/api/v1/responses\\\", json=payload, headers=headers)\\n\\n    # simple_api_test may not have ChatInput/ChatOutput, so it might error\\n    # But if it succeeds, the response should have usage field\\n    json_response = response.json()\\n    if \\\"error\\\" not in json_response:\\n        # If no error, verify response structure includes usage\\n        assert \\\"id\\\" in json_response\\n        assert \\\"output\\\" in json_response\\n        assert \\\"usage\\\" in json_response  # usage field should always be present (can be None)\\n\\n\\nasync def test_openai_responses_rejects_cross_user_flow_access(\\n    client: AsyncClient,\\n    simple_api_test,\\n    created_api_key,  # noqa: ARG001 - used only to establish the owner's API key\\n):\\n    \\\"\\\"\\\"Regression: authenticated user cannot execute another user's flow.\\n\\n    Reproduces the IDOR scenario: a user with a valid API key passes a flow\\n    UUID owned by a different user in the ``model`` field.  The pre-fix\\n    behavior was that the endpoint executed the victim's flow and returned\\n    200 with real output; after the fix the helper resolves to\\n    flow_not_found because UUID lookups now enforce user scope.\\n    \\\"\\\"\\\"\\n    from langflow.services.auth.utils import get_password_hash\\n    from langflow.services.database.models.api_key.model import ApiKey\\n    from langflow.services.database.models.user.model import User\\n    from lfx.services.deps import session_scope\\n    from sqlmodel import select\\n\\n    attacker_api_key = \\\"attacker_random_key\\\"  # pragma: allowlist secret\\n    attacker_username = \\\"idor_attacker_user\\\"\\n\\n    # Create a second, unrelated user + API key inline.  Kept local to this\\n    # test rather than promoted to a shared fixture to minimize blast radius.\\n    async with session_scope() as session:\\n        existing = (await session.exec(select(User).where(User.username == attacker_username))).first()\\n        if existing is None:\\n            attacker = User(\\n                username=attacker_username,\\n                password=get_password_hash(\\\"testpassword\\\"),\\n                is_active=True,\\n                is_superuser=False,\\n            )\\n            session.add(attacker)\\n            await session.flush()\\n            await session.refresh(attacker)\\n        else:\\n            attacker = existing\\n        existing_key = (await session.exec(select(ApiKey).where(ApiKey.api_key == attacker_api_key))).first()\\n        if existing_key is None:\\n            key = ApiKey(\\n                name=\\\"idor_attacker_key\\\",\\n                user_id=attacker.id,\\n                api_key=attacker_api_key,\\n                hashed_api_key=get_password_hash(attacker_api_key),\\n            )\\n            session.add(key)\\n            await session.flush()\\n        attacker_id = attacker.id\\n\\n    try:\\n        victim_flow_id = simple_api_test[\\\"id\\\"]  # owned by active_user via logged_in_headers\\n        payload = {\\n            \\\"model\\\": victim_flow_id,\\n            \\\"input\\\": \\\"Hello\\\",\\n            \\\"stream\\\": False,\\n        }\\n        response = await client.post(\\n            \\\"/api/v1/responses\\\",\\n            json=payload,\\n            headers={\\\"x-api-key\\\": attacker_api_key},\\n        )\\n\\n        # The endpoint returns 200 with an OpenAI-style error body on flow-not-found\\n        # (matches test_openai_responses_nonexistent_flow_uuid behavior).\\n        assert response.status_code == status.HTTP_200_OK\\n        body = response.json()\\n        assert \\\"error\\\" in body, f\\\"Expected flow_not_found error for cross-user access, got: {body}\\\"\\n        assert body[\\\"error\\\"][\\\"code\\\"] == \\\"flow_not_found\\\", (\\n            f\\\"Expected flow_not_found for cross-user access, got code: {body['error'].get('code')}\\\"\\n        )\\n    finally:\\n        # Clean up the second user + key we created for this test.\\n        async with session_scope() as session:\\n            for api_key_row in (await session.exec(select(ApiKey).where(ApiKey.user_id == attacker_id))).all():\\n                await session.delete(api_key_row)\\n            user = await session.get(User, attacker_id)\\n            if user:\\n                await session.delete(user)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_enterprise_lifespan_hooks.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f37423a031212ca3a1f76ae1879259ff06c12131a2d578e0cf613e7442aa947c\",\"content\":\"\\\"\\\"\\\"Unit tests for the enterprise lifespan hook registry in langflow.main.\\n\\nTesting library and framework: pytest\\n\\\"\\\"\\\"\\n\\nimport pytest\\nfrom langflow.main import _enterprise_lifespan_hooks, _run_enterprise_lifespan_hooks\\n\\n\\n@pytest.fixture(autouse=True)\\ndef _clean_registry():\\n    \\\"\\\"\\\"Restore the module-global registry after each test.\\\"\\\"\\\"\\n    saved = {phase: list(hooks) for phase, hooks in _enterprise_lifespan_hooks.items()}\\n    yield\\n    for phase, hooks in saved.items():\\n        _enterprise_lifespan_hooks[phase][:] = hooks\\n\\n\\nasync def test_hooks_run_in_registration_order():\\n    calls: list[str] = []\\n\\n    async def first():\\n        calls.append(\\\"first\\\")\\n\\n    async def second():\\n        calls.append(\\\"second\\\")\\n\\n    _enterprise_lifespan_hooks[\\\"startup\\\"].extend([first, second])\\n    await _run_enterprise_lifespan_hooks(\\\"startup\\\")\\n    assert calls == [\\\"first\\\", \\\"second\\\"]\\n\\n\\nasync def test_failing_hook_does_not_block_later_hooks():\\n    calls: list[str] = []\\n\\n    async def broken():\\n        msg = \\\"boom\\\"\\n        raise RuntimeError(msg)\\n\\n    async def survivor():\\n        calls.append(\\\"survivor\\\")\\n\\n    _enterprise_lifespan_hooks[\\\"shutdown\\\"].extend([broken, survivor])\\n    # Must not raise: hooks are best-effort by contract.\\n    await _run_enterprise_lifespan_hooks(\\\"shutdown\\\")\\n    assert calls == [\\\"survivor\\\"]\\n\\n\\nasync def test_unknown_phase_is_a_noop():\\n    await _run_enterprise_lifespan_hooks(\\\"no-such-phase\\\")\\n\\n\\nasync def test_registry_has_expected_phases():\\n    assert set(_enterprise_lifespan_hooks) == {\\\"startup\\\", \\\"shutdown\\\"}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_enterprise_readiness_checks.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"49dcc68c2addf3c569ed9af427295a8347caec9b683452e9602c44d9cbf80e61\",\"content\":\"\\\"\\\"\\\"Unit tests for the enterprise readiness check registry in health_check_router.\\n\\nTesting library and framework: pytest\\n\\\"\\\"\\\"\\n\\nimport asyncio\\nfrom types import SimpleNamespace\\nfrom unittest.mock import AsyncMock, MagicMock, patch\\n\\nimport pytest\\nfrom fastapi import HTTPException\\nfrom langflow.api.health_check_router import _enterprise_readiness_checks, healthz\\n\\n\\n@pytest.fixture(autouse=True)\\ndef _clean_registry():\\n    \\\"\\\"\\\"Restore the module-global registry after each test.\\\"\\\"\\\"\\n    saved = list(_enterprise_readiness_checks)\\n    yield\\n    _enterprise_readiness_checks[:] = saved\\n\\n\\n@pytest.fixture\\ndef fake_session():\\n    \\\"\\\"\\\"Minimal async session double that satisfies the healthz DB probe.\\\"\\\"\\\"\\n    exec_result = MagicMock()\\n    exec_result.first.return_value = None\\n    session = AsyncMock()\\n    session.exec = AsyncMock(return_value=exec_result)\\n    return session\\n\\n\\n@pytest.fixture\\ndef _patch_services():\\n    \\\"\\\"\\\"Patch get_chat_service and get_settings_service for healthz.\\n\\n    Returns worker_timeout=300 to match the /health_check route's effective timeout.\\n    \\\"\\\"\\\"\\n    fake_chat = AsyncMock()\\n    fake_settings = SimpleNamespace(settings=SimpleNamespace(worker_timeout=300))\\n    with (\\n        patch(\\\"langflow.api.health_check_router.get_chat_service\\\", return_value=fake_chat),\\n        patch(\\\"langflow.api.health_check_router.get_settings_service\\\", return_value=fake_settings),\\n    ):\\n        yield\\n\\n\\n# ---------------------------------------------------------------------------\\n# Registry state\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_registry_is_empty_by_default():\\n    assert _enterprise_readiness_checks == []\\n\\n\\n# ---------------------------------------------------------------------------\\n# Registry: check callable contract \u2014 \\\"ok\\\" result\\n# ---------------------------------------------------------------------------\\n\\n\\nasync def test_passing_check_returns_name_and_ok():\\n    async def always_ok():\\n        return (\\\"entitlement\\\", \\\"ok\\\")\\n\\n    _enterprise_readiness_checks.append(always_ok)\\n\\n    name, result = await _enterprise_readiness_checks[0]()\\n    assert name == \\\"entitlement\\\"\\n    assert result == \\\"ok\\\"\\n    assert not result.startswith(\\\"error:\\\")\\n\\n\\n# ---------------------------------------------------------------------------\\n# Registry: check callable contract \u2014 \\\"error:\\\" result\\n# ---------------------------------------------------------------------------\\n\\n\\nasync def test_error_check_result_starts_with_error_colon():\\n    async def failing_check():\\n        return (\\\"entitlement\\\", \\\"error: entitlement lost\\\")\\n\\n    _enterprise_readiness_checks.append(failing_check)\\n\\n    name, result = await _enterprise_readiness_checks[0]()\\n    assert name == \\\"entitlement\\\"\\n    assert result.startswith(\\\"error:\\\")\\n\\n\\n# ---------------------------------------------------------------------------\\n# Registry: checks run in registration order\\n# ---------------------------------------------------------------------------\\n\\n\\nasync def test_checks_run_in_registration_order():\\n    calls: list[str] = []\\n\\n    async def first():\\n        calls.append(\\\"first\\\")\\n        return (\\\"a\\\", \\\"ok\\\")\\n\\n    async def second():\\n        calls.append(\\\"second\\\")\\n        return (\\\"b\\\", \\\"ok\\\")\\n\\n    _enterprise_readiness_checks.extend([first, second])\\n\\n    for check in list(_enterprise_readiness_checks):\\n        await check()\\n\\n    assert calls == [\\\"first\\\", \\\"second\\\"]\\n\\n\\n# ---------------------------------------------------------------------------\\n# /healthz handler behaviour \u2014 exercised via the real handler\\n# ---------------------------------------------------------------------------\\n\\n\\n@pytest.mark.usefixtures(\\\"_patch_services\\\")\\nasync def test_healthz_returns_ok_with_empty_registry(fake_session):\\n    \\\"\\\"\\\"No registered checks \u2192 healthy response.\\\"\\\"\\\"\\n    response = await healthz(session=fake_session)\\n    assert response.status == \\\"ok\\\"\\n    assert response.db == \\\"ok\\\"\\n    assert response.chat == \\\"ok\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"_patch_services\\\")\\nasync def test_healthz_returns_ok_when_all_checks_pass(fake_session):\\n    \\\"\\\"\\\"All registered checks succeed \u2192 healthy response.\\\"\\\"\\\"\\n\\n    async def always_ok():\\n        return (\\\"entitlement\\\", \\\"ok\\\")\\n\\n    _enterprise_readiness_checks.append(always_ok)\\n\\n    response = await healthz(session=fake_session)\\n    assert response.status == \\\"ok\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"_patch_services\\\")\\nasync def test_healthz_raises_503_on_error_result(fake_session):\\n    \\\"\\\"\\\"A check returning 'error:\u2026' causes a 503 with a generic detail.\\\"\\\"\\\"\\n\\n    async def failing_check():\\n        return (\\\"entitlement\\\", \\\"error: entitlement lost\\\")\\n\\n    _enterprise_readiness_checks.append(failing_check)\\n\\n    with pytest.raises(HTTPException) as exc_info:\\n        await healthz(session=fake_session)\\n\\n    assert exc_info.value.status_code == 503\\n    # Detail must be generic \u2014 no plugin name or raw result exposed to clients.\\n    assert exc_info.value.detail == \\\"Service unavailable\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"_patch_services\\\")\\nasync def test_healthz_returns_ok_for_non_error_prefix_status(fake_session):\\n    \\\"\\\"\\\"A check returning a non-'error:' status (e.g. 'errorless') must not trigger 503.\\\"\\\"\\\"\\n\\n    async def ambiguous_check():\\n        return (\\\"entitlement\\\", \\\"errorless\\\")\\n\\n    _enterprise_readiness_checks.append(ambiguous_check)\\n\\n    # Must complete successfully \u2014 'errorless' does not start with 'error:'\\n    response = await healthz(session=fake_session)\\n    assert response.status == \\\"ok\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"_patch_services\\\")\\nasync def test_healthz_first_error_short_circuits_remaining_checks(fake_session):\\n    \\\"\\\"\\\"The first error-result check stops further checks immediately.\\\"\\\"\\\"\\n    calls: list[str] = []\\n\\n    async def first_fail():\\n        calls.append(\\\"first\\\")\\n        return (\\\"check_a\\\", \\\"error: first failed\\\")\\n\\n    async def second():\\n        calls.append(\\\"second\\\")\\n        return (\\\"check_b\\\", \\\"ok\\\")\\n\\n    _enterprise_readiness_checks.extend([first_fail, second])\\n\\n    with pytest.raises(HTTPException):\\n        await healthz(session=fake_session)\\n\\n    assert \\\"first\\\" in calls\\n    assert \\\"second\\\" not in calls\\n\\n\\n@pytest.mark.usefixtures(\\\"_patch_services\\\")\\nasync def test_healthz_swallows_crashing_check(fake_session):\\n    \\\"\\\"\\\"An exception from a check is logged and swallowed \u2014 no 503, no propagation.\\\"\\\"\\\"\\n\\n    async def boom():\\n        msg = \\\"unexpected crash\\\"\\n        raise RuntimeError(msg)\\n\\n    _enterprise_readiness_checks.append(boom)\\n\\n    # Must complete successfully \u2014 crash is swallowed.\\n    response = await healthz(session=fake_session)\\n    assert response.status == \\\"ok\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"_patch_services\\\")\\nasync def test_healthz_503_when_db_and_chat_fail(fake_session):\\n    \\\"\\\"\\\"DB and chat failures \u2192 500, not a 503 from the enterprise checks path.\\\"\\\"\\\"\\n    fake_session.exec.side_effect = RuntimeError(\\\"db down\\\")\\n\\n    with pytest.raises(HTTPException) as exc_info:\\n        await healthz(session=fake_session)\\n\\n    assert exc_info.value.status_code == 500\\n\\n\\n@pytest.mark.usefixtures(\\\"_patch_services\\\")\\nasync def test_healthz_raises_503_on_timeout(fake_session):\\n    \\\"\\\"\\\"A check that remains pending longer than worker_timeout triggers a real asyncio timeout.\\\"\\\"\\\"\\n\\n    async def slow_check():\\n        # Waits on an Event that is never set \u2014 stays pending until cancelled.\\n        await asyncio.Event().wait()\\n        return (\\\"entitlement\\\", \\\"ok\\\")  # pragma: no cover\\n\\n    _enterprise_readiness_checks.append(slow_check)\\n\\n    with (\\n        patch(\\n            \\\"langflow.api.health_check_router.get_settings_service\\\",\\n            return_value=SimpleNamespace(settings=SimpleNamespace(worker_timeout=0.01)),\\n        ),\\n        pytest.raises(HTTPException) as exc_info,\\n    ):\\n        await healthz(session=fake_session)\\n\\n    assert exc_info.value.status_code == 503\\n    assert exc_info.value.detail == \\\"Service unavailable\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"_patch_services\\\")\\nasync def test_healthz_chat_failure_returns_500(fake_session):\\n    \\\"\\\"\\\"Chat service failure (not DB) still causes 500 via has_error path.\\\"\\\"\\\"\\n    with (\\n        patch(\\\"langflow.api.health_check_router.get_chat_service\\\", side_effect=RuntimeError(\\\"chat down\\\")),\\n        pytest.raises(HTTPException) as exc_info,\\n    ):\\n        await healthz(session=fake_session)\\n\\n    assert exc_info.value.status_code == 500\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_exception_telemetry.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4b99cbc4b81108911047fd6c7b3725774f253ff8184f4ebc81f63dd8d9b5a087\",\"content\":\"\\\"\\\"\\\"Unit tests for exception telemetry.\\\"\\\"\\\"\\n\\nimport hashlib\\nimport traceback\\nfrom unittest.mock import AsyncMock, MagicMock\\n\\nimport pytest\\nfrom langflow.services.telemetry.schema import ExceptionPayload\\nfrom langflow.services.telemetry.service import TelemetryService\\n\\n\\nclass TestExceptionTelemetry:\\n    \\\"\\\"\\\"Unit test suite for exception telemetry functionality.\\\"\\\"\\\"\\n\\n    def test_exception_payload_schema(self):\\n        \\\"\\\"\\\"Test ExceptionPayload schema creation and serialization.\\\"\\\"\\\"\\n        payload = ExceptionPayload(\\n            exception_type=\\\"ValueError\\\",\\n            exception_message=\\\"Test error message\\\",\\n            exception_context=\\\"handler\\\",\\n            stack_trace_hash=\\\"abc123def456\\\",  # pragma: allowlist secret\\n        )\\n\\n        # Test serialization with aliases\\n        data = payload.model_dump(by_alias=True, exclude_none=True)\\n\\n        expected_fields = {\\n            \\\"exceptionType\\\": \\\"ValueError\\\",\\n            \\\"exceptionMessage\\\": \\\"Test error message\\\",\\n            \\\"exceptionContext\\\": \\\"handler\\\",\\n            \\\"stackTraceHash\\\": \\\"abc123def456\\\",  # pragma: allowlist secret\\n        }\\n\\n        assert data == expected_fields\\n\\n    @pytest.mark.asyncio\\n    async def test_log_exception_method(self):\\n        \\\"\\\"\\\"Test the log_exception method creates proper payload.\\\"\\\"\\\"\\n        # Create a minimal telemetry service for testing\\n        telemetry_service = TelemetryService.__new__(TelemetryService)\\n        telemetry_service.do_not_track = False\\n        telemetry_service._stopping = False\\n        telemetry_service.client_type = \\\"oss\\\"\\n\\n        # Mock the _queue_event method to capture calls\\n        captured_events = []\\n\\n        async def mock_queue_event(event_tuple):\\n            captured_events.append(event_tuple)\\n\\n        telemetry_service._queue_event = mock_queue_event\\n\\n        # Test exception\\n        test_exception = RuntimeError(\\\"Test exception message\\\")\\n\\n        # Call log_exception\\n        await telemetry_service.log_exception(test_exception, \\\"handler\\\")\\n\\n        # Verify event was queued\\n        assert len(captured_events) == 1\\n\\n        _func, payload, path = captured_events[0]\\n\\n        # Verify payload\\n        assert isinstance(payload, ExceptionPayload)\\n        assert payload.exception_type == \\\"RuntimeError\\\"\\n        assert payload.exception_message == \\\"Test exception message\\\"\\n        assert payload.exception_context == \\\"handler\\\"\\n        assert payload.stack_trace_hash is not None\\n        assert len(payload.stack_trace_hash) == 16  # MD5 hash truncated to 16 chars\\n\\n        # Verify path\\n        assert path == \\\"exception\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_send_telemetry_data_success(self):\\n        \\\"\\\"\\\"Test successful telemetry data sending.\\\"\\\"\\\"\\n        # Create minimal service\\n        telemetry_service = TelemetryService.__new__(TelemetryService)\\n        telemetry_service.base_url = \\\"https://mock-telemetry.example.com\\\"\\n        telemetry_service.do_not_track = False\\n        telemetry_service.client_type = \\\"oss\\\"\\n        telemetry_service.common_telemetry_fields = {\\n            \\\"langflow_version\\\": \\\"1.0.0\\\",\\n            \\\"platform\\\": \\\"python_package\\\",\\n            \\\"os\\\": \\\"linux\\\",\\n        }\\n\\n        # Mock HTTP client\\n        mock_response = MagicMock()\\n        mock_response.status_code = 200\\n        mock_client = AsyncMock()\\n        mock_client.get.return_value = mock_response\\n        telemetry_service.client = mock_client\\n\\n        payload = ExceptionPayload(\\n            exception_type=\\\"ValueError\\\",\\n            exception_message=\\\"Test error\\\",\\n            exception_context=\\\"handler\\\",\\n            stack_trace_hash=\\\"abc123\\\",\\n        )\\n\\n        # Send telemetry\\n        await telemetry_service.send_telemetry_data(payload, \\\"exception\\\")\\n\\n        # Verify HTTP call was made\\n        mock_client.get.assert_called_once()\\n        call_args = mock_client.get.call_args\\n\\n        # Check URL\\n        assert call_args[0][0] == \\\"https://mock-telemetry.example.com/exception\\\"\\n\\n        # Check query parameters (should include common telemetry fields)\\n        params = call_args[1][\\\"params\\\"]\\n        assert params[\\\"exceptionType\\\"] == \\\"ValueError\\\"\\n        assert params[\\\"exceptionMessage\\\"] == \\\"Test error\\\"\\n        assert params[\\\"exceptionContext\\\"] == \\\"handler\\\"\\n        assert params[\\\"stackTraceHash\\\"] == \\\"abc123\\\"\\n        assert params[\\\"clientType\\\"] == \\\"oss\\\"\\n        assert params[\\\"langflow_version\\\"] == \\\"1.0.0\\\"\\n        assert params[\\\"platform\\\"] == \\\"python_package\\\"\\n        assert params[\\\"os\\\"] == \\\"linux\\\"\\n        assert \\\"timestamp\\\" in params\\n\\n    @pytest.mark.asyncio\\n    async def test_send_telemetry_data_respects_do_not_track(self):\\n        \\\"\\\"\\\"Test that do_not_track setting prevents telemetry.\\\"\\\"\\\"\\n        # Create service with do_not_track enabled\\n        telemetry_service = TelemetryService.__new__(TelemetryService)\\n        telemetry_service.base_url = \\\"https://mock-telemetry.example.com\\\"\\n        telemetry_service.do_not_track = True\\n        telemetry_service.client_type = \\\"oss\\\"\\n        telemetry_service.common_telemetry_fields = {\\n            \\\"langflow_version\\\": \\\"1.0.0\\\",\\n            \\\"platform\\\": \\\"python_package\\\",\\n            \\\"os\\\": \\\"linux\\\",\\n        }\\n\\n        # Mock HTTP client\\n        mock_client = AsyncMock()\\n        telemetry_service.client = mock_client\\n\\n        payload = ExceptionPayload(\\n            exception_type=\\\"ValueError\\\",\\n            exception_message=\\\"Test error\\\",\\n            exception_context=\\\"handler\\\",\\n            stack_trace_hash=\\\"abc123\\\",\\n        )\\n\\n        # Send telemetry - should be blocked\\n        await telemetry_service.send_telemetry_data(payload, \\\"exception\\\")\\n\\n        # Verify no HTTP call was made\\n        mock_client.get.assert_not_called()\\n\\n    def test_stack_trace_hash_consistency(self):\\n        \\\"\\\"\\\"Test that same exceptions produce same hash.\\\"\\\"\\\"\\n\\n        def create_test_exception():\\n            try:\\n                msg = \\\"Consistent test message\\\"\\n                raise ValueError(msg)\\n            except ValueError as e:\\n                return e\\n\\n        exc1 = create_test_exception()\\n        exc2 = create_test_exception()\\n\\n        # Generate hashes the same way as log_exception\\n        def get_hash(exc):\\n            stack_trace = traceback.format_exception(type(exc), exc, exc.__traceback__)\\n            stack_trace_str = \\\"\\\".join(stack_trace)\\n            return hashlib.sha256(stack_trace_str.encode()).hexdigest()[:16]\\n\\n        hash1 = get_hash(exc1)\\n        hash2 = get_hash(exc2)\\n\\n        # Hashes should be the same for same exception type and location\\n        assert hash1 == hash2\\n\\n    @pytest.mark.asyncio\\n    async def test_query_params_url_length_limit(self):\\n        \\\"\\\"\\\"Test that query parameters don't exceed URL length limits.\\\"\\\"\\\"\\n        telemetry_service = TelemetryService.__new__(TelemetryService)\\n        telemetry_service.base_url = \\\"https://mock-telemetry.example.com\\\"\\n        telemetry_service.do_not_track = False\\n        telemetry_service.client_type = \\\"oss\\\"\\n        telemetry_service.common_telemetry_fields = {\\n            \\\"langflow_version\\\": \\\"1.0.0\\\",\\n            \\\"platform\\\": \\\"python_package\\\",\\n            \\\"os\\\": \\\"linux\\\",\\n        }\\n\\n        # Create payload with very long message\\n        long_message = \\\"A\\\" * 2000  # Very long message\\n        payload = ExceptionPayload(\\n            exception_type=\\\"ValueError\\\",\\n            exception_message=long_message,\\n            exception_context=\\\"handler\\\",\\n            stack_trace_hash=\\\"abc123\\\",\\n        )\\n\\n        mock_client = AsyncMock()\\n        telemetry_service.client = mock_client\\n\\n        await telemetry_service.send_telemetry_data(payload, \\\"exception\\\")\\n\\n        # Verify HTTP call was made\\n        mock_client.get.assert_called_once()\\n        call_args = mock_client.get.call_args\\n\\n        # Check that URL doesn't exceed reasonable length (typically 2048 chars)\\n        full_url = call_args[0][0]\\n        assert len(full_url) < 2048, f\\\"URL too long: {len(full_url)} characters\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_query_params_special_characters(self):\\n        \\\"\\\"\\\"Test that special characters in query parameters are properly encoded.\\\"\\\"\\\"\\n        telemetry_service = TelemetryService.__new__(TelemetryService)\\n        telemetry_service.base_url = \\\"https://mock-telemetry.example.com\\\"\\n        telemetry_service.do_not_track = False\\n        telemetry_service.client_type = \\\"oss\\\"\\n        telemetry_service.common_telemetry_fields = {\\n            \\\"langflow_version\\\": \\\"1.0.0\\\",\\n            \\\"platform\\\": \\\"python_package\\\",\\n            \\\"os\\\": \\\"linux\\\",\\n        }\\n\\n        # Create payload with special characters\\n        special_message = \\\"Error with special chars: &?=#@!$%^&*()\\\"\\n        payload = ExceptionPayload(\\n            exception_type=\\\"ValueError\\\",\\n            exception_message=special_message,\\n            exception_context=\\\"handler\\\",\\n            stack_trace_hash=\\\"abc123\\\",\\n        )\\n\\n        mock_client = AsyncMock()\\n        telemetry_service.client = mock_client\\n\\n        await telemetry_service.send_telemetry_data(payload, \\\"exception\\\")\\n\\n        # Verify HTTP call was made\\n        mock_client.get.assert_called_once()\\n        call_args = mock_client.get.call_args\\n\\n        # Check that special characters are properly encoded\\n        full_url = call_args[0][0]\\n        assert \\\"&\\\" not in full_url or \\\"%26\\\" in full_url, \\\"Ampersand not properly encoded\\\"\\n        assert \\\"?\\\" not in full_url or \\\"%3F\\\" in full_url, \\\"Question mark not properly encoded\\\"\\n        assert \\\"=\\\" not in full_url or \\\"%3D\\\" in full_url, \\\"Equals sign not properly encoded\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_query_params_sensitive_data_exposure(self):\\n        \\\"\\\"\\\"Test that sensitive data is not exposed in query parameters.\\\"\\\"\\\"\\n        telemetry_service = TelemetryService.__new__(TelemetryService)\\n        telemetry_service.base_url = \\\"https://mock-telemetry.example.com\\\"\\n        telemetry_service.do_not_track = False\\n        telemetry_service.client_type = \\\"oss\\\"\\n        telemetry_service.common_telemetry_fields = {\\n            \\\"langflow_version\\\": \\\"1.0.0\\\",\\n            \\\"platform\\\": \\\"python_package\\\",\\n            \\\"os\\\": \\\"linux\\\",\\n        }\\n\\n        # Create payload with potentially sensitive data\\n        sensitive_message = \\\"Password: secret123, API Key: sk-abc123, Token: xyz789\\\"\\n        payload = ExceptionPayload(\\n            exception_type=\\\"ValueError\\\",\\n            exception_message=sensitive_message,\\n            exception_context=\\\"handler\\\",\\n            stack_trace_hash=\\\"abc123\\\",\\n        )\\n\\n        mock_client = AsyncMock()\\n        telemetry_service.client = mock_client\\n\\n        await telemetry_service.send_telemetry_data(payload, \\\"exception\\\")\\n\\n        # Verify HTTP call was made\\n        mock_client.get.assert_called_once()\\n        call_args = mock_client.get.call_args\\n\\n        # Check that sensitive data is not in URL (should be in request body instead)\\n        full_url = call_args[0][0]\\n        sensitive_patterns = [\\\"secret123\\\", \\\"sk-abc123\\\", \\\"xyz789\\\"]\\n        for pattern in sensitive_patterns:\\n            assert pattern not in full_url, f\\\"Sensitive data '{pattern}' found in URL\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_query_params_unicode_characters(self):\\n        \\\"\\\"\\\"Test that unicode characters in query parameters are handled correctly.\\\"\\\"\\\"\\n        telemetry_service = TelemetryService.__new__(TelemetryService)\\n        telemetry_service.base_url = \\\"https://mock-telemetry.example.com\\\"\\n        telemetry_service.do_not_track = False\\n        telemetry_service.client_type = \\\"oss\\\"\\n        telemetry_service.common_telemetry_fields = {\\n            \\\"langflow_version\\\": \\\"1.0.0\\\",\\n            \\\"platform\\\": \\\"python_package\\\",\\n            \\\"os\\\": \\\"linux\\\",\\n        }\\n\\n        # Create payload with unicode characters\\n        unicode_message = \\\"Error with unicode: \u4e16\u754c, \ud83d\ude80, \u00e9mojis\\\"\\n        payload = ExceptionPayload(\\n            exception_type=\\\"ValueError\\\",\\n            exception_message=unicode_message,\\n            exception_context=\\\"handler\\\",\\n            stack_trace_hash=\\\"abc123\\\",\\n        )\\n\\n        mock_client = AsyncMock()\\n        telemetry_service.client = mock_client\\n\\n        await telemetry_service.send_telemetry_data(payload, \\\"exception\\\")\\n\\n        # Verify HTTP call was made\\n        mock_client.get.assert_called_once()\\n        call_args = mock_client.get.call_args\\n\\n        # Check that unicode characters are properly handled\\n        full_url = call_args[0][0]\\n        # URL should be valid and not cause encoding issues\\n        assert len(full_url) > 0, \\\"URL should not be empty\\\"\\n        # Should not contain raw unicode characters that could cause issues\\n        assert \\\"\u4e16\u754c\\\" not in full_url or \\\"%E4%B8%96%E7%95%8C\\\" in full_url\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_experimental_components.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"93c1283a45cae262a78ab0d653e33ef836acaa446cfd99811f9e4a6cd0e473ce\",\"content\":\"import pytest\\nfrom lfx.components import prototypes\\nfrom lfx.services.deps import get_settings_service\\nfrom lfx.utils.python_repl_security import CodeExecutionDisabledError\\n\\n\\ndef test_python_function_component():\\n    # Arrange\\n    python_function_component = prototypes.PythonFunctionComponent()\\n\\n    # Act\\n    # function must be a string representation\\n    function = \\\"def function():\\\\n    return 'Hello, World!'\\\"\\n    python_function_component.function_code = function\\n    # result is the callable function\\n    result = python_function_component.get_function_callable()\\n    result_message = python_function_component.execute_function_message()\\n    result_data = python_function_component.execute_function_data()\\n\\n    # Assert\\n    assert result() == \\\"Hello, World!\\\"\\n    assert result_message.text == \\\"Hello, World!\\\"\\n    assert result_data[0].text == \\\"Hello, World!\\\"\\n\\n\\ndef test_python_function_component_respects_code_execution_policy(monkeypatch):\\n    component = prototypes.PythonFunctionComponent()\\n    component.function_code = \\\"def function():\\\\n    return 'unsafe'\\\"\\n    monkeypatch.setattr(get_settings_service().settings, \\\"allow_custom_components\\\", False)\\n\\n    with pytest.raises(CodeExecutionDisabledError):\\n        component.get_function_callable()\\n    with pytest.raises(CodeExecutionDisabledError):\\n        component.execute_function()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_extension_events_service.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6af6e14165c94bf643b6a52195c6d64f3e36319356bea44c938864bbff2763f4\",\"content\":\"import multiprocessing\\nimport time\\n\\nfrom lfx.services.extension_events.service import ExtensionEventsService\\n\\n\\ndef _worker_emit(cache_dir, event_type, payload):\\n    \\\"\\\"\\\"Top-level helper for multiprocessing tests; must be picklable.\\\"\\\"\\\"\\n    svc = ExtensionEventsService(cache_dir=cache_dir)\\n    svc.emit(event_type, payload)\\n\\n\\n# ---------------------------------------------------------------------------\\n# Basic emit / since\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_emit_and_since(tmp_path):\\n    svc = ExtensionEventsService(cache_dir=tmp_path / \\\"cache\\\")\\n    svc.emit(\\\"bundle_reloaded\\\", {\\\"bundle\\\": \\\"my-ext\\\", \\\"reload_id\\\": \\\"r1\\\"})\\n    svc.emit(\\\"bundle_reload_failed\\\", {\\\"bundle\\\": \\\"my-ext\\\", \\\"reload_id\\\": \\\"r2\\\"})\\n\\n    events, settled = svc.since(0.0)\\n    assert len(events) == 2\\n    assert events[0].type == \\\"bundle_reloaded\\\"\\n    assert events[1].type == \\\"bundle_reload_failed\\\"\\n    assert events[0].payload[\\\"bundle\\\"] == \\\"my-ext\\\"\\n    assert not settled\\n\\n\\ndef test_since_filters_by_timestamp(tmp_path):\\n    svc = ExtensionEventsService(cache_dir=tmp_path / \\\"cache\\\")\\n    e1 = svc.emit(\\\"bundle_reloaded\\\", {\\\"bundle\\\": \\\"a\\\"})\\n    svc.emit(\\\"flow_migrated\\\", {\\\"flow_id\\\": \\\"f1\\\"})\\n\\n    events, _ = svc.since(e1.timestamp)\\n    assert len(events) == 1\\n    assert events[0].type == \\\"flow_migrated\\\"\\n\\n\\ndef test_cursor_at_or_before_event_excluded(tmp_path):\\n    svc = ExtensionEventsService(cache_dir=tmp_path / \\\"cache\\\")\\n    e1 = svc.emit(\\\"bundle_reloaded\\\", {\\\"bundle\\\": \\\"a\\\"})\\n\\n    events, _ = svc.since(e1.timestamp)\\n    assert events == []\\n\\n\\ndef test_empty_keyspace_returns_settled(tmp_path):\\n    svc = ExtensionEventsService(cache_dir=tmp_path / \\\"cache\\\")\\n    events, settled = svc.since(0.0)\\n    assert events == []\\n    assert settled is True\\n\\n\\n# ---------------------------------------------------------------------------\\n# Settled logic\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_settled_on_timeout(tmp_path):\\n    svc = ExtensionEventsService(cache_dir=tmp_path / \\\"cache\\\")\\n    svc.SETTLE_TIMEOUT = 0.1\\n    svc.emit(\\\"bundle_reloaded\\\", {\\\"bundle\\\": \\\"a\\\"})\\n\\n    time.sleep(0.15)\\n\\n    _, settled = svc.since(0.0)\\n    assert settled is True\\n\\n\\ndef test_not_settled_with_recent_event(tmp_path):\\n    svc = ExtensionEventsService(cache_dir=tmp_path / \\\"cache\\\")\\n    svc.emit(\\\"bundle_reloaded\\\", {\\\"bundle\\\": \\\"a\\\"})\\n\\n    _, settled = svc.since(0.0)\\n    assert settled is False\\n\\n\\n# ---------------------------------------------------------------------------\\n# TTL expiry\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_ttl_expiry(tmp_path):\\n    svc = ExtensionEventsService(cache_dir=tmp_path / \\\"cache\\\")\\n    svc.TTL_SECONDS = 0.1\\n    svc.emit(\\\"bundle_reloaded\\\", {\\\"bundle\\\": \\\"a\\\"})\\n\\n    time.sleep(0.15)\\n\\n    events, _ = svc.since(0.0)\\n    assert len(events) == 0\\n\\n\\ndef test_cleanup_removes_expired(tmp_path):\\n    svc = ExtensionEventsService(cache_dir=tmp_path / \\\"cache\\\")\\n    svc.TTL_SECONDS = 0.1\\n    svc.emit(\\\"bundle_reloaded\\\", {\\\"bundle\\\": \\\"a\\\"})\\n\\n    time.sleep(0.15)\\n    svc.cleanup()\\n\\n    events, _ = svc.since(0.0)\\n    assert len(events) == 0\\n\\n\\n# ---------------------------------------------------------------------------\\n# Global cap eviction\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_global_cap_eviction(tmp_path):\\n    svc = ExtensionEventsService(cache_dir=tmp_path / \\\"cache\\\")\\n    svc.MAX_EVENTS = 5\\n\\n    for i in range(10):\\n        svc.emit(\\\"bundle_reloaded\\\", {\\\"bundle\\\": f\\\"b{i}\\\"})\\n\\n    events, _ = svc.since(0.0)\\n    assert len(events) == 5\\n    # Should keep the 5 most recent\\n    assert events[0].payload[\\\"bundle\\\"] == \\\"b5\\\"\\n    assert events[-1].payload[\\\"bundle\\\"] == \\\"b9\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# Invalid event type\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_invalid_event_type_raises(tmp_path):\\n    svc = ExtensionEventsService(cache_dir=tmp_path / \\\"cache\\\")\\n    import pytest\\n\\n    with pytest.raises(ValueError, match=\\\"Invalid event type\\\"):\\n        svc.emit(\\\"not_a_real_event\\\", {})\\n\\n\\n# ---------------------------------------------------------------------------\\n# Keyspace isolation\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_keyspace_isolation(tmp_path):\\n    svc = ExtensionEventsService(cache_dir=tmp_path / \\\"cache\\\")\\n    svc.emit(\\\"bundle_reloaded\\\", {\\\"bundle\\\": \\\"a\\\"}, keyspace=\\\"global\\\")\\n    svc.emit(\\\"flow_migrated\\\", {\\\"flow_id\\\": \\\"f1\\\"}, keyspace=\\\"session:abc\\\")\\n\\n    global_events, _ = svc.since(0.0, keyspace=\\\"global\\\")\\n    session_events, _ = svc.since(0.0, keyspace=\\\"session:abc\\\")\\n\\n    assert len(global_events) == 1\\n    assert global_events[0].type == \\\"bundle_reloaded\\\"\\n\\n    assert len(session_events) == 1\\n    assert session_events[0].type == \\\"flow_migrated\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# Cross-worker visibility (same process, two service instances)\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_cross_worker_visibility(tmp_path):\\n    \\\"\\\"\\\"Two service instances sharing a cache_dir see each other's events.\\\"\\\"\\\"\\n    shared = tmp_path / \\\"shared\\\"\\n\\n    worker_a = ExtensionEventsService(cache_dir=shared)\\n    worker_b = ExtensionEventsService(cache_dir=shared)\\n\\n    worker_a.emit(\\\"bundle_reloaded\\\", {\\\"bundle\\\": \\\"a\\\", \\\"reload_id\\\": \\\"r1\\\"})\\n\\n    events, _ = worker_b.since(0.0)\\n    assert len(events) == 1\\n    assert events[0].payload[\\\"bundle\\\"] == \\\"a\\\"\\n\\n    worker_b.emit(\\\"bundle_reload_failed\\\", {\\\"bundle\\\": \\\"b\\\", \\\"reload_id\\\": \\\"r2\\\"})\\n\\n    events, _ = worker_a.since(0.0)\\n    assert len(events) == 2\\n\\n\\ndef test_cross_worker_keyspace_isolation(tmp_path):\\n    shared = tmp_path / \\\"shared\\\"\\n\\n    worker_a = ExtensionEventsService(cache_dir=shared)\\n    worker_b = ExtensionEventsService(cache_dir=shared)\\n\\n    worker_a.emit(\\\"bundle_reloaded\\\", {\\\"bundle\\\": \\\"a\\\"}, keyspace=\\\"global\\\")\\n    worker_b.emit(\\\"flow_migrated\\\", {\\\"flow_id\\\": \\\"f1\\\"}, keyspace=\\\"session:xyz\\\")\\n\\n    global_events, _ = worker_b.since(0.0, keyspace=\\\"global\\\")\\n    session_events, _ = worker_a.since(0.0, keyspace=\\\"session:xyz\\\")\\n\\n    assert len(global_events) == 1\\n    assert len(session_events) == 1\\n\\n\\ndef test_cross_worker_ttl_expiry(tmp_path):\\n    \\\"\\\"\\\"Expired events are invisible to all workers.\\\"\\\"\\\"\\n    shared = tmp_path / \\\"shared\\\"\\n\\n    worker_a = ExtensionEventsService(cache_dir=shared)\\n    worker_a.TTL_SECONDS = 0.1\\n    worker_a.emit(\\\"bundle_reloaded\\\", {\\\"bundle\\\": \\\"a\\\"})\\n\\n    time.sleep(0.15)\\n\\n    worker_b = ExtensionEventsService(cache_dir=shared)\\n    events, _ = worker_b.since(0.0)\\n    assert len(events) == 0\\n\\n\\n# ---------------------------------------------------------------------------\\n# Multi-process visibility\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_multi_process_visibility(tmp_path):\\n    \\\"\\\"\\\"A separate OS process can write events that this process reads.\\\"\\\"\\\"\\n    shared = tmp_path / \\\"shared\\\"\\n\\n    ctx = multiprocessing.get_context(\\\"spawn\\\")\\n    proc = ctx.Process(\\n        target=_worker_emit,\\n        args=(str(shared), \\\"bundle_reloaded\\\", {\\\"bundle\\\": \\\"from-child\\\", \\\"reload_id\\\": \\\"mp-1\\\"}),\\n    )\\n    proc.start()\\n    proc.join(timeout=10)\\n    assert proc.exitcode == 0, \\\"Child process failed to emit event\\\"\\n\\n    reader = ExtensionEventsService(cache_dir=shared)\\n    events, _ = reader.since(0.0)\\n    assert len(events) == 1\\n    assert events[0].payload[\\\"bundle\\\"] == \\\"from-child\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_extract_text_from_bytes.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b03e2d5558c10fca45f4dfb023f43b0c5cdfc9549fd4fba38b645bfd39045f9e\",\"content\":\"from io import BytesIO\\nfrom unittest.mock import MagicMock, patch\\n\\nimport pytest\\nfrom lfx.base.data.utils import extract_text_from_bytes\\nfrom pypdf import PdfWriter\\n\\n\\ndef _make_blank_pdf(num_pages: int = 1) -> bytes:\\n    \\\"\\\"\\\"Create a valid PDF with blank pages.\\\"\\\"\\\"\\n    writer = PdfWriter()\\n    for _ in range(num_pages):\\n        writer.add_blank_page(width=612, height=792)\\n    buf = BytesIO()\\n    writer.write(buf)\\n    return buf.getvalue()\\n\\n\\ndef _mock_pdf_reader(pages_text: list[str]):\\n    \\\"\\\"\\\"Create a mock PdfReader that returns pages with given text.\\\"\\\"\\\"\\n    mock_reader = MagicMock()\\n    mock_pages = []\\n    for text in pages_text:\\n        page = MagicMock()\\n        page.extract_text.return_value = text\\n        mock_pages.append(page)\\n    mock_reader.pages = mock_pages\\n    mock_reader.__enter__ = MagicMock(return_value=mock_reader)\\n    mock_reader.__exit__ = MagicMock(return_value=False)\\n    return mock_reader\\n\\n\\nclass TestExtractTextFromBytesPDF:\\n    @patch(\\\"lfx.base.data.utils.PdfReader\\\")\\n    def test_should_extract_text_from_valid_pdf(self, mock_reader_cls):\\n        mock_reader_cls.return_value = _mock_pdf_reader([\\\"Hello World\\\"])\\n        result = extract_text_from_bytes(\\\"document.pdf\\\", _make_blank_pdf())\\n        assert \\\"Hello World\\\" in result\\n\\n    @patch(\\\"lfx.base.data.utils.PdfReader\\\")\\n    def test_should_extract_text_from_multi_page_pdf(self, mock_reader_cls):\\n        mock_reader_cls.return_value = _mock_pdf_reader([\\\"Page one content\\\", \\\"Page two content\\\"])\\n        result = extract_text_from_bytes(\\\"multi.pdf\\\", _make_blank_pdf(2))\\n        assert \\\"Page one content\\\" in result\\n        assert \\\"Page two content\\\" in result\\n\\n    @patch(\\\"lfx.base.data.utils.PdfReader\\\")\\n    def test_should_join_pages_with_double_newline(self, mock_reader_cls):\\n        mock_reader_cls.return_value = _mock_pdf_reader([\\\"First\\\", \\\"Second\\\"])\\n        result = extract_text_from_bytes(\\\"test.pdf\\\", _make_blank_pdf(2))\\n        assert result == \\\"First\\\\n\\\\nSecond\\\"\\n\\n    @patch(\\\"lfx.base.data.utils.PdfReader\\\")\\n    def test_should_be_case_insensitive_on_extension(self, mock_reader_cls):\\n        mock_reader_cls.return_value = _mock_pdf_reader([\\\"Test\\\"])\\n        result = extract_text_from_bytes(\\\"DOC.PDF\\\", _make_blank_pdf())\\n        assert \\\"Test\\\" in result\\n\\n    def test_should_raise_value_error_for_corrupted_pdf(self):\\n        with pytest.raises(ValueError, match=\\\"Failed to parse PDF file\\\"):\\n            extract_text_from_bytes(\\\"bad.pdf\\\", b\\\"this is not a pdf\\\")\\n\\n    def test_should_raise_value_error_for_empty_pdf_bytes(self):\\n        with pytest.raises(ValueError, match=\\\"Failed to parse PDF file\\\"):\\n            extract_text_from_bytes(\\\"empty.pdf\\\", b\\\"\\\")\\n\\n    def test_should_handle_pdf_with_blank_pages(self):\\n        result = extract_text_from_bytes(\\\"blank.pdf\\\", _make_blank_pdf())\\n        assert isinstance(result, str)\\n\\n    @patch(\\\"lfx.base.data.utils.PdfReader\\\")\\n    def test_should_handle_page_returning_none(self, mock_reader_cls):\\n        mock_reader_cls.return_value = _mock_pdf_reader([\\\"Text\\\"])\\n        mock_reader_cls.return_value.pages[0].extract_text.return_value = None\\n        mock_reader_cls.return_value.__enter__.return_value = mock_reader_cls.return_value\\n        result = extract_text_from_bytes(\\\"null_page.pdf\\\", _make_blank_pdf())\\n        assert isinstance(result, str)\\n\\n\\nclass TestExtractTextFromBytesDOCX:\\n    def test_should_extract_text_from_valid_docx(self):\\n        from docx import Document\\n\\n        doc = Document()\\n        doc.add_paragraph(\\\"Hello from DOCX\\\")\\n        buf = BytesIO()\\n        doc.save(buf)\\n\\n        result = extract_text_from_bytes(\\\"file.docx\\\", buf.getvalue())\\n        assert \\\"Hello from DOCX\\\" in result\\n\\n    def test_should_extract_multiple_paragraphs(self):\\n        from docx import Document\\n\\n        doc = Document()\\n        doc.add_paragraph(\\\"First paragraph\\\")\\n        doc.add_paragraph(\\\"Second paragraph\\\")\\n        buf = BytesIO()\\n        doc.save(buf)\\n\\n        result = extract_text_from_bytes(\\\"file.docx\\\", buf.getvalue())\\n        assert \\\"First paragraph\\\" in result\\n        assert \\\"Second paragraph\\\" in result\\n        assert \\\"\\\\n\\\\n\\\" in result\\n\\n    def test_should_be_case_insensitive_on_extension(self):\\n        from docx import Document\\n\\n        doc = Document()\\n        doc.add_paragraph(\\\"Case test\\\")\\n        buf = BytesIO()\\n        doc.save(buf)\\n\\n        result = extract_text_from_bytes(\\\"FILE.DOCX\\\", buf.getvalue())\\n        assert \\\"Case test\\\" in result\\n\\n    def test_should_raise_value_error_for_corrupted_docx(self):\\n        with pytest.raises(ValueError, match=\\\"Failed to parse DOCX file\\\"):\\n            extract_text_from_bytes(\\\"bad.docx\\\", b\\\"not a valid docx\\\")\\n\\n    def test_should_raise_value_error_for_empty_docx_bytes(self):\\n        with pytest.raises(ValueError, match=\\\"Failed to parse DOCX file\\\"):\\n            extract_text_from_bytes(\\\"empty.docx\\\", b\\\"\\\")\\n\\n    def test_should_handle_docx_with_no_paragraphs(self):\\n        from docx import Document\\n\\n        doc = Document()\\n        buf = BytesIO()\\n        doc.save(buf)\\n\\n        result = extract_text_from_bytes(\\\"empty_doc.docx\\\", buf.getvalue())\\n        assert isinstance(result, str)\\n\\n\\nclass TestExtractTextFromBytesPlainText:\\n    def test_should_decode_utf8_text(self):\\n        content = b\\\"Hello plain text\\\"\\n        result = extract_text_from_bytes(\\\"readme.txt\\\", content)\\n        assert result == \\\"Hello plain text\\\"\\n\\n    def test_should_handle_non_utf8_gracefully(self):\\n        content = b\\\"\\\\xff\\\\xfe\\\\x00\\\\x01 some text\\\"\\n        result = extract_text_from_bytes(\\\"binary.txt\\\", content)\\n        assert isinstance(result, str)\\n        assert \\\"some text\\\" in result\\n\\n    def test_should_handle_empty_content(self):\\n        result = extract_text_from_bytes(\\\"empty.txt\\\", b\\\"\\\")\\n        assert result == \\\"\\\"\\n\\n    def test_should_handle_csv_as_plain_text(self):\\n        content = b\\\"col1,col2\\\\nval1,val2\\\"\\n        result = extract_text_from_bytes(\\\"data.csv\\\", content)\\n        assert \\\"col1,col2\\\" in result\\n\\n    def test_should_handle_json_as_plain_text(self):\\n        content = b'{\\\"key\\\": \\\"value\\\"}'\\n        result = extract_text_from_bytes(\\\"data.json\\\", content)\\n        assert '\\\"key\\\"' in result\\n\\n    def test_should_handle_unknown_extension_as_plain_text(self):\\n        content = b\\\"some content\\\"\\n        result = extract_text_from_bytes(\\\"file.xyz\\\", content)\\n        assert result == \\\"some content\\\"\\n\\n    def test_should_handle_file_without_extension(self):\\n        content = b\\\"no extension\\\"\\n        result = extract_text_from_bytes(\\\"Makefile\\\", content)\\n        assert result == \\\"no extension\\\"\\n\\n    def test_should_preserve_unicode_characters(self):\\n        content = \\\"caf\u00e9 r\u00e9sum\u00e9 na\u00efve\\\".encode()\\n        result = extract_text_from_bytes(\\\"unicode.txt\\\", content)\\n        assert result == \\\"caf\u00e9 r\u00e9sum\u00e9 na\u00efve\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_frontend_serving.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f54e54a7bbb4d068e6b061a3306d3fabbe42a4118dfd6dbf39764304cc96eaca\",\"content\":\"\\\"\\\"\\\"Tests for serving the built frontend via FastAPI's ``app.frontend()``.\\n\\n``setup_static_files`` serves the build with ``app.frontend()`` instead of a\\nmanual ``StaticFiles`` mount. ``app.frontend()`` returns ``index.html`` for any\\nunmatched GET, so a ``/api`` GET/HEAD reservation plus the app-wide 404 handler\\nkeep the old contract: missing API paths stay JSON 404s, wrong methods stay 405,\\nand non-API deep links (including dotted ones) load the SPA.\\n\\\"\\\"\\\"\\n\\nfrom pathlib import Path\\n\\nimport pytest\\nfrom fastapi.testclient import TestClient\\nfrom langflow.main import setup_app\\n\\n\\n@pytest.fixture\\ndef frontend_client(tmp_path: Path) -> TestClient:\\n    dist = tmp_path / \\\"frontend\\\"\\n    (dist / \\\"assets\\\").mkdir(parents=True)\\n    (dist / \\\"index.html\\\").write_text(\\\"<!doctype html><title>Langflow</title><div id='root'></div>\\\")\\n    (dist / \\\"assets\\\" / \\\"app.js\\\").write_text(\\\"console.log('app')\\\")\\n    app = setup_app(static_files_dir=dist)\\n    return TestClient(app, raise_server_exceptions=False)\\n\\n\\ndef test_serves_spa_index_at_root(frontend_client: TestClient):\\n    response = frontend_client.get(\\\"/\\\")\\n    assert response.status_code == 200\\n    assert response.headers[\\\"content-type\\\"].startswith(\\\"text/html\\\")\\n    assert \\\"id='root'\\\" in response.text\\n\\n\\ndef test_serves_static_asset(frontend_client: TestClient):\\n    response = frontend_client.get(\\\"/assets/app.js\\\")\\n    assert response.status_code == 200\\n    assert response.text == \\\"console.log('app')\\\"\\n\\n\\ndef test_client_route_falls_back_to_index(frontend_client: TestClient):\\n    # Extensionless deep links are served the SPA shell by app.frontend() itself.\\n    response = frontend_client.get(\\\"/flows/some/client/route\\\")\\n    assert response.status_code == 200\\n    assert response.headers[\\\"content-type\\\"].startswith(\\\"text/html\\\")\\n    assert \\\"id='root'\\\" in response.text\\n\\n\\ndef test_dotted_client_route_falls_back_to_index(frontend_client: TestClient):\\n    # A deep link whose last segment has a dot is not a \\\"navigation\\\" request to\\n    # app.frontend(), so the app-wide 404 handler must still return the SPA.\\n    response = frontend_client.get(\\\"/flow/my.flow.v2\\\")\\n    assert response.status_code == 200\\n    assert response.headers[\\\"content-type\\\"].startswith(\\\"text/html\\\")\\n    assert \\\"id='root'\\\" in response.text\\n\\n\\ndef test_unknown_api_path_returns_json_404(frontend_client: TestClient):\\n    # Missing API paths must stay JSON 404s, not the SPA index.html.\\n    response = frontend_client.get(\\\"/api/v1/definitely-not-a-real-route\\\")\\n    assert response.status_code == 404\\n    assert response.headers[\\\"content-type\\\"].startswith(\\\"application/json\\\")\\n    assert response.json() == {\\\"detail\\\": \\\"Not Found\\\"}\\n\\n\\ndef test_wrong_method_on_real_api_route_returns_405(frontend_client: TestClient):\\n    # The /api reservation only claims GET/HEAD, so a wrong method on a real\\n    # endpoint still gets 405, not a 404 swallowed by the catch-all.\\n    response = frontend_client.post(\\\"/api/v1/version\\\")\\n    assert response.status_code == 405\\n    assert response.headers[\\\"content-type\\\"].startswith(\\\"application/json\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_get_api_key.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6acd226c38e80f6709e3e46eb4c3b3bd724aeface998303e392932b8fc73fc73\",\"content\":\"import asyncio\\nfrom uuid import uuid4\\n\\nimport langflow.services.database.models.api_key.crud as crud_module\\nimport pytest\\nfrom cryptography.fernet import InvalidToken\\n\\n\\nclass DummyResult:\\n    def __init__(self, items):\\n        self._items = items\\n\\n    def all(self):\\n        return self._items\\n\\n\\nclass MockSession:\\n    def __init__(self, items):\\n        self._items = items\\n\\n    async def exec(self, _query=None):\\n        # emulate SQLModel AsyncSession.exec returning a result with .all()\\n        await asyncio.sleep(0)  # ensure it's truly async\\n        return DummyResult(self._items)\\n\\n\\nclass MockApiKeyObj:\\n    def __init__(self, data: dict):\\n        self._data = data\\n\\n    def model_dump(self):\\n        return dict(self._data)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_get_api_keys_decrypts_and_falls_back(monkeypatch):\\n    user_id = uuid4()\\n\\n    items = [\\n        MockApiKeyObj({\\\"id\\\": \\\"1\\\", \\\"api_key\\\": \\\"enc-1\\\", \\\"name\\\": \\\"k1\\\", \\\"user_id\\\": str(user_id)}),\\n        MockApiKeyObj({\\\"id\\\": \\\"2\\\", \\\"api_key\\\": \\\"bad-enc\\\", \\\"name\\\": \\\"k2\\\", \\\"user_id\\\": str(user_id)}),\\n        MockApiKeyObj({\\\"id\\\": \\\"3\\\", \\\"api_key\\\": None, \\\"name\\\": \\\"k3\\\", \\\"user_id\\\": str(user_id)}),\\n    ]\\n\\n    session = MockSession(items)\\n\\n    # Patch decrypt_api_key to:\\n    # - return 'sk-decrypted' for 'enc-1'\\n    # - raise InvalidToken for 'bad-enc' to trigger fallback\\n    def fake_decrypt(val, *, settings_service=None):  # noqa: ARG001\\n        if val == \\\"enc-1\\\":\\n            return \\\"sk-decrypted\\\"\\n        if val == \\\"bad-enc\\\":\\n            raise InvalidToken\\n        return val\\n\\n    monkeypatch.setattr(crud_module.auth_utils, \\\"decrypt_api_key\\\", fake_decrypt)\\n\\n    # Patch ApiKeyRead.model_validate to just return the provided dict for easy assertions\\n    monkeypatch.setattr(crud_module.ApiKeyRead, \\\"model_validate\\\", staticmethod(lambda data: data))\\n\\n    result = await crud_module.get_api_keys(session, user_id)\\n\\n    # three entries returned\\n    assert isinstance(result, list)\\n    assert len(result) == 3\\n\\n    # first decrypted\\n    assert result[0][\\\"api_key\\\"] == \\\"sk-decrypted\\\"\\n    # second fell back to stored value 'bad-enc'\\n    assert result[1][\\\"api_key\\\"] == \\\"bad-enc\\\"\\n    # third remains None\\n    assert result[2][\\\"api_key\\\"] is None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_helper_components.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9938e36b3d7b89e10f986edaadd4ca139016df248724d32bbd0225946dcb11d7\",\"content\":\"from pathlib import Path\\n\\nfrom lfx.components import helpers, processing\\nfrom lfx.custom.utils import build_custom_component_template\\nfrom lfx.schema import Data\\nfrom lfx.schema.message import Message\\n\\n# def test_update_data_component():\\n#     # Arrange\\n#     update_data_component = helpers.UpdateDataComponent()\\n\\n#     # Act\\n#     new_data = {\\\"new_key\\\": \\\"new_value\\\"}\\n#     existing_data = Data(data={\\\"existing_key\\\": \\\"existing_value\\\"})\\n#     result = update_data_component.build(existing_data, new_data)\\n#     assert result.data == {\\\"existing_key\\\": \\\"existing_value\\\", \\\"new_key\\\": \\\"new_value\\\"}\\n#     assert result.existing_key == \\\"existing_value\\\"\\n#     assert result.new_key == \\\"new_value\\\"\\n\\n\\n# def test_document_to_data_component():\\n#     # Arrange\\n#     document_to_data_component = helpers.DocumentsToDataComponent()\\n\\n#     # Act\\n#     # Replace with your actual test data\\n#     document = Document(page_content=\\\"key: value\\\", metadata={\\\"url\\\": \\\"https://example.com\\\"})\\n#     result = document_to_data_component.build(document)\\n\\n#     # Assert\\n#     # Replace with your actual expected result\\n#     assert result == [Data(data={\\\"text\\\": \\\"key: value\\\", \\\"url\\\": \\\"https://example.com\\\"})]\\n\\n\\ndef test_uuid_generator_component():\\n    # Arrange\\n    uuid_generator_component = helpers.IDGeneratorComponent()\\n    uuid_generator_component._code = Path(helpers.id_generator.__file__).read_text(encoding=\\\"utf-8\\\")\\n\\n    frontend_node, _ = build_custom_component_template(uuid_generator_component)\\n\\n    # Act\\n    build_config = frontend_node.get(\\\"template\\\")\\n    field_name = \\\"unique_id\\\"\\n    build_config = uuid_generator_component.update_build_config(build_config, None, field_name)\\n    result = uuid_generator_component.generate_id()\\n\\n    # Assert\\n    # UUID should be a string of length 36\\n    assert isinstance(result, Message)\\n    assert len(result.text) == 36\\n\\n\\ndef test_data_as_text_component():\\n    # Arrange\\n    data_as_text_component = processing.ParseDataComponent()\\n\\n    # Act\\n    # Replace with your actual test data\\n    data = [Data(data={\\\"key\\\": \\\"value\\\", \\\"bacon\\\": \\\"eggs\\\"})]\\n    template = \\\"Data:{data} -- Bacon:{bacon}\\\"\\n    data_as_text_component.set_attributes({\\\"data\\\": data, \\\"template\\\": template})\\n    result = data_as_text_component.parse_data()\\n\\n    # Assert\\n    # Replace with your actual expected result\\n    assert result.text == \\\"Data:{'key': 'value', 'bacon': 'eggs'} -- Bacon:eggs\\\"\\n\\n\\n# def test_text_to_data_component():\\n#     # Arrange\\n#     text_to_data_component = helpers.CreateDataComponent()\\n\\n#     # Act\\n#     # Replace with your actual test data\\n#     dict_with_text = {\\\"field_1\\\": {\\\"key\\\": \\\"value\\\"}}\\n#     result = text_to_data_component.build(number_of_fields=1, **dict_with_text)\\n\\n#     # Assert\\n#     # Replace with your actual expected result\\n#     assert result == Data(data={\\\"key\\\": \\\"value\\\"})\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_i18n_note_translation.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0fc0a7b80bc406a0b73aa9d4758963c5818199d418f2b019d3963d6037368005\",\"content\":\"\\\"\\\"\\\"Tests for note node translation in i18n utilities and API endpoints.\\\"\\\"\\\"\\n\\nimport uuid\\n\\nfrom fastapi import status\\nfrom httpx import AsyncClient\\nfrom langflow.utils.i18n import _safe_flow_key, translate_flow_notes\\n\\n# ---------------------------------------------------------------------------\\n# Helpers\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _make_note_node(node_id: str, description: str, i18n_key: str | None = None) -> dict:\\n    node_data: dict = {\\\"description\\\": description}\\n    if i18n_key is not None:\\n        node_data[\\\"i18n_key\\\"] = i18n_key\\n    return {\\n        \\\"id\\\": node_id,\\n        \\\"type\\\": \\\"noteNode\\\",\\n        \\\"data\\\": {\\\"node\\\": node_data},\\n    }\\n\\n\\ndef _make_generic_node(node_id: str) -> dict:\\n    return {\\n        \\\"id\\\": node_id,\\n        \\\"type\\\": \\\"genericNode\\\",\\n        \\\"data\\\": {\\\"node\\\": {\\\"display_name\\\": \\\"Chat Input\\\"}},\\n    }\\n\\n\\n# ---------------------------------------------------------------------------\\n# Unit tests \u2014 translate_flow_notes()\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestTranslateFlowNotes:\\n    def test_translates_description_when_key_is_baked_in(self, monkeypatch):\\n        \\\"\\\"\\\"A noteNode with i18n_key baked in gets its description translated.\\\"\\\"\\\"\\n        monkeypatch.setattr(\\n            \\\"langflow.utils.i18n._translations\\\",\\n            {\\n                \\\"en\\\": {\\\"template_notes.simple_agent.0\\\": \\\"Hello\\\"},\\n                \\\"fr\\\": {\\\"template_notes.simple_agent.0\\\": \\\"Bonjour\\\"},\\n            },\\n        )\\n        nodes = [_make_note_node(\\\"n1\\\", \\\"Hello\\\", i18n_key=\\\"template_notes.simple_agent.0\\\")]\\n        result = translate_flow_notes(nodes, \\\"fr\\\")\\n        assert result[0][\\\"data\\\"][\\\"node\\\"][\\\"description\\\"] == \\\"Bonjour\\\"\\n\\n    def test_falls_back_to_english_when_locale_missing(self, monkeypatch):\\n        monkeypatch.setattr(\\n            \\\"langflow.utils.i18n._translations\\\",\\n            {\\\"en\\\": {\\\"template_notes.simple_agent.0\\\": \\\"Hello\\\"}},\\n        )\\n        nodes = [_make_note_node(\\\"n1\\\", \\\"Hello\\\", i18n_key=\\\"template_notes.simple_agent.0\\\")]\\n        result = translate_flow_notes(nodes, \\\"ja\\\")\\n        assert result[0][\\\"data\\\"][\\\"node\\\"][\\\"description\\\"] == \\\"Hello\\\"\\n\\n    def test_falls_back_to_original_when_key_not_in_translations(self, monkeypatch):\\n        monkeypatch.setattr(\\\"langflow.utils.i18n._translations\\\", {\\\"en\\\": {}, \\\"fr\\\": {}})\\n        nodes = [_make_note_node(\\\"n1\\\", \\\"Original text\\\", i18n_key=\\\"template_notes.unknown_flow.0\\\")]\\n        result = translate_flow_notes(nodes, \\\"fr\\\")\\n        assert result[0][\\\"data\\\"][\\\"node\\\"][\\\"description\\\"] == \\\"Original text\\\"\\n\\n    def test_node_without_i18n_key_is_passed_through_unchanged(self, monkeypatch):\\n        \\\"\\\"\\\"NoteNodes without i18n_key (e.g. user-created) are left untouched.\\\"\\\"\\\"\\n        monkeypatch.setattr(\\\"langflow.utils.i18n._translations\\\", {\\\"fr\\\": {}})\\n        node = _make_note_node(\\\"n1\\\", \\\"User note\\\")  # no i18n_key\\n        result = translate_flow_notes([node], \\\"fr\\\")\\n        assert result[0] is node  # same object, not deep-copied\\n\\n    def test_non_note_nodes_are_passed_through_unchanged(self, monkeypatch):\\n        monkeypatch.setattr(\\\"langflow.utils.i18n._translations\\\", {\\\"en\\\": {}})\\n        generic = _make_generic_node(\\\"g1\\\")\\n        result = translate_flow_notes([generic], \\\"fr\\\")\\n        assert result[0] is generic  # same object, untouched\\n\\n    def test_does_not_mutate_input_nodes(self, monkeypatch):\\n        monkeypatch.setattr(\\n            \\\"langflow.utils.i18n._translations\\\",\\n            {\\\"en\\\": {\\\"template_notes.simple_agent.0\\\": \\\"Hello\\\"}},\\n        )\\n        node = _make_note_node(\\\"n1\\\", \\\"Hello\\\", i18n_key=\\\"template_notes.simple_agent.0\\\")\\n        original_description = node[\\\"data\\\"][\\\"node\\\"][\\\"description\\\"]\\n        translate_flow_notes([node], \\\"en\\\")\\n        assert node[\\\"data\\\"][\\\"node\\\"][\\\"description\\\"] == original_description\\n\\n    def test_translates_multiple_note_nodes_independently(self, monkeypatch):\\n        monkeypatch.setattr(\\n            \\\"langflow.utils.i18n._translations\\\",\\n            {\\n                \\\"en\\\": {\\n                    \\\"template_notes.simple_agent.0\\\": \\\"First\\\",\\n                    \\\"template_notes.simple_agent.1\\\": \\\"Second\\\",\\n                },\\n                \\\"fr\\\": {\\n                    \\\"template_notes.simple_agent.0\\\": \\\"Premier\\\",\\n                    \\\"template_notes.simple_agent.1\\\": \\\"Deuxi\u00e8me\\\",\\n                },\\n            },\\n        )\\n        nodes = [\\n            _make_note_node(\\\"n0\\\", \\\"First\\\", i18n_key=\\\"template_notes.simple_agent.0\\\"),\\n            _make_note_node(\\\"n1\\\", \\\"Second\\\", i18n_key=\\\"template_notes.simple_agent.1\\\"),\\n        ]\\n        result = translate_flow_notes(nodes, \\\"fr\\\")\\n        assert result[0][\\\"data\\\"][\\\"node\\\"][\\\"description\\\"] == \\\"Premier\\\"\\n        assert result[1][\\\"data\\\"][\\\"node\\\"][\\\"description\\\"] == \\\"Deuxi\u00e8me\\\"\\n\\n    def test_does_not_stamp_i18n_key_onto_nodes(self, monkeypatch):\\n        \\\"\\\"\\\"translate_flow_notes must never write i18n_key \u2014 that's the bake script's job.\\\"\\\"\\\"\\n        monkeypatch.setattr(\\n            \\\"langflow.utils.i18n._translations\\\",\\n            {\\\"en\\\": {\\\"template_notes.simple_agent.0\\\": \\\"Hello\\\"}},\\n        )\\n        node = _make_note_node(\\\"n1\\\", \\\"Hello\\\")  # no i18n_key\\n        result = translate_flow_notes([node], \\\"en\\\")\\n        assert \\\"i18n_key\\\" not in result[0][\\\"data\\\"][\\\"node\\\"]\\n\\n\\n# ---------------------------------------------------------------------------\\n# Unit tests \u2014 _safe_flow_key()\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestSafeFlowKey:\\n    def test_lowercases_and_replaces_spaces(self):\\n        assert _safe_flow_key(\\\"Simple Agent\\\") == \\\"simple_agent\\\"\\n\\n    def test_parentheses_in_name_become_underscores(self):\\n        # Parentheses are replaced with underscores, so the dedup number is\\n        # preserved in the key. Callers must pass the original (deduped) name\\n        # to get a stable key.\\n        assert _safe_flow_key(\\\"Simple Agent (2)\\\") == \\\"simple_agent_2\\\"\\n\\n    def test_handles_special_characters(self):\\n        assert _safe_flow_key(\\\"My-Flow! v2\\\") == \\\"my_flow_v2\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# Integration tests \u2014 GET /flows/{id}/note_translations\\n# ---------------------------------------------------------------------------\\n\\n\\nasync def test_note_translations_returns_empty_for_user_flow(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"A flow without i18n_key on its noteNodes returns an empty map.\\\"\\\"\\\"\\n    flow_payload = {\\n        \\\"name\\\": \\\"User Flow\\\",\\n        \\\"description\\\": \\\"\\\",\\n        \\\"data\\\": {\\n            \\\"nodes\\\": [_make_note_node(\\\"note-abc\\\", \\\"My note\\\")],\\n            \\\"edges\\\": [],\\n        },\\n        \\\"is_component\\\": False,\\n    }\\n    create_resp = await client.post(\\\"api/v1/flows/\\\", json=flow_payload, headers=logged_in_headers)\\n    assert create_resp.status_code == status.HTTP_201_CREATED\\n    flow_id = create_resp.json()[\\\"id\\\"]\\n\\n    resp = await client.get(f\\\"api/v1/flows/{flow_id}/note_translations\\\", headers=logged_in_headers)\\n    assert resp.status_code == status.HTTP_200_OK\\n    assert resp.json() == {}\\n\\n\\nasync def test_note_translations_returns_translated_text_for_baked_node(\\n    client: AsyncClient, logged_in_headers, monkeypatch\\n):\\n    \\\"\\\"\\\"A noteNode with a baked i18n_key returns translated text for the locale.\\\"\\\"\\\"\\n    import langflow.utils.i18n as i18n_mod\\n\\n    monkeypatch.setattr(\\n        i18n_mod,\\n        \\\"_translations\\\",\\n        {\\n            \\\"en\\\": {\\\"template_notes.simple_agent.0\\\": \\\"Hello\\\"},\\n            \\\"fr\\\": {\\\"template_notes.simple_agent.0\\\": \\\"Bonjour\\\"},\\n        },\\n    )\\n\\n    note_node = _make_note_node(\\\"note-xyz\\\", \\\"Hello\\\", i18n_key=\\\"template_notes.simple_agent.0\\\")\\n\\n    flow_payload = {\\n        \\\"name\\\": \\\"Baked Flow\\\",\\n        \\\"description\\\": \\\"\\\",\\n        \\\"data\\\": {\\\"nodes\\\": [note_node], \\\"edges\\\": []},\\n        \\\"is_component\\\": False,\\n    }\\n    create_resp = await client.post(\\\"api/v1/flows/\\\", json=flow_payload, headers=logged_in_headers)\\n    assert create_resp.status_code == status.HTTP_201_CREATED\\n    flow_id = create_resp.json()[\\\"id\\\"]\\n\\n    resp = await client.get(\\n        f\\\"api/v1/flows/{flow_id}/note_translations\\\",\\n        headers={**logged_in_headers, \\\"Accept-Language\\\": \\\"fr\\\"},\\n    )\\n    assert resp.status_code == status.HTTP_200_OK\\n    translations = resp.json()\\n    assert \\\"Bonjour\\\" in translations.values()\\n\\n\\nasync def test_note_translations_returns_404_for_missing_flow(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"A non-existent (or inaccessible) flow returns 404, consistent with GET /flows/{id}.\\\"\\\"\\\"\\n    fake_id = str(uuid.uuid4())\\n    resp = await client.get(f\\\"api/v1/flows/{fake_id}/note_translations\\\", headers=logged_in_headers)\\n    assert resp.status_code == status.HTTP_404_NOT_FOUND\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_initial_setup.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"913a983e1905b6b293ca2ba10ececbbcbcdb6a0508dab1dc08e0eda9afb85f29\",\"content\":\"import asyncio\\nimport os\\nimport shutil\\nimport tempfile\\nimport uuid\\nfrom copy import deepcopy\\nfrom datetime import datetime\\nfrom pathlib import Path as SyncPath\\nfrom unittest.mock import AsyncMock, MagicMock, patch\\nfrom urllib.parse import urlparse\\n\\nimport orjson\\nimport pytest\\nfrom anyio import Path\\nfrom httpx import AsyncClient\\nfrom langflow.initial_setup.constants import STARTER_FOLDER_NAME\\nfrom langflow.initial_setup.setup import (\\n    copy_profile_pictures,\\n    detect_github_url,\\n    filter_starter_projects_by_available_components,\\n    get_project_data,\\n    load_bundles_from_urls,\\n    load_starter_projects,\\n    update_projects_components_with_latest_component_versions,\\n)\\nfrom langflow.interface.components import get_and_cache_all_types_dict\\nfrom langflow.services.auth.utils import create_super_user\\nfrom langflow.services.database.models import Flow\\nfrom langflow.services.database.models.folder.model import Folder\\nfrom langflow.services.deps import get_settings_service, session_scope\\nfrom lfx.extension.bundle_registry import BundleRecord, BundleRegistry\\nfrom sqlalchemy.orm import selectinload\\nfrom sqlmodel import select\\n\\n\\nasync def test_load_starter_projects():\\n    projects = await load_starter_projects()\\n    assert isinstance(projects, list)\\n    assert all(isinstance(project[1], dict) for project in projects)\\n    assert all(isinstance(project[0], Path) for project in projects)\\n\\n\\ndef test_filter_starter_projects_by_available_components():\\n    available_components = {\\n        \\\"input_output\\\": {\\n            \\\"ChatInput\\\": {\\n                \\\"display_name\\\": \\\"Chat Input\\\",\\n                \\\"template\\\": {\\\"_type\\\": \\\"ChatInput\\\"},\\n            }\\n        }\\n    }\\n    valid_project = {\\n        \\\"name\\\": \\\"Core starter\\\",\\n        \\\"data\\\": {\\n            \\\"nodes\\\": [\\n                {\\n                    \\\"data\\\": {\\n                        \\\"type\\\": \\\"ChatInput\\\",\\n                        \\\"node\\\": {\\\"metadata\\\": {\\\"module\\\": \\\"lfx.components.input_output.chat\\\"}, \\\"template\\\": {}},\\n                    }\\n                },\\n                {\\\"data\\\": {\\\"type\\\": \\\"note\\\", \\\"node\\\": {\\\"metadata\\\": {}, \\\"template\\\": {}}}},\\n                {\\n                    \\\"data\\\": {\\n                        \\\"type\\\": \\\"EmbeddedCustomComponent\\\",\\n                        \\\"node\\\": {\\\"metadata\\\": {}, \\\"template\\\": {\\\"code\\\": {\\\"value\\\": \\\"class Embedded: pass\\\"}}},\\n                    }\\n                },\\n            ]\\n        },\\n    }\\n    unavailable_project = {\\n        \\\"name\\\": \\\"Bundle starter\\\",\\n        \\\"data\\\": {\\n            \\\"nodes\\\": [\\n                {\\n                    \\\"data\\\": {\\n                        \\\"type\\\": \\\"OpenAIModelComponent\\\",\\n                        \\\"node\\\": {\\n                            \\\"metadata\\\": {\\\"module\\\": \\\"lfx.components.openai.openai_chat_model\\\"},\\n                            \\\"template\\\": {\\\"code\\\": {\\\"value\\\": \\\"class OpenAIModelComponent: pass\\\"}},\\n                        },\\n                    }\\n                }\\n            ]\\n        },\\n    }\\n    projects = [\\n        (Path(\\\"core.json\\\"), valid_project),\\n        (Path(\\\"bundle.json\\\"), unavailable_project),\\n    ]\\n\\n    filtered = filter_starter_projects_by_available_components(projects, available_components)\\n\\n    assert filtered == [(Path(\\\"core.json\\\"), valid_project)]\\n\\n\\nasync def test_core_catalog_filters_starter_projects_from_other_packages():\\n    repo_root = SyncPath(__file__).resolve().parents[4]\\n    index_path = repo_root / \\\"src\\\" / \\\"lfx\\\" / \\\"src\\\" / \\\"lfx\\\" / \\\"_assets\\\" / \\\"component_index.json\\\"\\n    core_components = dict(orjson.loads(index_path.read_bytes())[\\\"entries\\\"])\\n    with patch(\\\"langflow.initial_setup.setup.get_default_registry\\\", return_value=BundleRegistry()):\\n        projects = await load_starter_projects()\\n\\n    filtered = filter_starter_projects_by_available_components(projects, core_components)\\n\\n    filtered_names = {project[\\\"name\\\"] for _, project in filtered}\\n    removed_names = {project[\\\"name\\\"] for _, project in projects} - filtered_names\\n    assert removed_names == {\\n        \\\"Hybrid Search RAG\\\",\\n        \\\"Research Translation Loop\\\",\\n    }\\n\\n\\nasync def test_load_starter_projects_from_manifestless_bundle(tmp_path):\\n    bundle_root = tmp_path / \\\"youtube\\\"\\n    projects_dir = bundle_root / \\\"starter_projects\\\"\\n    projects_dir.mkdir(parents=True)\\n    project = {\\\"name\\\": \\\"Bundle starter\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}\\n    (projects_dir / \\\"Bundle starter.json\\\").write_bytes(orjson.dumps(project))\\n\\n    manifest_bundle_root = tmp_path / \\\"manifest_bundle\\\"\\n    manifest_projects_dir = manifest_bundle_root / \\\"starter_projects\\\"\\n    manifest_projects_dir.mkdir(parents=True)\\n    deferred_project = {\\\"name\\\": \\\"Deferred starter\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}\\n    (manifest_projects_dir / \\\"Deferred starter.json\\\").write_bytes(orjson.dumps(deferred_project))\\n\\n    registry = BundleRegistry()\\n    registry.install_bundle(\\n        BundleRecord(\\n            bundle=\\\"youtube\\\",\\n            extension_id=\\\"lfx-bundles\\\",\\n            extension_version=\\\"1.1.1\\\",\\n            slot=\\\"official\\\",\\n            source_path=bundle_root,\\n            manifestless=True,\\n        )\\n    )\\n    registry.install_bundle(\\n        BundleRecord(\\n            bundle=\\\"manifest_bundle\\\",\\n            extension_id=\\\"manifest-bundle\\\",\\n            extension_version=\\\"1.0.0\\\",\\n            slot=\\\"official\\\",\\n            source_path=manifest_bundle_root,\\n        )\\n    )\\n\\n    with patch(\\\"langflow.initial_setup.setup.get_default_registry\\\", return_value=registry):\\n        projects = await load_starter_projects()\\n\\n    assert (Path(projects_dir / \\\"Bundle starter.json\\\"), project) in projects\\n    assert all(project_data != deferred_project for _, project_data in projects)\\n\\n\\nasync def test_get_project_data():\\n    projects = await load_starter_projects()\\n    for _, project in projects:\\n        (\\n            project_name,\\n            project_description,\\n            project_is_component,\\n            updated_at_datetime,\\n            project_data,\\n            project_icon,\\n            project_icon_bg_color,\\n            project_gradient,\\n            project_tags,\\n        ) = get_project_data(project)\\n        assert isinstance(project_gradient, str) or project_gradient is None\\n        assert isinstance(project_tags, list), f\\\"Project {project_name} has no tags\\\"\\n        assert isinstance(project_name, str), f\\\"Project {project_name} has no name\\\"\\n        assert isinstance(project_description, str), f\\\"Project {project_name} has no description\\\"\\n        assert isinstance(project_is_component, bool), f\\\"Project {project_name} has no is_component\\\"\\n        assert isinstance(updated_at_datetime, datetime), f\\\"Project {project_name} has no updated_at_datetime\\\"\\n        assert isinstance(project_data, dict), f\\\"Project {project_name} has no data\\\"\\n        assert isinstance(project_icon, str) or project_icon is None, f\\\"Project {project_name} has no icon\\\"\\n        assert isinstance(project_icon_bg_color, str) or project_icon_bg_color is None, (\\n            f\\\"Project {project_name} has no icon_bg_color\\\"\\n        )\\n\\n\\nasync def test_should_not_leak_caio_contexts_when_loading_starter_projects():\\n    \\\"\\\"\\\"Test that load_starter_projects does not leak caio async I/O contexts.\\n\\n    Bug: On Linux CI, aiofile's async_open creates caio.AsyncioContext objects\\n    keyed by event loop in a global dict (DEFAULT_CONTEXT_STORE) that are never\\n    cleaned up. With pytest-asyncio creating a new event loop per test function,\\n    these contexts accumulate until the OS limit (aio-max-nr) is exhausted,\\n    causing SystemError: (11, 'Resource temporarily unavailable') (EAGAIN).\\n\\n    This test verifies that load_starter_projects does not increase the number\\n    of leaked caio contexts after being called.\\n    \\\"\\\"\\\"\\n    try:\\n        from aiofile.aio import DEFAULT_CONTEXT_STORE\\n    except ImportError:\\n        pytest.skip(\\\"aiofile not installed\\\")\\n\\n    contexts_before = len(DEFAULT_CONTEXT_STORE)\\n    await load_starter_projects()\\n    contexts_after = len(DEFAULT_CONTEXT_STORE)\\n\\n    assert contexts_after == contexts_before, (\\n        f\\\"load_starter_projects leaked {contexts_after - contexts_before} caio context(s). \\\"\\n        f\\\"This causes SystemError(11, 'Resource temporarily unavailable') on Linux CI \\\"\\n        f\\\"when many tests accumulate leaked contexts. \\\"\\n        f\\\"Use anyio.Path.read_text() instead of aiofile.async_open().\\\"\\n    )\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_create_or_update_starter_projects():\\n    async with session_scope() as session:\\n        projects = await load_starter_projects()\\n        all_types_dict = await get_and_cache_all_types_dict(get_settings_service())\\n        expected_project_names = {\\n            project[\\\"name\\\"] for _, project in filter_starter_projects_by_available_components(projects, all_types_dict)\\n        }\\n\\n        stmt = select(Folder).options(selectinload(Folder.flows)).where(Folder.name == STARTER_FOLDER_NAME)\\n        folder = (await session.exec(stmt)).first()\\n        assert folder is not None\\n        db_project_names = {flow.name for flow in folder.flows}\\n\\n        assert db_project_names == expected_project_names\\n\\n\\n# Some starter projects require integration\\n# async def test_starter_projects_can_run_successfully(client):\\n#     with session_scope() as session:\\n#         # Run the function to create or update projects\\n#         create_or_update_starter_projects()\\n\\n#         # Get the number of projects returned by load_starter_projects\\n#         num_projects = len(load_starter_projects())\\n\\n#         # Get the number of projects in the database\\n#         num_db_projects = session.exec(select(func.count(Flow.id)).where(Flow.folder == STARTER_FOLDER_NAME)).one()\\n\\n#         # Check that the number of projects in the database is the same as the number of projects returned by\\n#         # load_starter_projects\\n#         assert num_db_projects == num_projects\\n\\n#         # Get all the starter projects\\n#         projects = session.exec(select(Flow).where(Flow.folder == STARTER_FOLDER_NAME)).all()\\n#         graphs: list[tuple[str, Graph]] = []\\n#         for project in projects:\\n#             # Add tweaks to make file_path work\\n#             tweaks = {\\\"path\\\": __file__}\\n#             graph_data = process_tweaks(project.data, tweaks)\\n#             graph_object = Graph.from_payload(graph_data, flow_id=project.id)\\n#             graphs.append((project.name, graph_object))\\n#         assert len(graphs) == len(projects)\\n#     for name, graph in graphs:\\n#         outputs = await graph.arun(\\n#             inputs={},\\n#             outputs=[],\\n#             session_id=\\\"test\\\",\\n#         )\\n#         assert all(isinstance(output, RunOutputs) for output in outputs), f\\\"Project {name} error: {outputs}\\\"\\n#         delete_messages(session_id=\\\"test\\\")\\n\\n\\ndef find_component_by_name(components, name):\\n    for children in components.values():\\n        if name in children:\\n            return children[name]\\n    msg = f\\\"Component {name} not found in components\\\"\\n    raise ValueError(msg)\\n\\n\\ndef set_value(component, input_name, value):\\n    component[\\\"template\\\"][input_name][\\\"value\\\"] = value\\n\\n\\ndef component_to_node(node_id, node_type, component):\\n    return {\\\"id\\\": node_type + node_id, \\\"data\\\": {\\\"node\\\": component, \\\"type\\\": node_type, \\\"id\\\": node_id}}\\n\\n\\ndef add_edge(source, target, from_output, to_input):\\n    return {\\n        \\\"source\\\": source,\\n        \\\"target\\\": target,\\n        \\\"data\\\": {\\n            \\\"sourceHandle\\\": {\\\"dataType\\\": \\\"ChatInput\\\", \\\"id\\\": source, \\\"name\\\": from_output, \\\"output_types\\\": [\\\"Message\\\"]},\\n            \\\"targetHandle\\\": {\\\"fieldName\\\": to_input, \\\"id\\\": target, \\\"inputTypes\\\": [\\\"Message\\\"], \\\"type\\\": \\\"str\\\"},\\n        },\\n    }\\n\\n\\nasync def test_refresh_starter_projects():\\n    all_types = await get_and_cache_all_types_dict(get_settings_service())\\n    copy_all_types = deepcopy(all_types)\\n\\n    chat_input = find_component_by_name(copy_all_types, \\\"ChatInput\\\")\\n    chat_output = find_component_by_name(copy_all_types, \\\"ChatOutput\\\")\\n    chat_output[\\\"template\\\"][\\\"code\\\"][\\\"value\\\"] = \\\"changed !\\\"\\n    del chat_output[\\\"template\\\"][\\\"should_store_message\\\"]\\n    graph_data = {\\n        \\\"nodes\\\": [\\n            component_to_node(\\\"chat-input-1\\\", \\\"ChatInput\\\", chat_input),\\n            component_to_node(\\\"chat-output-1\\\", \\\"ChatOutput\\\", chat_output),\\n        ],\\n        \\\"edges\\\": [add_edge(\\\"ChatInput\\\" + \\\"chat-input-1\\\", \\\"ChatOutput\\\" + \\\"chat-output-1\\\", \\\"message\\\", \\\"input_value\\\")],\\n    }\\n\\n    new_change = update_projects_components_with_latest_component_versions(graph_data, all_types)\\n    assert graph_data[\\\"nodes\\\"][1][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"code\\\"][\\\"value\\\"] == \\\"changed !\\\"\\n    assert new_change[\\\"nodes\\\"][1][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"code\\\"][\\\"value\\\"] != \\\"changed !\\\"\\n\\n    assert \\\"should_store_message\\\" not in graph_data[\\\"nodes\\\"][1][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"]\\n    assert \\\"should_store_message\\\" in new_change[\\\"nodes\\\"][1][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"]\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"url\\\", \\\"expected\\\"),\\n    [\\n        (\\n            \\\"https://github.com/langflow-ai/langflow-bundles\\\",\\n            \\\"https://github.com/langflow-ai/langflow-bundles/archive/refs/heads/main.zip\\\",\\n        ),\\n        (\\n            \\\"https://github.com/langflow-ai/langflow-bundles/\\\",\\n            \\\"https://github.com/langflow-ai/langflow-bundles/archive/refs/heads/main.zip\\\",\\n        ),\\n        (\\n            \\\"https://github.com/langflow-ai/langflow-bundles.git\\\",\\n            \\\"https://github.com/langflow-ai/langflow-bundles/archive/refs/heads/main.zip\\\",\\n        ),\\n        (\\n            \\\"https://github.com/langflow-ai/langflow-bundles/tree/some.branch-0_1\\\",\\n            \\\"https://github.com/langflow-ai/langflow-bundles/archive/refs/heads/some.branch-0_1.zip\\\",\\n        ),\\n        (\\n            \\\"https://github.com/langflow-ai/langflow-bundles/tree/some/branch\\\",\\n            \\\"https://github.com/langflow-ai/langflow-bundles/archive/refs/heads/some/branch.zip\\\",\\n        ),\\n        (\\n            \\\"https://github.com/langflow-ai/langflow-bundles/tree/some/branch/\\\",\\n            \\\"https://github.com/langflow-ai/langflow-bundles/archive/refs/heads/some/branch.zip\\\",\\n        ),\\n        (\\n            \\\"https://github.com/langflow-ai/langflow-bundles/releases/tag/v1.0.0-0_1\\\",\\n            \\\"https://github.com/langflow-ai/langflow-bundles/archive/refs/tags/v1.0.0-0_1.zip\\\",\\n        ),\\n        (\\n            \\\"https://github.com/langflow-ai/langflow-bundles/releases/tag/foo/v1.0.0\\\",\\n            \\\"https://github.com/langflow-ai/langflow-bundles/archive/refs/tags/foo/v1.0.0.zip\\\",\\n        ),\\n        (\\n            \\\"https://github.com/langflow-ai/langflow-bundles/releases/tag/foo/v1.0.0/\\\",\\n            \\\"https://github.com/langflow-ai/langflow-bundles/archive/refs/tags/foo/v1.0.0.zip\\\",\\n        ),\\n        (\\n            \\\"https://github.com/langflow-ai/langflow-bundles/commit/68428ce16729a385fe1bcc0f1ec91fd5f5f420b9\\\",\\n            \\\"https://github.com/langflow-ai/langflow-bundles/archive/68428ce16729a385fe1bcc0f1ec91fd5f5f420b9.zip\\\",\\n        ),\\n        (\\n            \\\"https://github.com/langflow-ai/langflow-bundles/commit/68428ce16729a385fe1bcc0f1ec91fd5f5f420b9/\\\",\\n            \\\"https://github.com/langflow-ai/langflow-bundles/archive/68428ce16729a385fe1bcc0f1ec91fd5f5f420b9.zip\\\",\\n        ),\\n        (\\\"https://example.com/myzip.zip\\\", \\\"https://example.com/myzip.zip\\\"),\\n    ],\\n)\\nasync def test_detect_github_url(url, expected):\\n    # Mock the GitHub API response for the default branch case\\n    mock_response = MagicMock()\\n    mock_response.json.return_value = {\\\"default_branch\\\": \\\"main\\\"}\\n\\n    with patch(\\\"httpx.AsyncClient.get\\\", return_value=mock_response) as mock_get:\\n        result = await detect_github_url(url)\\n        assert result == expected\\n\\n        # Verify the API call was only made for GitHub repo URLs\\n        parsed = urlparse(url)\\n        if parsed.hostname == \\\"github.com\\\" and not any(x in url for x in [\\\"/tree/\\\", \\\"/releases/\\\", \\\"/commit/\\\"]):\\n            mock_get.assert_called_once()\\n        else:\\n            mock_get.assert_not_called()\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_load_bundles_from_urls():\\n    settings_service = get_settings_service()\\n    settings_service.settings.bundle_urls = [\\n        \\\"https://github.com/langflow-ai/langflow-bundles/commit/68428ce16729a385fe1bcc0f1ec91fd5f5f420b9\\\"\\n    ]\\n    settings_service.auth_settings.AUTO_LOGIN = True\\n\\n    # Create a superuser in the test database since load_bundles_from_urls requires one\\n    async with session_scope() as session:\\n        await create_super_user(\\n            username=settings_service.auth_settings.SUPERUSER,\\n            password=(\\n                settings_service.auth_settings.SUPERUSER_PASSWORD.get_secret_value()\\n                if hasattr(settings_service.auth_settings.SUPERUSER_PASSWORD, \\\"get_secret_value\\\")\\n                else settings_service.auth_settings.SUPERUSER_PASSWORD\\n            ),\\n            db=session,\\n        )\\n\\n    temp_dirs, components_paths = await load_bundles_from_urls()\\n\\n    try:\\n        assert len(components_paths) == 1\\n        assert \\\"langflow-bundles-68428ce16729a385fe1bcc0f1ec91fd5f5f420b9/components\\\" in components_paths[0]\\n\\n        content = await (Path(components_paths[0]) / \\\"embeddings\\\" / \\\"openai2.py\\\").read_text(encoding=\\\"utf-8\\\")\\n        assert \\\"OpenAIEmbeddings2Component\\\" in content\\n\\n        assert len(temp_dirs) == 1\\n\\n        async with session_scope() as session:\\n            stmt = select(Flow).where(Flow.id == uuid.UUID(\\\"c54f9130-f2fa-4a3e-b22a-3856d946351b\\\"))\\n            flow = (await session.exec(stmt)).first()\\n            assert flow is not None\\n    finally:\\n        for temp_dir in temp_dirs:\\n            await asyncio.to_thread(temp_dir.cleanup)\\n\\n\\n@pytest.fixture\\ndef set_fs_flows_polling_interval():\\n    os.environ[\\\"LANGFLOW_FS_FLOWS_POLLING_INTERVAL\\\"] = \\\"100\\\"\\n    yield\\n    os.unsetenv(\\\"LANGFLOW_FS_FLOWS_POLLING_INTERVAL\\\")\\n\\n\\n@pytest.mark.usefixtures(\\\"set_fs_flows_polling_interval\\\")\\nasync def test_sync_flows_from_fs(client: AsyncClient, logged_in_headers):\\n    # Use a relative path which will be placed in the user's flows directory\\n    # The path validation requires paths to be within the user's flows directory for security\\n    flow_filename = f\\\"{uuid.uuid4()}.json\\\"\\n    try:\\n        basic_case = {\\n            \\\"name\\\": \\\"string\\\",\\n            \\\"description\\\": \\\"string\\\",\\n            \\\"data\\\": {},\\n            \\\"locked\\\": False,\\n            \\\"fs_path\\\": flow_filename,\\n        }\\n        response = await client.post(\\\"api/v1/flows/\\\", json=basic_case, headers=logged_in_headers)\\n        assert response.status_code == 201, f\\\"Failed to create flow: {response.text}\\\"\\n        created_flow = response.json()\\n        flow_id = created_flow[\\\"id\\\"]\\n        user_id = created_flow[\\\"user_id\\\"]\\n        async with session_scope() as session:\\n            original_flow = (await session.exec(select(Flow).where(Flow.id == uuid.UUID(flow_id)))).one()\\n            original_updated_at = original_flow.updated_at\\n\\n        # Construct the full path where the file was saved\\n        # The API saves relative paths to: storage_service.data_dir / \\\"flows\\\" / user_id / filename\\n        from langflow.services.deps import get_storage_service\\n\\n        storage_service = get_storage_service()\\n        flow_file = storage_service.data_dir / \\\"flows\\\" / str(user_id) / flow_filename\\n\\n        # Read the file created by the API\\n        fs_flow = orjson.loads(await flow_file.read_bytes())\\n        fs_flow.update(\\n            name=\\\"new name\\\",\\n            description=\\\"new description\\\",\\n            data={\\\"nodes\\\": {}, \\\"edges\\\": {}},\\n            locked=True,\\n        )\\n\\n        await flow_file.write_bytes(orjson.dumps(fs_flow))\\n\\n        result = {}\\n        for i in range(10):\\n            response = await client.get(f\\\"api/v1/flows/{flow_id}\\\", headers=logged_in_headers)\\n            result = response.json()\\n            if result[\\\"name\\\"] == \\\"new name\\\":\\n                break\\n            assert i != 9, \\\"flow name should have been updated\\\"\\n            await asyncio.sleep(0.1)\\n\\n        assert result[\\\"description\\\"] == \\\"new description\\\"\\n        assert result[\\\"data\\\"] == {\\\"nodes\\\": {}, \\\"edges\\\": {}}\\n        assert result[\\\"locked\\\"] is True\\n        async with session_scope() as session:\\n            updated_flow = (await session.exec(select(Flow).where(Flow.id == uuid.UUID(flow_id)))).one()\\n            assert updated_flow.updated_at > original_updated_at\\n    finally:\\n        if \\\"flow_file\\\" in locals():\\n            await flow_file.unlink(missing_ok=True)\\n\\n\\n# ==================== Profile Pictures Tests ====================\\n\\n\\n@pytest.fixture\\ndef profile_pictures_temp_config(monkeypatch):\\n    \\\"\\\"\\\"Fixture that sets up a temporary config directory for profile picture tests.\\\"\\\"\\\"\\n    temp_dir = tempfile.mkdtemp()\\n    config_path = SyncPath(temp_dir)\\n\\n    # Set the config_dir to our temp directory\\n    monkeypatch.setenv(\\\"LANGFLOW_CONFIG_DIR\\\", str(config_path))\\n\\n    yield config_path\\n\\n    # Cleanup\\n    shutil.rmtree(temp_dir, ignore_errors=True)\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_copy_profile_pictures_creates_directories():\\n    \\\"\\\"\\\"Test that copy_profile_pictures creates the profile_pictures directories.\\\"\\\"\\\"\\n    settings_service = get_settings_service()\\n    config_dir = settings_service.settings.config_dir\\n    config_path = SyncPath(config_dir)\\n\\n    # The function should have been called during app startup (client fixture)\\n    # Verify the directories exist\\n    people_dir = config_path / \\\"profile_pictures\\\" / \\\"People\\\"\\n    space_dir = config_path / \\\"profile_pictures\\\" / \\\"Space\\\"\\n\\n    assert people_dir.exists(), \\\"People directory should exist after copy_profile_pictures\\\"\\n    assert space_dir.exists(), \\\"Space directory should exist after copy_profile_pictures\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_copy_profile_pictures_copies_files():\\n    \\\"\\\"\\\"Test that copy_profile_pictures copies all profile picture files.\\\"\\\"\\\"\\n    settings_service = get_settings_service()\\n    config_dir = settings_service.settings.config_dir\\n    config_path = SyncPath(config_dir)\\n\\n    people_dir = config_path / \\\"profile_pictures\\\" / \\\"People\\\"\\n    space_dir = config_path / \\\"profile_pictures\\\" / \\\"Space\\\"\\n\\n    # Check that files were copied\\n    people_files = list(people_dir.glob(\\\"*.svg\\\")) if people_dir.exists() else []\\n    space_files = list(space_dir.glob(\\\"*.svg\\\")) if space_dir.exists() else []\\n\\n    assert len(people_files) > 0, \\\"Should have People profile pictures copied\\\"\\n    assert len(space_files) > 0, \\\"Should have Space profile pictures copied\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_copy_profile_pictures_specific_files_exist():\\n    \\\"\\\"\\\"Test that specific known profile picture files exist after copying.\\\"\\\"\\\"\\n    settings_service = get_settings_service()\\n    config_dir = settings_service.settings.config_dir\\n    config_path = SyncPath(config_dir)\\n\\n    # Check for the default rocket profile picture (used as default in the app)\\n    rocket_path = config_path / \\\"profile_pictures\\\" / \\\"Space\\\" / \\\"046-rocket.svg\\\"\\n    assert rocket_path.exists(), \\\"Default rocket profile picture should exist\\\"\\n\\n    # Check that the file has content\\n    content = rocket_path.read_bytes()\\n    assert len(content) > 0, \\\"Profile picture file should have content\\\"\\n    assert b\\\"<svg\\\" in content or b\\\"<?xml\\\" in content, \\\"Profile picture should be a valid SVG\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_copy_profile_pictures_is_idempotent():\\n    \\\"\\\"\\\"Test that copy_profile_pictures can be called multiple times without issues.\\\"\\\"\\\"\\n    settings_service = get_settings_service()\\n    config_dir = settings_service.settings.config_dir\\n    config_path = SyncPath(config_dir)\\n\\n    # Get initial file count\\n    people_dir = config_path / \\\"profile_pictures\\\" / \\\"People\\\"\\n    initial_count = len(list(people_dir.glob(\\\"*.svg\\\"))) if people_dir.exists() else 0\\n\\n    # Call copy_profile_pictures again\\n    await copy_profile_pictures()\\n\\n    # Count should remain the same (no duplicates)\\n    final_count = len(list(people_dir.glob(\\\"*.svg\\\"))) if people_dir.exists() else 0\\n    assert final_count == initial_count, \\\"Calling copy_profile_pictures again should not create duplicates\\\"\\n\\n\\nasync def test_copy_profile_pictures_source_exists():\\n    \\\"\\\"\\\"Test that the source profile pictures directory exists in the package.\\\"\\\"\\\"\\n    from langflow.initial_setup import setup\\n\\n    source_path = Path(setup.__file__).parent / \\\"profile_pictures\\\"\\n    assert await source_path.exists(), \\\"Source profile_pictures directory should exist in package\\\"\\n\\n    people_source = source_path / \\\"People\\\"\\n    space_source = source_path / \\\"Space\\\"\\n\\n    assert await people_source.exists(), \\\"Source People directory should exist\\\"\\n    assert await space_source.exists(), \\\"Source Space directory should exist\\\"\\n\\n    # Count source files\\n    people_files = [f async for f in people_source.glob(\\\"*.svg\\\")]\\n    space_files = [f async for f in space_source.glob(\\\"*.svg\\\")]\\n\\n    assert len(people_files) > 0, \\\"Source should have People profile pictures\\\"\\n    assert len(space_files) > 0, \\\"Source should have Space profile pictures\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_profile_pictures_available_via_api(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Test that profile pictures are available via the API after app startup.\\\"\\\"\\\"\\n    response = await client.get(\\\"api/v1/files/profile_pictures/list\\\", headers=logged_in_headers)\\n\\n    assert response.status_code == 200, f\\\"Expected 200, got {response.status_code}: {response.json()}\\\"\\n\\n    data = response.json()\\n    assert \\\"files\\\" in data, \\\"Response should contain 'files' key\\\"\\n\\n    files = data[\\\"files\\\"]\\n    assert len(files) > 0, \\\"Should have profile pictures available via API\\\"\\n\\n    # Check for expected file format\\n    assert any(f.startswith(\\\"People/\\\") for f in files), \\\"Should have People profile pictures\\\"\\n    assert any(f.startswith(\\\"Space/\\\") for f in files), \\\"Should have Space profile pictures\\\"\\n\\n    # Check for the default rocket profile picture\\n    assert \\\"Space/046-rocket.svg\\\" in files, \\\"Default rocket profile picture should be available\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_profile_picture_can_be_downloaded(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Test that a profile picture can be downloaded via the API.\\\"\\\"\\\"\\n    response = await client.get(\\n        \\\"api/v1/files/profile_pictures/Space/046-rocket.svg\\\",\\n        headers=logged_in_headers,\\n    )\\n\\n    assert response.status_code == 200, f\\\"Expected 200, got {response.status_code}\\\"\\n    assert \\\"image/svg+xml\\\" in response.headers[\\\"content-type\\\"], \\\"Should return SVG content type\\\"\\n    assert len(response.content) > 0, \\\"Should have content\\\"\\n\\n\\nasync def test_copy_profile_pictures_handles_missing_config_dir():\\n    \\\"\\\"\\\"Test that copy_profile_pictures raises error when config_dir is not set.\\\"\\\"\\\"\\n    with patch(\\\"langflow.initial_setup.setup.get_storage_service\\\") as mock_storage:\\n        mock_settings = AsyncMock()\\n        mock_settings.settings_service.settings.config_dir = None\\n        mock_storage.return_value = mock_settings\\n\\n        with pytest.raises(ValueError, match=\\\"Config dir is not set\\\"):\\n            await copy_profile_pictures()\\n\\n\\ndef test_update_projects_handles_components_without_metadata():\\n    \\\"\\\"\\\"Test that components without metadata are handled gracefully.\\\"\\\"\\\"\\n    all_types_dict = {\\n        \\\"agents\\\": {\\n            \\\"Agent\\\": {\\n                \\\"template\\\": {\\n                    \\\"code\\\": {\\\"value\\\": \\\"test code\\\"},\\n                    \\\"_type\\\": \\\"Component\\\",\\n                },\\n                \\\"display_name\\\": \\\"Agent\\\",\\n                # No metadata field at all\\n            }\\n        }\\n    }\\n\\n    project_data = {\\n        \\\"nodes\\\": [\\n            {\\n                \\\"data\\\": {\\n                    \\\"type\\\": \\\"Agent\\\",\\n                    \\\"node\\\": {\\n                        \\\"template\\\": {\\n                            \\\"code\\\": {\\\"value\\\": \\\"old code\\\"},\\n                            \\\"_type\\\": \\\"Component\\\",\\n                        },\\n                        \\\"outputs\\\": [],\\n                    },\\n                }\\n            }\\n        ]\\n    }\\n\\n    # Should not raise an error\\n    updated_project = update_projects_components_with_latest_component_versions(project_data, all_types_dict)\\n    assert updated_project[\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"code\\\"][\\\"value\\\"] == \\\"test code\\\"\\n\\n\\ndef test_update_projects_resolves_prompt_via_component_type_alias():\\n    \\\"\\\"\\\"Test that legacy Prompt nodes resolve via the explicit legacy alias.\\n\\n    Prompt Template is keyed as \\\"Prompt Template\\\" in the component dictionary,\\n    but starter projects may still reference the legacy \\\"Prompt\\\" type.\\n    \\\"\\\"\\\"\\n    all_types_dict = {\\n        \\\"models_and_agents\\\": {\\n            \\\"Prompt Template\\\": {\\n                \\\"template\\\": {\\n                    \\\"code\\\": {\\\"value\\\": \\\"new_prompt_code_v2\\\"},\\n                    \\\"_type\\\": \\\"Component\\\",\\n                },\\n                \\\"display_name\\\": \\\"Prompt Template\\\",\\n            }\\n        }\\n    }\\n\\n    project_data = {\\n        \\\"nodes\\\": [\\n            {\\n                \\\"data\\\": {\\n                    \\\"type\\\": \\\"Prompt\\\",  # Old type name, doesn't match key \\\"Prompt Template\\\"\\n                    \\\"node\\\": {\\n                        \\\"template\\\": {\\n                            \\\"code\\\": {\\\"value\\\": \\\"old_prompt_code_v1\\\"},\\n                            \\\"_type\\\": \\\"Component\\\",\\n                        },\\n                        \\\"outputs\\\": [],\\n                    },\\n                }\\n            }\\n        ]\\n    }\\n\\n    updated_project = update_projects_components_with_latest_component_versions(project_data, all_types_dict)\\n    updated_code = updated_project[\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"code\\\"][\\\"value\\\"]\\n    assert updated_code == \\\"new_prompt_code_v2\\\", (\\n        f\\\"Expected code to be updated to 'new_prompt_code_v2' but got '{updated_code}'. \\\"\\n        \\\"The legacy 'Prompt' type should resolve to 'Prompt Template'.\\\"\\n    )\\n\\n\\ndef test_update_projects_preserves_current_prompt_custom_fields():\\n    \\\"\\\"\\\"Current Prompt Template nodes must retain serialized dynamic inputs.\\\"\\\"\\\"\\n    url_field = {\\n        \\\"name\\\": \\\"URL\\\",\\n        \\\"type\\\": \\\"str\\\",\\n        \\\"value\\\": \\\"\\\",\\n        \\\"input_types\\\": [\\\"Message\\\", \\\"Text\\\"],\\n    }\\n    all_types_dict = {\\n        \\\"models_and_agents\\\": {\\n            \\\"Prompt Template\\\": {\\n                \\\"template\\\": {\\n                    \\\"_type\\\": \\\"Component\\\",\\n                    \\\"code\\\": {\\\"value\\\": \\\"new_prompt_code\\\"},\\n                    \\\"template\\\": {\\\"type\\\": \\\"prompt\\\", \\\"value\\\": \\\"\\\"},\\n                },\\n                \\\"display_name\\\": \\\"Prompt Template\\\",\\n            }\\n        }\\n    }\\n    project_data = {\\n        \\\"nodes\\\": [\\n            {\\n                \\\"data\\\": {\\n                    \\\"type\\\": \\\"Prompt Template\\\",\\n                    \\\"node\\\": {\\n                        \\\"custom_fields\\\": {\\\"template\\\": [\\\"URL\\\"]},\\n                        \\\"template\\\": {\\n                            \\\"_type\\\": \\\"Component\\\",\\n                            \\\"code\\\": {\\\"value\\\": \\\"old_prompt_code\\\"},\\n                            \\\"template\\\": {\\\"type\\\": \\\"prompt\\\", \\\"value\\\": \\\"Source: {URL}\\\"},\\n                            \\\"URL\\\": url_field,\\n                        },\\n                        \\\"outputs\\\": [],\\n                    },\\n                }\\n            }\\n        ]\\n    }\\n\\n    updated_project = update_projects_components_with_latest_component_versions(project_data, all_types_dict)\\n\\n    updated_template = updated_project[\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"]\\n    assert updated_template[\\\"URL\\\"] == url_field\\n\\n\\ndef test_update_projects_direct_key_takes_precedence_over_alias():\\n    \\\"\\\"\\\"Test that a direct key match is preferred over the derived alias.\\\"\\\"\\\"\\n    all_types_dict = {\\n        \\\"category\\\": {\\n            \\\"Prompt\\\": {\\n                \\\"template\\\": {\\n                    \\\"code\\\": {\\\"value\\\": \\\"direct_match_code\\\"},\\n                    \\\"_type\\\": \\\"Component\\\",\\n                },\\n                \\\"display_name\\\": \\\"Prompt\\\",\\n            },\\n            \\\"Prompt Template\\\": {\\n                \\\"template\\\": {\\n                    \\\"code\\\": {\\\"value\\\": \\\"renamed_code\\\"},\\n                    \\\"_type\\\": \\\"Component\\\",\\n                },\\n                \\\"display_name\\\": \\\"Prompt Template\\\",\\n            },\\n        }\\n    }\\n\\n    project_data = {\\n        \\\"nodes\\\": [\\n            {\\n                \\\"data\\\": {\\n                    \\\"type\\\": \\\"Prompt\\\",\\n                    \\\"node\\\": {\\n                        \\\"template\\\": {\\n                            \\\"code\\\": {\\\"value\\\": \\\"old_code\\\"},\\n                            \\\"_type\\\": \\\"Component\\\",\\n                        },\\n                        \\\"outputs\\\": [],\\n                    },\\n                }\\n            }\\n        ]\\n    }\\n\\n    updated_project = update_projects_components_with_latest_component_versions(project_data, all_types_dict)\\n    updated_code = updated_project[\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"code\\\"][\\\"value\\\"]\\n    assert updated_code == \\\"direct_match_code\\\", (\\n        \\\"Direct key match ('Prompt') should take precedence over the derived alias to 'Prompt Template'\\\"\\n    )\\n\\n\\ndef test_update_projects_resolves_url_via_component_type_alias():\\n    \\\"\\\"\\\"Test that legacy URL nodes resolve via the component class alias.\\\"\\\"\\\"\\n    all_types_dict = {\\n        \\\"tools\\\": {\\n            \\\"URLComponent\\\": {\\n                \\\"template\\\": {\\n                    \\\"code\\\": {\\\"value\\\": \\\"new_url_code_v2\\\"},\\n                    \\\"_type\\\": \\\"URLComponent\\\",\\n                },\\n                \\\"display_name\\\": \\\"URL\\\",\\n            }\\n        }\\n    }\\n\\n    project_data = {\\n        \\\"nodes\\\": [\\n            {\\n                \\\"data\\\": {\\n                    \\\"type\\\": \\\"URL\\\",\\n                    \\\"node\\\": {\\n                        \\\"template\\\": {\\n                            \\\"code\\\": {\\\"value\\\": \\\"old_url_code_v1\\\"},\\n                            \\\"_type\\\": \\\"Component\\\",\\n                        },\\n                        \\\"outputs\\\": [],\\n                    },\\n                }\\n            }\\n        ]\\n    }\\n\\n    updated_project = update_projects_components_with_latest_component_versions(project_data, all_types_dict)\\n    updated_code = updated_project[\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"code\\\"][\\\"value\\\"]\\n    assert updated_code == \\\"new_url_code_v2\\\"\\n\\n\\ndef test_update_projects_resolves_parser_via_component_type_alias():\\n    \\\"\\\"\\\"Test that legacy lowercase parser nodes resolve via the explicit alias.\\\"\\\"\\\"\\n    all_types_dict = {\\n        \\\"processing\\\": {\\n            \\\"ParserComponent\\\": {\\n                \\\"template\\\": {\\n                    \\\"code\\\": {\\\"value\\\": \\\"new_parser_code_v2\\\"},\\n                    \\\"_type\\\": \\\"Component\\\",\\n                },\\n                \\\"display_name\\\": \\\"Parser\\\",\\n            }\\n        }\\n    }\\n\\n    project_data = {\\n        \\\"nodes\\\": [\\n            {\\n                \\\"data\\\": {\\n                    \\\"type\\\": \\\"parser\\\",\\n                    \\\"node\\\": {\\n                        \\\"template\\\": {\\n                            \\\"code\\\": {\\\"value\\\": \\\"old_parser_code_v1\\\"},\\n                            \\\"_type\\\": \\\"Component\\\",\\n                        },\\n                        \\\"outputs\\\": [],\\n                    },\\n                }\\n            }\\n        ]\\n    }\\n\\n    updated_project = update_projects_components_with_latest_component_versions(project_data, all_types_dict)\\n    updated_code = updated_project[\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"code\\\"][\\\"value\\\"]\\n    assert updated_code == \\\"new_parser_code_v2\\\"\\n\\n\\n# ==================== Update Project File Tests ====================\\n\\n\\nasync def test_update_project_file_success():\\n    \\\"\\\"\\\"Test that update_project_file successfully writes to a writable path.\\\"\\\"\\\"\\n    from langflow.initial_setup.setup import update_project_file\\n\\n    with tempfile.TemporaryDirectory() as temp_dir:\\n        project_path = Path(temp_dir) / \\\"test_project.json\\\"\\n        project = {\\\"name\\\": \\\"Test Project\\\", \\\"data\\\": {\\\"old\\\": \\\"data\\\"}}\\n        updated_data = {\\\"new\\\": \\\"data\\\"}\\n\\n        await update_project_file(project_path, project, updated_data)\\n\\n        # Verify the file was written\\n        assert await project_path.exists()\\n        content = await project_path.read_text(encoding=\\\"utf-8\\\")\\n        import orjson\\n\\n        written_project = orjson.loads(content)\\n        assert written_project[\\\"data\\\"] == updated_data\\n        assert written_project[\\\"name\\\"] == \\\"Test Project\\\"\\n\\n\\nasync def test_update_project_file_readonly_filesystem():\\n    \\\"\\\"\\\"Test that update_project_file handles read-only filesystem gracefully.\\\"\\\"\\\"\\n    from langflow.initial_setup.setup import update_project_file\\n\\n    project_path = Path(\\\"/nonexistent/readonly/path/test_project.json\\\")\\n    project = {\\\"name\\\": \\\"Test Project\\\", \\\"data\\\": {\\\"old\\\": \\\"data\\\"}}\\n    updated_data = {\\\"new\\\": \\\"data\\\"}\\n\\n    # This should NOT raise an exception - it should handle the error gracefully\\n    await update_project_file(project_path, project, updated_data)\\n\\n    # Verify the project dict was still updated (in-memory)\\n    assert project[\\\"data\\\"] == updated_data\\n\\n\\nasync def test_update_project_file_permission_denied():\\n    \\\"\\\"\\\"Test that update_project_file handles permission denied gracefully.\\\"\\\"\\\"\\n    from langflow.initial_setup.setup import update_project_file\\n\\n    with tempfile.TemporaryDirectory() as temp_dir:\\n        project_path = Path(temp_dir) / \\\"test_project.json\\\"\\n        project = {\\\"name\\\": \\\"Test Project\\\", \\\"data\\\": {\\\"old\\\": \\\"data\\\"}}\\n        updated_data = {\\\"new\\\": \\\"data\\\"}\\n\\n        # Mock aiofiles.open to raise OSError (permission denied)\\n        with patch(\\\"langflow.initial_setup.setup.aiofiles.open\\\") as mock_open:\\n            mock_open.side_effect = OSError(13, \\\"Permission denied\\\")\\n\\n            # Should not raise\\n            await update_project_file(project_path, project, updated_data)\\n\\n            # Verify the project dict was still updated (in-memory)\\n            assert project[\\\"data\\\"] == updated_data\\n\\n\\nasync def test_update_project_file_logs_debug_on_oserror():\\n    \\\"\\\"\\\"Test that update_project_file logs a debug message on OSError.\\\"\\\"\\\"\\n    from langflow.initial_setup.setup import update_project_file\\n\\n    project_path = Path(\\\"/nonexistent/readonly/path/test_project.json\\\")\\n    project = {\\\"name\\\": \\\"Test Project\\\", \\\"data\\\": {\\\"old\\\": \\\"data\\\"}}\\n    updated_data = {\\\"new\\\": \\\"data\\\"}\\n\\n    with patch(\\\"langflow.initial_setup.setup.logger\\\") as mock_logger:\\n        mock_logger.adebug = AsyncMock()\\n        await update_project_file(project_path, project, updated_data)\\n        # Verify debug log was called (either success or error path)\\n        assert mock_logger.adebug.called\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_kb_storage_deletion.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8d8a0b3c7e7f1f1f21a53509159b51c72ae32d968a006635c14c1fc0815b0b3d\",\"content\":\"\\\"\\\"\\\"Tests for unified Knowledge Base deletion and resource cleanup.\\n\\nCovers the delete_storage method, release_chroma_resources, private helpers\\n(_remove_sqlite_lock_files, _truncate_sqlite_files), and the delete endpoints.\\n\\\"\\\"\\\"\\n\\nimport json\\nimport shutil\\nimport uuid\\nfrom pathlib import Path\\nfrom unittest.mock import MagicMock, patch\\n\\nimport pytest\\n\\n# ---------------------------------------------------------------------------\\n# Fixtures\\n# ---------------------------------------------------------------------------\\n\\n\\n@pytest.fixture\\ndef kb_dir(tmp_path):\\n    \\\"\\\"\\\"Create a fake KB directory with SQLite files simulating ChromaDB.\\\"\\\"\\\"\\n    kb = tmp_path / \\\"test_kb\\\"\\n    kb.mkdir()\\n    (kb / \\\"chroma.sqlite3\\\").write_bytes(b\\\"fake-sqlite-data\\\")\\n    (kb / \\\"chroma.sqlite3-wal\\\").write_bytes(b\\\"wal-data\\\")\\n    (kb / \\\"chroma.sqlite3-shm\\\").write_bytes(b\\\"shm-data\\\")\\n    (kb / \\\"embedding_metadata.json\\\").write_text(json.dumps({\\\"id\\\": str(uuid.uuid4())}))\\n    return kb\\n\\n\\n@pytest.fixture\\ndef empty_kb_dir(tmp_path):\\n    \\\"\\\"\\\"Create a KB directory with no ChromaDB data files.\\\"\\\"\\\"\\n    kb = tmp_path / \\\"empty_kb\\\"\\n    kb.mkdir()\\n    return kb\\n\\n\\n# ===========================================================================\\n# Unit tests: _remove_sqlite_lock_files\\n# ===========================================================================\\n\\n\\nclass TestRemoveSqliteLockFiles:\\n    \\\"\\\"\\\"Tests for _remove_sqlite_lock_files \u2014 removes WAL, SHM, journal files.\\\"\\\"\\\"\\n\\n    def test_should_remove_all_lock_files(self, kb_dir):\\n        from langflow.api.utils.kb_helpers import _remove_sqlite_lock_files\\n\\n        (kb_dir / \\\"chroma.sqlite3-journal\\\").write_bytes(b\\\"journal\\\")\\n        assert (kb_dir / \\\"chroma.sqlite3-wal\\\").exists()\\n        assert (kb_dir / \\\"chroma.sqlite3-shm\\\").exists()\\n\\n        _remove_sqlite_lock_files(kb_dir)\\n\\n        assert not (kb_dir / \\\"chroma.sqlite3-wal\\\").exists()\\n        assert not (kb_dir / \\\"chroma.sqlite3-shm\\\").exists()\\n        assert not (kb_dir / \\\"chroma.sqlite3-journal\\\").exists()\\n        assert (kb_dir / \\\"chroma.sqlite3\\\").exists()\\n\\n    def test_should_not_raise_when_no_lock_files(self, empty_kb_dir):\\n        from langflow.api.utils.kb_helpers import _remove_sqlite_lock_files\\n\\n        _remove_sqlite_lock_files(empty_kb_dir)\\n\\n    def test_should_handle_permission_error_gracefully(self, kb_dir):\\n        from langflow.api.utils.kb_helpers import _remove_sqlite_lock_files\\n\\n        with patch.object(Path, \\\"unlink\\\", side_effect=OSError(\\\"Permission denied\\\")):\\n            _remove_sqlite_lock_files(kb_dir)\\n\\n\\n# ===========================================================================\\n# Unit tests: _truncate_sqlite_files\\n# ===========================================================================\\n\\n\\nclass TestTruncateSqliteFiles:\\n    \\\"\\\"\\\"Tests for _truncate_sqlite_files \u2014 truncates .sqlite3 files.\\\"\\\"\\\"\\n\\n    def test_should_truncate_sqlite_files_to_zero(self, kb_dir):\\n        from langflow.api.utils.kb_helpers import _truncate_sqlite_files\\n\\n        assert (kb_dir / \\\"chroma.sqlite3\\\").stat().st_size > 0\\n\\n        _truncate_sqlite_files(kb_dir)\\n\\n        assert (kb_dir / \\\"chroma.sqlite3\\\").stat().st_size == 0\\n\\n    def test_should_not_raise_when_no_sqlite_files(self, empty_kb_dir):\\n        from langflow.api.utils.kb_helpers import _truncate_sqlite_files\\n\\n        _truncate_sqlite_files(empty_kb_dir)\\n\\n    def test_should_handle_locked_file_gracefully(self, kb_dir):\\n        from langflow.api.utils.kb_helpers import _truncate_sqlite_files\\n\\n        with patch(\\\"builtins.open\\\", side_effect=OSError(\\\"File is locked\\\")):\\n            _truncate_sqlite_files(kb_dir)\\n\\n\\n# ===========================================================================\\n# Unit tests: KBStorageHelper.release_chroma_resources\\n# ===========================================================================\\n\\n\\nclass TestReleaseChromaResources:\\n    \\\"\\\"\\\"Tests for release_chroma_resources \u2014 clears registry and forces GC.\\\"\\\"\\\"\\n\\n    def test_should_clear_registry_entry_for_path(self, kb_dir):\\n        from chromadb.api.shared_system_client import SharedSystemClient\\n        from langflow.api.utils.kb_helpers import KBStorageHelper\\n\\n        path_key = str(kb_dir)\\n        SharedSystemClient._identifier_to_system[path_key] = MagicMock()\\n\\n        KBStorageHelper.release_chroma_resources(kb_dir)\\n\\n        assert path_key not in SharedSystemClient._identifier_to_system\\n\\n    def test_should_not_raise_when_path_not_in_registry(self, tmp_path):\\n        from langflow.api.utils.kb_helpers import KBStorageHelper\\n\\n        KBStorageHelper.release_chroma_resources(tmp_path / \\\"nonexistent\\\")\\n\\n    @patch(\\\"langflow.api.utils.kb_helpers.gc.collect\\\")\\n    def test_should_call_gc_collect(self, mock_gc, tmp_path):\\n        from langflow.api.utils.kb_helpers import KBStorageHelper\\n\\n        KBStorageHelper.release_chroma_resources(tmp_path)\\n\\n        mock_gc.assert_called_once()\\n\\n\\n# ===========================================================================\\n# Unit tests: KBStorageHelper.delete_storage\\n# ===========================================================================\\n\\n\\nclass TestDeleteStorage:\\n    \\\"\\\"\\\"Tests for KBStorageHelper.delete_storage \u2014 unified deletion with retry.\\\"\\\"\\\"\\n\\n    @patch(\\\"langflow.api.utils.kb_helpers.KBStorageHelper.get_fresh_chroma_client\\\", new=MagicMock())\\n    @patch(\\\"langflow.api.utils.kb_helpers.Chroma\\\", new=MagicMock())\\n    @patch(\\\"langflow.api.utils.kb_helpers.time.sleep\\\", new=MagicMock())\\n    def test_should_return_true_when_path_does_not_exist(self, tmp_path):\\n        from langflow.api.utils.kb_helpers import KBStorageHelper\\n\\n        non_existent = tmp_path / \\\"does_not_exist\\\"\\n        result = KBStorageHelper.delete_storage(non_existent, \\\"ghost_kb\\\")\\n\\n        assert result is True\\n\\n    @patch(\\\"langflow.api.utils.kb_helpers.KBStorageHelper.get_fresh_chroma_client\\\", new=MagicMock())\\n    @patch(\\\"langflow.api.utils.kb_helpers.Chroma\\\", new=MagicMock())\\n    @patch(\\\"langflow.api.utils.kb_helpers.time.sleep\\\", new=MagicMock())\\n    def test_should_delete_directory_on_first_attempt(self, kb_dir):\\n        from langflow.api.utils.kb_helpers import KBStorageHelper\\n\\n        result = KBStorageHelper.delete_storage(kb_dir, \\\"test_kb\\\")\\n\\n        assert result is True\\n        assert not kb_dir.exists()\\n\\n    @patch(\\\"langflow.api.utils.kb_helpers.KBStorageHelper.get_fresh_chroma_client\\\", new=MagicMock())\\n    @patch(\\\"langflow.api.utils.kb_helpers.Chroma\\\", new=MagicMock())\\n    @patch(\\\"langflow.api.utils.kb_helpers.time.sleep\\\", new=MagicMock())\\n    def test_should_retry_and_succeed_on_second_attempt(self, kb_dir):\\n        from langflow.api.utils.kb_helpers import KBStorageHelper\\n\\n        original_rmtree = shutil.rmtree\\n        call_count = 0\\n\\n        def rmtree_fails_once(path, *, ignore_errors=False):\\n            nonlocal call_count\\n            call_count += 1\\n            if call_count == 1:\\n                msg = \\\"[WinError 32] File in use\\\"\\n                raise OSError(msg)\\n            original_rmtree(path, ignore_errors=ignore_errors)\\n\\n        with patch(\\\"langflow.api.utils.kb_helpers.shutil.rmtree\\\", side_effect=rmtree_fails_once):\\n            result = KBStorageHelper.delete_storage(kb_dir, \\\"test_kb\\\")\\n\\n        assert result is True\\n        assert call_count == 2\\n\\n    @patch(\\\"langflow.api.utils.kb_helpers.KBStorageHelper.get_fresh_chroma_client\\\", new=MagicMock())\\n    @patch(\\\"langflow.api.utils.kb_helpers.Chroma\\\", new=MagicMock())\\n    @patch(\\\"langflow.api.utils.kb_helpers.time.sleep\\\", new=MagicMock())\\n    def test_should_write_sentinel_when_all_retries_fail(self, kb_dir):\\n        \\\"\\\"\\\"Locked directory falls back to a ``.kb_deleted`` sentinel file.\\n\\n        Replaces the previous rename fallback: the dir keeps its original\\n        name, but the listing layer skips dirs carrying the sentinel.\\n        \\\"\\\"\\\"\\n        from langflow.api.utils.kb_helpers import KB_DELETED_SENTINEL, KBStorageHelper\\n\\n        with patch(\\n            \\\"langflow.api.utils.kb_helpers.shutil.rmtree\\\",\\n            side_effect=OSError(\\\"[WinError 32] File in use\\\"),\\n        ):\\n            result = KBStorageHelper.delete_storage(kb_dir, \\\"test_kb\\\")\\n\\n        assert result is True\\n        assert kb_dir.exists(), \\\"dir should remain on disk; the sentinel hides it from listings\\\"\\n        assert (kb_dir / KB_DELETED_SENTINEL).is_file()\\n\\n    @patch(\\\"langflow.api.utils.kb_helpers.KBStorageHelper.get_fresh_chroma_client\\\", new=MagicMock())\\n    @patch(\\\"langflow.api.utils.kb_helpers.Chroma\\\", new=MagicMock())\\n    @patch(\\\"langflow.api.utils.kb_helpers.time.sleep\\\", new=MagicMock())\\n    def test_should_return_false_when_rmtree_and_sentinel_both_fail(self, kb_dir):\\n        \\\"\\\"\\\"If even the sentinel write fails, the helper reports the failure.\\n\\n        Covers the worst case: a lock that prevents both ``rmtree`` and a\\n        plain ``Path.touch`` inside the dir (e.g. permission denied on the\\n        directory itself).  The caller can then surface a 200-with-warning\\n        rather than silently claiming success.\\n        \\\"\\\"\\\"\\n        from langflow.api.utils.kb_helpers import KBStorageHelper\\n\\n        with (\\n            patch(\\n                \\\"langflow.api.utils.kb_helpers.shutil.rmtree\\\",\\n                side_effect=OSError(\\\"[WinError 32] File in use\\\"),\\n            ),\\n            patch.object(Path, \\\"touch\\\", side_effect=OSError(\\\"Permission denied\\\")),\\n        ):\\n            result = KBStorageHelper.delete_storage(kb_dir, \\\"test_kb\\\")\\n\\n        assert result is False\\n        assert kb_dir.exists()\\n\\n    @patch(\\\"langflow.api.utils.kb_helpers.KBStorageHelper.get_fresh_chroma_client\\\", new=MagicMock())\\n    @patch(\\\"langflow.api.utils.kb_helpers.Chroma\\\", new=MagicMock())\\n    @patch(\\\"langflow.api.utils.kb_helpers.time.sleep\\\")\\n    def test_should_use_exponential_backoff_on_retries(self, mock_sleep, kb_dir):\\n        from langflow.api.utils.kb_helpers import KBStorageHelper\\n\\n        real_rmtree = shutil.rmtree\\n        call_count = 0\\n\\n        def rmtree_fails_three_times(path, *, ignore_errors=False):\\n            nonlocal call_count\\n            call_count += 1\\n            if call_count <= 3:\\n                msg = \\\"[WinError 32] File in use\\\"\\n                raise OSError(msg)\\n            real_rmtree(path, ignore_errors=ignore_errors)\\n\\n        with patch(\\\"langflow.api.utils.kb_helpers.shutil.rmtree\\\", side_effect=rmtree_fails_three_times):\\n            result = KBStorageHelper.delete_storage(kb_dir, \\\"test_kb\\\")\\n\\n        assert result is True\\n        sleep_values = [call.args[0] for call in mock_sleep.call_args_list]\\n        assert sleep_values == [1.0, 2.0, 4.0]\\n\\n    @patch(\\\"langflow.api.utils.kb_helpers.KBStorageHelper.get_fresh_chroma_client\\\")\\n    @patch(\\\"langflow.api.utils.kb_helpers.Chroma\\\")\\n    @patch(\\\"langflow.api.utils.kb_helpers.time.sleep\\\", new=MagicMock())\\n    def test_should_teardown_collection_before_deletion(self, mock_chroma_cls, mock_client_cls, kb_dir):\\n        from langflow.api.utils.kb_helpers import KBStorageHelper\\n\\n        mock_chroma = MagicMock()\\n        mock_chroma_cls.return_value = mock_chroma\\n        mock_client_cls.return_value = MagicMock()\\n\\n        KBStorageHelper.delete_storage(kb_dir, \\\"test_kb\\\")\\n\\n        mock_chroma.delete_collection.assert_called_once()\\n        assert not kb_dir.exists()\\n\\n    @patch(\\\"langflow.api.utils.kb_helpers.KBStorageHelper.get_fresh_chroma_client\\\")\\n    @patch(\\\"langflow.api.utils.kb_helpers.time.sleep\\\", new=MagicMock())\\n    def test_should_not_fail_when_teardown_raises(self, mock_client_cls, kb_dir):\\n        from langflow.api.utils.kb_helpers import KBStorageHelper\\n\\n        mock_client_cls.side_effect = OSError(\\\"Cannot open database\\\")\\n\\n        result = KBStorageHelper.delete_storage(kb_dir, \\\"test_kb\\\")\\n\\n        assert result is True\\n        assert not kb_dir.exists()\\n\\n    @patch(\\\"langflow.api.utils.kb_helpers.KBStorageHelper.get_fresh_chroma_client\\\", new=MagicMock())\\n    @patch(\\\"langflow.api.utils.kb_helpers.Chroma\\\", new=MagicMock())\\n    @patch(\\\"langflow.api.utils.kb_helpers.time.sleep\\\", new=MagicMock())\\n    def test_should_skip_teardown_when_no_chroma_data(self, empty_kb_dir):\\n        from langflow.api.utils.kb_helpers import KBStorageHelper\\n\\n        result = KBStorageHelper.delete_storage(empty_kb_dir, \\\"empty_kb\\\")\\n\\n        assert result is True\\n        assert not empty_kb_dir.exists()\\n\\n\\n# ===========================================================================\\n# Integration tests: delete endpoints using unified delete_storage\\n# ===========================================================================\\n\\n\\nasync def _seed_kb_row(active_user, name: str):\\n    \\\"\\\"\\\"Create the ``knowledge_base`` row that makes a KB exist.\\n\\n    The delete endpoints resolve existence from the row, not from a directory,\\n    so a bare directory is not deletable (and not visible) without one.\\n    \\\"\\\"\\\"\\n    from langflow.api.utils import knowledge_base_service\\n\\n    return await knowledge_base_service.create_record(\\n        user_id=active_user.id,\\n        name=name,\\n        model_selection={\\\"name\\\": \\\"text-embedding-3-small\\\", \\\"provider\\\": \\\"OpenAI\\\"},\\n    )\\n\\n\\nclass TestDeleteEndpoint:\\n    \\\"\\\"\\\"Tests that delete endpoint uses KBStorageHelper.delete_storage.\\\"\\\"\\\"\\n\\n    @patch(\\\"langflow.api.utils.kb_helpers.KBStorageHelper.get_fresh_chroma_client\\\", new=MagicMock())\\n    @patch(\\\"langflow.api.utils.kb_helpers.Chroma\\\", new=MagicMock())\\n    @patch(\\\"langflow.api.utils.kb_helpers.time.sleep\\\", new=MagicMock())\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_should_delete_kb_successfully(self, mock_root, client, logged_in_headers, active_user, tmp_path):\\n        mock_root.return_value = tmp_path\\n        (tmp_path / \\\"activeuser\\\" / \\\"My_KB\\\").mkdir(parents=True)\\n        await _seed_kb_row(active_user, \\\"My_KB\\\")\\n\\n        response = await client.delete(\\\"api/v1/knowledge_bases/My_KB\\\", headers=logged_in_headers)\\n\\n        assert response.status_code == 200\\n\\n    @patch(\\\"langflow.api.utils.kb_helpers.KBStorageHelper.delete_storage\\\", return_value=False)\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_should_return_200_with_warning_when_storage_cleanup_fails(\\n        self, mock_root, mock_delete, client, logged_in_headers, active_user, tmp_path\\n    ):\\n        \\\"\\\"\\\"Storage failure must not block the user from removing the KB.\\n\\n        DB-first ordering: by the time delete_storage() returns False the\\n        row has already been dropped, so the user no longer sees the KB.\\n        We surface a warning with the on-disk consequence so an operator\\n        can follow up, but the request itself succeeds.\\n        \\\"\\\"\\\"\\n        mock_root.return_value = tmp_path\\n        (tmp_path / \\\"activeuser\\\" / \\\"My_KB\\\").mkdir(parents=True)\\n        await _seed_kb_row(active_user, \\\"My_KB\\\")\\n\\n        response = await client.delete(\\\"api/v1/knowledge_bases/My_KB\\\", headers=logged_in_headers)\\n\\n        assert response.status_code == 200\\n        body = response.json()\\n        assert body[\\\"message\\\"].startswith(\\\"Knowledge base 'My_KB' deleted\\\")\\n        assert \\\"could not be cleaned up\\\" in body.get(\\\"warning\\\", \\\"\\\")\\n        mock_delete.assert_called_once()\\n\\n    async def test_should_return_404_when_kb_not_found(self, client, logged_in_headers):\\n        response = await client.delete(\\\"api/v1/knowledge_bases/NonExistent_KB\\\", headers=logged_in_headers)\\n\\n        assert response.status_code == 404\\n\\n\\nclass TestBulkDeleteEndpoint:\\n    \\\"\\\"\\\"Tests that bulk delete endpoint uses KBStorageHelper.delete_storage.\\\"\\\"\\\"\\n\\n    @patch(\\\"langflow.api.utils.kb_helpers.KBStorageHelper.get_fresh_chroma_client\\\", new=MagicMock())\\n    @patch(\\\"langflow.api.utils.kb_helpers.Chroma\\\", new=MagicMock())\\n    @patch(\\\"langflow.api.utils.kb_helpers.time.sleep\\\", new=MagicMock())\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_should_delete_multiple_kbs(self, mock_root, client, logged_in_headers, active_user, tmp_path):\\n        mock_root.return_value = tmp_path\\n        kb_user_path = tmp_path / \\\"activeuser\\\"\\n        kb_user_path.mkdir(parents=True)\\n        (kb_user_path / \\\"KB1\\\").mkdir()\\n        (kb_user_path / \\\"KB2\\\").mkdir()\\n        await _seed_kb_row(active_user, \\\"KB1\\\")\\n        await _seed_kb_row(active_user, \\\"KB2\\\")\\n\\n        response = await client.request(\\n            \\\"DELETE\\\",\\n            \\\"api/v1/knowledge_bases\\\",\\n            headers=logged_in_headers,\\n            json={\\\"kb_names\\\": [\\\"KB1\\\", \\\"KB2\\\"]},\\n        )\\n\\n        assert response.status_code == 200\\n        data = response.json()\\n        assert data[\\\"deleted_count\\\"] == 2\\n\\n    @patch(\\\"langflow.api.utils.kb_helpers.KBStorageHelper.delete_storage\\\")\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_should_handle_partial_storage_failure_with_warning(\\n        self, mock_root, mock_delete, client, logged_in_headers, active_user, tmp_path\\n    ):\\n        \\\"\\\"\\\"Storage failure on one KB still counts as deleted, with a warning.\\n\\n        DB-first ordering: the second KB's row is dropped before storage\\n        cleanup runs, so the user sees both KBs disappear from the list\\n        even when delete_storage() returns False on one.  The response\\n        includes a warning so an operator can follow up on the orphaned\\n        bytes.\\n        \\\"\\\"\\\"\\n        mock_root.return_value = tmp_path\\n        kb_user_path = tmp_path / \\\"activeuser\\\"\\n        kb_user_path.mkdir(parents=True)\\n        (kb_user_path / \\\"KB1\\\").mkdir()\\n        (kb_user_path / \\\"KB2\\\").mkdir()\\n        await _seed_kb_row(active_user, \\\"KB1\\\")\\n        await _seed_kb_row(active_user, \\\"KB2\\\")\\n\\n        mock_delete.side_effect = [True, False]\\n\\n        response = await client.request(\\n            \\\"DELETE\\\",\\n            \\\"api/v1/knowledge_bases\\\",\\n            headers=logged_in_headers,\\n            json={\\\"kb_names\\\": [\\\"KB1\\\", \\\"KB2\\\"]},\\n        )\\n\\n        assert response.status_code == 200\\n        data = response.json()\\n        assert data[\\\"deleted_count\\\"] == 2\\n        # Warnings field is named ``remote_warnings`` server-side; test the\\n        # external contract: a warning string mentioning the failed KB.\\n        warnings_field = data.get(\\\"remote_warnings\\\") or data.get(\\\"warnings\\\") or data.get(\\\"warning\\\") or \\\"\\\"\\n        assert \\\"KB2\\\" in str(warnings_field) or \\\"could not be cleaned up\\\" in str(warnings_field)\\n\\n    @patch(\\\"langflow.api.utils.kb_helpers.KBStorageHelper.delete_storage\\\", new=MagicMock(return_value=True))\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_should_report_not_found_kbs(self, mock_root, client, logged_in_headers, active_user, tmp_path):\\n        mock_root.return_value = tmp_path\\n        kb_user_path = tmp_path / \\\"activeuser\\\"\\n        kb_user_path.mkdir(parents=True)\\n        (kb_user_path / \\\"KB1\\\").mkdir()\\n        await _seed_kb_row(active_user, \\\"KB1\\\")\\n\\n        response = await client.request(\\n            \\\"DELETE\\\",\\n            \\\"api/v1/knowledge_bases\\\",\\n            headers=logged_in_headers,\\n            json={\\\"kb_names\\\": [\\\"KB1\\\", \\\"Ghost\\\"]},\\n        )\\n\\n        assert response.status_code == 200\\n        data = response.json()\\n        assert data[\\\"deleted_count\\\"] == 1\\n        assert \\\"Ghost\\\" in data[\\\"not_found\\\"]\\n\\n\\n# ===========================================================================\\n# Unit tests: sentinel helpers\\n# ===========================================================================\\n\\n\\nclass TestSentinelHelpers:\\n    \\\"\\\"\\\"Tests for ``is_kb_dir_deleted`` and ``clear_deletion_sentinel``.\\\"\\\"\\\"\\n\\n    def test_is_kb_dir_deleted_false_when_marker_absent(self, kb_dir):\\n        from langflow.api.utils.kb_helpers import KBStorageHelper\\n\\n        assert KBStorageHelper.is_kb_dir_deleted(kb_dir) is False\\n\\n    def test_is_kb_dir_deleted_true_when_marker_present(self, kb_dir):\\n        from langflow.api.utils.kb_helpers import KB_DELETED_SENTINEL, KBStorageHelper\\n\\n        (kb_dir / KB_DELETED_SENTINEL).touch()\\n        assert KBStorageHelper.is_kb_dir_deleted(kb_dir) is True\\n\\n    def test_is_kb_dir_deleted_false_for_missing_dir(self, tmp_path):\\n        from langflow.api.utils.kb_helpers import KBStorageHelper\\n\\n        assert KBStorageHelper.is_kb_dir_deleted(tmp_path / \\\"nope\\\") is False\\n\\n    def test_clear_deletion_sentinel_removes_marker(self, kb_dir):\\n        from langflow.api.utils.kb_helpers import KB_DELETED_SENTINEL, KBStorageHelper\\n\\n        marker = kb_dir / KB_DELETED_SENTINEL\\n        marker.touch()\\n        assert marker.exists()\\n\\n        KBStorageHelper.clear_deletion_sentinel(kb_dir)\\n        assert not marker.exists()\\n\\n    def test_clear_deletion_sentinel_no_op_when_absent(self, kb_dir):\\n        \\\"\\\"\\\"Clearing when the marker is absent must be a silent no-op.\\n\\n        The create path always calls this defensively; raising would\\n        regress every fresh KB creation.\\n        \\\"\\\"\\\"\\n        from langflow.api.utils.kb_helpers import KBStorageHelper\\n\\n        # Should not raise even with no marker file present.\\n        KBStorageHelper.clear_deletion_sentinel(kb_dir)\\n\\n\\n# ===========================================================================\\n# Unit tests: lfx get_knowledge_bases filter parity\\n# ===========================================================================\\n\\n\\nclass TestLfxSentinelStringInSync:\\n    \\\"\\\"\\\"The lfx package inlines the sentinel filename string.\\n\\n    lfx is published independently of langflow and cannot import\\n    ``KB_DELETED_SENTINEL`` from langflow.api.utils.kb_helpers without\\n    pulling the whole API package into the standalone install.  This test\\n    pins the two literals together so a rename of the sentinel cannot\\n    silently desync the listing filter.\\n    \\\"\\\"\\\"\\n\\n    def test_sentinel_constant_matches_lfx_literal(self):\\n        from langflow.api.utils.kb_helpers import KB_DELETED_SENTINEL\\n\\n        # The lfx-side literal is intentionally inlined as the string\\n        # \\\".kb_deleted\\\" inside ``lfx.base.knowledge_bases.knowledge_base_utils``;\\n        # see the get_knowledge_bases() implementation.\\n        assert KB_DELETED_SENTINEL == \\\".kb_deleted\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_kubernetes_secrets.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"918bfcffc9597439fe272eebc506bc6caaa5f6a6f3dd58377c0903331faa9111\",\"content\":\"from base64 import b64encode\\nfrom unittest.mock import MagicMock\\nfrom uuid import UUID\\n\\nimport pytest\\nfrom kubernetes.client import V1ObjectMeta, V1Secret\\nfrom langflow.services.variable.kubernetes_secrets import KubernetesSecretManager, encode_user_id\\n\\n\\n@pytest.fixture\\ndef _mock_kube_config(mocker):\\n    mocker.patch(\\\"kubernetes.config.load_kube_config\\\")\\n    mocker.patch(\\\"kubernetes.config.load_incluster_config\\\")\\n\\n\\n@pytest.fixture\\ndef secret_manager(_mock_kube_config):\\n    return KubernetesSecretManager(namespace=\\\"test-namespace\\\")\\n\\n\\ndef test_create_secret(secret_manager, mocker):\\n    mocker.patch.object(\\n        secret_manager.core_api,\\n        \\\"create_namespaced_secret\\\",\\n        return_value=V1Secret(metadata=V1ObjectMeta(name=\\\"test-secret\\\")),\\n    )\\n\\n    secret_manager.create_secret(name=\\\"test-secret\\\", data={\\\"key\\\": \\\"value\\\"})\\n    secret_manager.core_api.create_namespaced_secret.assert_called_once_with(\\n        \\\"test-namespace\\\",\\n        V1Secret(\\n            api_version=\\\"v1\\\",\\n            kind=\\\"Secret\\\",\\n            metadata=V1ObjectMeta(name=\\\"test-secret\\\"),\\n            type=\\\"Opaque\\\",\\n            data={\\\"key\\\": b64encode(b\\\"value\\\").decode()},\\n        ),\\n    )\\n\\n\\ndef test_get_secret(secret_manager, mocker):\\n    mock_secret = V1Secret(data={\\\"key\\\": b64encode(b\\\"value\\\").decode()})\\n    mocker.patch.object(secret_manager.core_api, \\\"read_namespaced_secret\\\", return_value=mock_secret)\\n\\n    secret_data = secret_manager.get_secret(name=\\\"test-secret\\\")\\n    secret_manager.core_api.read_namespaced_secret.assert_called_once_with(\\\"test-secret\\\", \\\"test-namespace\\\")\\n    assert secret_data == {\\\"key\\\": \\\"value\\\"}\\n\\n\\ndef test_delete_secret(secret_manager, mocker):\\n    mocker.patch.object(secret_manager.core_api, \\\"delete_namespaced_secret\\\", return_value=MagicMock(status=\\\"Success\\\"))\\n\\n    secret_manager.delete_secret(name=\\\"test-secret\\\")\\n    secret_manager.core_api.delete_namespaced_secret.assert_called_once_with(\\\"test-secret\\\", \\\"test-namespace\\\")\\n\\n\\ndef test_encode_uuid():\\n    uuid = UUID(\\\"123e4567-e89b-12d3-a456-426614174000\\\")\\n    result = encode_user_id(uuid)\\n    assert result == \\\"uuid-123e4567-e89b-12d3-a456-426614174000\\\"\\n    assert len(result) < 253\\n    assert result[0].isalnum()\\n    assert result[-1].isalnum()\\n\\n\\ndef test_encode_string():\\n    string_id = \\\"user@example.com\\\"\\n    result = encode_user_id(string_id)\\n    # assert (result.isalnum() or '-' in result or '_' in result)\\n    assert len(result) < 253\\n    assert result[0].isalnum()\\n    assert result[-1].isalnum()\\n\\n\\ndef test_long_string():\\n    long_string = \\\"a\\\" * 300\\n    result = encode_user_id(long_string)\\n    assert len(result) <= 253\\n\\n\\ndef test_starts_with_non_alphanumeric():\\n    non_alnum_start = \\\"+user123\\\"\\n    result = encode_user_id(non_alnum_start)\\n    assert result[0].isalnum()\\n\\n\\ndef test_ends_with_non_alphanumeric():\\n    non_alnum_end = \\\"user123+\\\"\\n    result = encode_user_id(non_alnum_end)\\n    assert result[-1].isalnum()\\n\\n\\ndef test_email_address():\\n    email = \\\"User.Name@Example.com\\\"\\n    result = encode_user_id(email)\\n    assert result.isalnum() or \\\"-\\\" in result or \\\"_\\\" in result\\n    assert len(result) < 253\\n    assert result[0].isalnum()\\n    assert result[-1].isalnum()\\n\\n\\ndef test_uuid_case_insensitivity():\\n    uuid_upper = UUID(\\\"123E4567-E89B-12D3-A456-426614174000\\\")\\n    uuid_lower = UUID(\\\"123e4567-e89b-12d3-a456-426614174000\\\")\\n    result_upper = encode_user_id(uuid_upper)\\n    result_lower = encode_user_id(uuid_lower)\\n    assert result_upper == result_lower\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_lfx_bundles_extras.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d108747be841c424a8627e93c1c28aadce7f6c009d448bb48c4bb789b82617cb\",\"content\":\"\\\"\\\"\\\"Extras-drift guard for the ``lfx-bundles`` metapackage.\\n\\n``src/bundles/lfx-bundles/pyproject.toml`` carries one optional-dependency\\nextra per provider plus the *generated* ``all`` and ``all-no-torch`` aggregates\\nfor explicit opt-in installs such as ``lfx[bundles]``. These invariants are\\nmaintained by ``scripts/migrate/consolidate_bundles.py`` and must never drift\\nby hand-edit:\\n\\n    1. every provider directory has exactly one extra (PEP 685-normalized key),\\n       apart from explicit compatibility aliases for graduated providers,\\n    2. ``all`` is exactly the set of per-provider self-refs -- a provider\\n       missing from ``all`` silently drops its deps from explicit all-bundle\\n       installs,\\n    3. ``all-no-torch`` is exactly ``all`` minus the torch-pulling providers\\n       (``TORCH_EXTRAS``), giving a torch-free full-provider install,\\n    4. normalized extra keys are collision-free,\\n    5. the metapackage provider set stays disjoint from the graduated\\n       partner distributions (no double-ship; manifest would shadow),\\n    6. ALTK remains available on Python 3.14 while preserving its Intel macOS\\n       exclusion.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport re\\nfrom pathlib import Path\\n\\nfrom packaging.markers import default_environment\\nfrom packaging.requirements import Requirement\\n\\ntry:\\n    import tomllib\\nexcept ModuleNotFoundError:  # Python 3.10: tomllib is stdlib only on 3.11+\\n    import tomli as tomllib  # pytest guarantees tomli on <3.11\\n\\nREPO_ROOT = Path(__file__).resolve().parents[4]\\nMETAPACKAGE_DIR = REPO_ROOT / \\\"src\\\" / \\\"bundles\\\" / \\\"lfx-bundles\\\"\\nPROVIDERS_DIR = METAPACKAGE_DIR / \\\"src\\\" / \\\"lfx_bundles\\\"\\nBUNDLES_DIR = REPO_ROOT / \\\"src\\\" / \\\"bundles\\\"\\n\\n# Generated aggregate extras (not per-provider) -- kept in sync with\\n# scripts/migrate/consolidate_bundles.py. ``all`` pulls every provider;\\n# ``all-no-torch`` is ``all`` minus the torch-pulling providers (TORCH_EXTRAS).\\nAGGREGATE_EXTRAS = frozenset({\\\"all\\\", \\\"all-no-torch\\\"})\\nCOMPATIBILITY_EXTRAS = {\\n    \\\"azure\\\": [\\\"lfx-azure>=0.1.0,<1.0.0\\\"],\\n    \\\"google\\\": [\\\"lfx-google>=0.1.0,<1.0.0\\\"],\\n    \\\"ollama\\\": [\\\"lfx-ollama>=0.1.0,<1.0.0\\\"],\\n}\\nTORCH_EXTRAS = frozenset({\\\"cuga\\\", \\\"codeagents\\\"})\\n\\n\\ndef _normalize(name: str) -> str:\\n    \\\"\\\"\\\"PEP 685 extra-name normalization (matches consolidate_bundles.py).\\\"\\\"\\\"\\n    return re.sub(r\\\"[-_.]+\\\", \\\"-\\\", name).lower()\\n\\n\\ndef _load_extras() -> dict[str, list[str]]:\\n    with (METAPACKAGE_DIR / \\\"pyproject.toml\\\").open(\\\"rb\\\") as fh:\\n        return tomllib.load(fh)[\\\"project\\\"][\\\"optional-dependencies\\\"]\\n\\n\\ndef _provider_dirs() -> list[str]:\\n    return sorted(\\n        child.name for child in PROVIDERS_DIR.iterdir() if child.is_dir() and (child / \\\"__init__.py\\\").is_file()\\n    )\\n\\n\\ndef test_every_provider_has_an_extra_and_vice_versa() -> None:\\n    extras = _load_extras()\\n    extra_keys = set(extras) - AGGREGATE_EXTRAS - COMPATIBILITY_EXTRAS.keys()\\n    provider_keys = {_normalize(p) for p in _provider_dirs()}\\n    assert extra_keys == provider_keys, (\\n        f\\\"extras and provider dirs drifted: extras-only={sorted(extra_keys - provider_keys)}, \\\"\\n        f\\\"providers-only={sorted(provider_keys - extra_keys)}\\\"\\n    )\\n\\n\\ndef test_all_extra_is_exactly_the_per_provider_self_refs() -> None:\\n    extras = _load_extras()\\n    expected = {\\n        f\\\"lfx-bundles[{key}]\\\" for key in extras if key not in AGGREGATE_EXTRAS and key not in COMPATIBILITY_EXTRAS\\n    }\\n    actual = set(extras[\\\"all\\\"])\\n    assert actual == expected, (\\n        f\\\"generated `all` drifted: missing={sorted(expected - actual)}, stray={sorted(actual - expected)}\\\"\\n    )\\n\\n\\ndef test_all_no_torch_extra_is_all_minus_torch_providers() -> None:\\n    extras = _load_extras()\\n    expected = {\\n        f\\\"lfx-bundles[{key}]\\\"\\n        for key in extras\\n        if key not in AGGREGATE_EXTRAS and key not in TORCH_EXTRAS and key not in COMPATIBILITY_EXTRAS\\n    }\\n    actual = set(extras[\\\"all-no-torch\\\"])\\n    assert actual == expected, (\\n        f\\\"generated `all-no-torch` drifted: missing={sorted(expected - actual)}, stray={sorted(actual - expected)}\\\"\\n    )\\n\\n\\ndef test_graduated_compatibility_extras_are_explicit_and_not_aggregated() -> None:\\n    extras = _load_extras()\\n    assert {key: extras[key] for key in COMPATIBILITY_EXTRAS} == COMPATIBILITY_EXTRAS\\n    aggregate_requirements = {*extras[\\\"all\\\"], *extras[\\\"all-no-torch\\\"]}\\n    assert not {f\\\"lfx-bundles[{key}]\\\" for key in COMPATIBILITY_EXTRAS} & aggregate_requirements\\n\\n\\ndef test_normalized_extra_keys_are_collision_free() -> None:\\n    providers = _provider_dirs()\\n    normalized = [_normalize(p) for p in providers]\\n    dupes = {key for key in normalized if normalized.count(key) > 1}\\n    assert not dupes, f\\\"provider names collide after PEP 685 normalization: {sorted(dupes)}\\\"\\n\\n\\ndef test_metapackage_providers_disjoint_from_graduated_partners() -> None:\\n    \\\"\\\"\\\"A provider must ship from exactly one distribution.\\n\\n    Graduated ``lfx-<provider>`` packages are the manifest-shipping\\n    ``src/bundles/<provider>/`` workspace members (manifest shadows\\n    manifest-less, but double-shipping is still a packaging bug).\\n    \\\"\\\"\\\"\\n    partners = {\\n        child.name\\n        for child in BUNDLES_DIR.iterdi";
